import type { NextConfig } from "next";
// ISOLATED SANDBOX: no rewrites, no proxies, no external image hosts, no env passthrough.
// basePath serves the showcase under /ds on the existing sandbox hostname.
const nextConfig: NextConfig = {
  reactStrictMode: true,
  basePath: "/ds",
};
export default nextConfig;

content.content:
1	@import "tailwindcss";
2	
3	/* ============================================================================
4	   NXEON DESIGN SYSTEM — TOKENS
5	   Phase 2. Single source of truth. No component may declare a raw colour,
6	   a raw font size, a raw radius, a raw duration or a raw z-index.
7	
8	   Navy is the Nxeon environment: this system is deliberately dark-first and
9	   commits to one visual world rather than inverting into a light theme.
10	   Every value is declared here so a second theme remains possible later
11	   without touching a single component.
12	   ========================================================================= */
13	
14	@theme {
15	  /* ---- Surface layers -------------------------------------------------- */
16	  --color-base: #070b14;        /* page ground */
17	  --color-surface: #0c1220;     /* panels, containers */
18	  --color-raised: #131b2b;      /* owned objects */
19	  --color-interactive: #1b2437; /* hover, inputs, pressed */
20	  --color-plate: #05080f;       /* recessed technical data */
21	  --color-scrim: #03060c;       /* behind overlays */
22	
23	  /* ---- Hairlines. Blue-grey, never neutral grey ------------------------ */
24	  --color-hairline: #1e2839;
25	  --color-hairline-strong: #2c3a52;
26	
27	  /* ---- Text. Every value verified for AA on --color-surface ------------ */
28	  --color-ink: #e7edf6;           /* 15.6:1  primary */
29	  --color-ink-secondary: #a9b6ca; /*  9.2:1  secondary */
30	  --color-ink-muted: #8494ac;     /*  6.1:1  muted — replaces the 4.0:1 tone */
31	  --color-ink-disabled: #5b6880;  /*  3.3:1  disabled only, never information */
32	  --color-ink-inverse: #070b14;
33	
34	  /* ---- Signal. The brand accent, and the one action on screen ---------- */
35	  --color-signal: #1e63d6;        /* fill; white on it = 5.5:1 */
36	  --color-signal-hover: #2e7bf6;
37	  --color-signal-press: #1750b4;
38	  --color-signal-text: #6ba5ff;   /* 7.6:1  signal as text or icon */
39	  --color-signal-edge: #2e7bf6;
40	
41	  /* ---- Data. Charts, meters, topology. Never an action ----------------- */
42	  --color-data: #2bb3ce;
43	  --color-data-2: #6ba5ff;
44	  --color-data-3: #3fcb9e;
45	  --color-data-4: #f0b44a;
46	  --color-data-5: #a88bff;
47	
48	  /* ---- Semantic state. Separate from the accent, always -------------- */
49	  --color-success: #0e7a5c;
50	  --color-success-text: #3fcb9e;  /* 9.3:1 */
51	  --color-warning: #8a5d10;
52	  --color-warning-text: #f0b44a;  /* 11.0:1 */
53	  --color-danger: #a83226;
54	  --color-danger-text: #ff8a7d;   /* 8.3:1 */
55	  --color-info: #1e63d6;
56	  --color-info-text: #6ba5ff;
57	
58	  /* ---- Violet. Reserved: AI and Build surfaces only -------------------- */
59	  --color-ai: #6b4be8;
60	  --color-ai-text: #a88bff;       /* 6.9:1 */
61	
62	  /* ---- THE BRAND GRADIENT ---------------------------------------------
63	     Sampled from the Nxeon lockup: the mark runs blue -> violet. The ramp
64	     is extended to a magenta terminus so the brand gradient carries the
65	     magenta end you asked for while still matching the logo exactly.
66	     Three stops, one place. Change `brand-c` to dial the magenta. */
67	  --color-brand-a: #3b6be8;       /* logo blue, left of the mark */
68	  --color-brand-b: #7b3fef;       /* logo violet, right of the mark */
69	  --color-brand-c: #e5197e;       /* magenta terminus — swap for the exact hex */
70	
71	  /* ---- NEON --------------------------------------------------------
72	     Deliberate, and rationed. Neon is allowed on exactly three things:
73	     a live resource, the brand mark, and a primary brand moment such as
74	     the deploy action. It is never ambient and never decorative. */
75	  --color-neon-cyan: #34e6ff;
76	  --color-neon-magenta: #ff2f9a;
77	
78	  /* ---- Type ------------------------------------------------------------ */
79	  --font-display: var(--font-archivo), "Helvetica Neue", Arial, sans-serif;
80	  --font-sans: var(--font-plex-sans), ui-sans-serif, system-ui, sans-serif;
81	  --font-mono: var(--font-plex-mono), ui-monospace, "SFMono-Regular", Menlo, monospace;
82	
83	  /* Scale. Nothing below 12px, and 12px is reserved for tracked labels.
84	     The old portal's 10px and 11px steps do not exist here by design. */
85	  --text-display: 2.25rem;      --text-display--line-height: 1.04;  --text-display--letter-spacing: -0.028em;  --text-display--font-weight: 700;
86	  --text-h1: 1.75rem;           --text-h1--line-height: 1.12;       --text-h1--letter-spacing: -0.022em;       --text-h1--font-weight: 700;
87	  --text-h2: 1.375rem;          --text-h2--line-height: 1.2;        --text-h2--letter-spacing: -0.016em;       --text-h2--font-weight: 600;
88	  --text-h3: 1.0625rem;         --text-h3--line-height: 1.3;        --text-h3--letter-spacing: -0.008em;       --text-h3--font-weight: 600;
89	  --text-h4: 0.9375rem;         --text-h4--line-height: 1.35;       --text-h4--letter-spacing: 0em;            --text-h4--font-weight: 600;
90	  --text-body: 0.9375rem;       --text-body--line-height: 1.6;
91	  --text-body-sm: 0.875rem;     --text-body-sm--line-height: 1.55;
92	  --text-caption: 0.8125rem;    --text-caption--line-height: 1.5;
93	  --text-label: 0.75rem;        --text-label--line-height: 1.2;     --text-label--letter-spacing: 0.11em;      --text-label--font-weight: 600;
94	  --text-code: 0.875rem;        --text-code--line-height: 1.5;
95	  --text-metric: 1.75rem;       --text-metric--line-height: 1;      --text-metric--letter-spacing: -0.03em;    --text-metric--font-weight: 700;
96	  --text-metric-sm: 1.125rem;   --text-metric-sm--line-height: 1.1; --text-metric-sm--letter-spacing: -0.02em; --text-metric-sm--font-weight: 600;
97	
98	  /* ---- Radius. Small and deliberate. The notch is the object signature -- */
99	  --radius-xs: 2px;
100	  --radius-sm: 4px;
101	  --radius-md: 6px;
102	  --radius-lg: 10px;
103	  --radius-pill: 999px;
104	  --nx-notch: 15px;
105	
106	  /* ---- Elevation. Separation is by layer and hairline first ------------ */
107	  --shadow-plate: inset 0 1px 0 0 rgb(255 255 255 / 0.03);
108	  --shadow-raised: 0 1px 2px 0 rgb(0 0 0 / 0.4);
109	  --shadow-overlay: 0 24px 64px -20px rgb(0 0 0 / 0.75), 0 0 0 1px rgb(44 58 82 / 0.7);
110	  --shadow-dock: 0 -12px 32px -16px rgb(0 0 0 / 0.7);
111	
112	  /* ---- Glow. Rationed, and each one has a named owner ----------------- */
113	  --nx-glow-live: 0 0 0 1px rgb(63 203 158 / 0.35), 0 0 12px -2px rgb(63 203 158 / 0.45);
114	  --nx-glow-brand: 0 0 24px -6px rgb(123 63 239 / 0.55), 0 0 48px -18px rgb(229 25 126 / 0.4);
115	  --nx-glow-neon: 0 0 10px -1px rgb(52 230 255 / 0.55);
116	
117	  /* ---- Motion ---------------------------------------------------------- */
118	  --nx-dur-1: 120ms;   /* state: hover, press, colour */
119	  --nx-dur-2: 180ms;   /* movement: reveal, tab, row */
120	  --nx-dur-3: 240ms;   /* surface: drawer, modal, wizard */
121	  --nx-ease: cubic-bezier(0.2, 0, 0, 1);
122	  --nx-ease-out: cubic-bezier(0.16, 1, 0.3, 1);
123	  --nx-ease-in: cubic-bezier(0.7, 0, 0.84, 0);
124	
125	  /* ---- Z-index. The documented stacking contract. Nothing invents a tier */
126	  --nx-z-base: 0;
127	  --nx-z-raised: 10;
128	  --nx-z-sticky: 20;
129	  --nx-z-scrim: 30;   /* the drawer's backdrop sits BELOW the drawer */
130	  --nx-z-rail: 40;    /* ...and the drawer above it, or the nav is untappable */
131	  --nx-z-overlay: 50;
132	  --nx-z-toast: 60;
133	  --nx-z-tooltip: 70;
134	
135	  /* ---- Focus ----------------------------------------------------------- */
136	  --nx-focus-width: 2px;
137	  --nx-focus-offset: 2px;
138	
139	  /* ---- Breakpoints (Tailwind defaults, stated so they are a contract) --- */
140	  --breakpoint-sm: 40rem;
141	  --breakpoint-md: 48rem;
142	  --breakpoint-lg: 64rem;
143	  --breakpoint-xl: 80rem;
144	  --breakpoint-2xl: 96rem;
145	
146	  /* ---- Keyframes ------------------------------------------------------- */
147	  --animate-nx-filament: nx-filament 2.4s ease-in-out infinite;
148	  --animate-nx-rise: nx-rise var(--nx-dur-3) var(--nx-ease-out) both;
149	  --animate-nx-fade: nx-fade var(--nx-dur-2) var(--nx-ease) both;
150	  --animate-nx-slide-right: nx-slide-right var(--nx-dur-3) var(--nx-ease-out) both;
151	  --animate-nx-slide-left: nx-slide-left var(--nx-dur-3) var(--nx-ease-out) both;
152	  --animate-nx-check: nx-check var(--nx-dur-3) var(--nx-ease-out) both;
153	  --animate-nx-sweep: nx-sweep 1.4s linear infinite;
154	  --animate-nx-pulse: nx-pulse 2s ease-in-out infinite;
155	  --animate-nx-trace: nx-trace 2.6s ease-in-out infinite;
156	  --animate-nx-node: nx-node 2.4s ease-in-out infinite;
157	  --animate-nx-grad-drift: nx-grad-drift 9s ease-in-out infinite;
158	  --animate-nx-scan: nx-scan 2.2s var(--nx-ease) infinite;
159	}
160	
161	@keyframes nx-filament {
162	  0%, 100% { transform: translateY(-100%); }
163	  50%      { transform: translateY(100%); }
164	}
165	@keyframes nx-rise {
166	  from { opacity: 0; transform: translateY(6px); }
167	  to   { opacity: 1; transform: none; }
168	}
169	@keyframes nx-fade {
170	  from { opacity: 0; }
171	  to   { opacity: 1; }
172	}
173	@keyframes nx-slide-right {
174	  from { transform: translateX(100%); }
175	  to   { transform: none; }
176	}
177	@keyframes nx-slide-left {
178	  from { transform: translateX(-100%); }
179	  to   { transform: none; }
180	}
181	@keyframes nx-check {
182	  from { stroke-dashoffset: 22; }
183	  to   { stroke-dashoffset: 0; }
184	}
185	@keyframes nx-sweep {
186	  from { transform: translateX(-100%); }
187	  to   { transform: translateX(300%); }
188	}
189	@keyframes nx-pulse {
190	  0%, 100% { opacity: 1; }
191	  50%      { opacity: 0.45; }
192	}
193	/* A packet travelling a topology path. */
194	@keyframes nx-trace {
195	  0%   { stroke-dashoffset: 220; opacity: 0; }
196	  12%  { opacity: 1; }
197	  88%  { opacity: 1; }
198	  100% { stroke-dashoffset: 0; opacity: 0; }
199	}
200	/* A node breathing on the map. */
201	@keyframes nx-node {
202	  0%, 100% { r: 3;   opacity: 0.9; }
203	  50%      { r: 4.6; opacity: 0.5; }
204	}
205	/* Slow drift across a brand gradient — the only ambient motion allowed. */
206	@keyframes nx-grad-drift {
207	  0%, 100% { background-position: 0% 50%; }
208	  50%      { background-position: 100% 50%; }
209	}
210	/* A provisioning scan line. */
211	/* --- deployment loader primitives --- */
212	@keyframes nx-block-in {
213	  0%, 12%  { opacity: 0; transform: translateY(5px) scaleY(0.4); }
214	  26%, 88% { opacity: 1; transform: none; }
215	  100%     { opacity: 0.35; transform: none; }
216	}
217	@keyframes nx-scanline {
218	  0%   { transform: translateY(-8%); opacity: 0; }
219	  15%  { opacity: 1; }
220	  85%  { opacity: 1; }
221	  100% { transform: translateY(108%); opacity: 0; }
222	}
223	@keyframes nx-ring-out {
224	  0%   { transform: scale(0.25); opacity: 0.85; }
225	  100% { transform: scale(1); opacity: 0; }
226	}
227	@keyframes nx-drop-in {
228	  0%, 10%  { opacity: 0; transform: translate(0,-14px); }
229	  30%, 82% { opacity: 1; transform: none; }
230	  100%     { opacity: 0; transform: translate(0,6px); }
231	}
232	@keyframes nx-tick-on {
233	  0%, 40%   { opacity: 0.2; }
234	  55%, 100% { opacity: 1; }
235	}
236	@keyframes nx-deploy-sweep {
237	  0%   { transform: translateX(-130%) skewX(-12deg); }
238	  100% { transform: translateX(130%) skewX(-12deg); }
239	}
240	@keyframes nx-scan {
241	  0%   { transform: translateY(-100%); opacity: 0; }
242	  20%  { opacity: 1; }
243	  80%  { opacity: 1; }
244	  100% { transform: translateY(400%); opacity: 0; }
245	}
246	
247	/* ============================================================================
248	   BASE
249	   ========================================================================= */
250	@layer base {
251	  * { border-color: var(--color-hairline); }
252	
253	  html { -webkit-text-size-adjust: 100%; }
254	
255	  body {
256	    background-color: var(--color-base);
257	    color: var(--color-ink);
258	    font-family: var(--font-sans);
259	    font-size: var(--text-body);
260	    line-height: 1.6;
261	    -webkit-font-smoothing: antialiased;
262	    text-rendering: optimizeLegibility;
263	  }
264	
265	  /* Atmosphere: one very low-contrast field. It must disappear behind
266	     content — it is never a feature, and it never moves. */
267	  body::before {
268	    content: "";
269	    position: fixed;
270	    inset: 0;
271	    pointer-events: none;
272	    z-index: 0;
273	    background:
274	      radial-gradient(1100px 620px at 12% -8%, rgb(30 99 214 / 0.055), transparent 70%),
275	      radial-gradient(900px 520px at 100% 0%, rgb(43 179 206 / 0.035), transparent 70%);
276	  }
277	
278	  h1, h2, h3, h4, h5, h6 { font-family: var(--font-display); text-wrap: balance; }
279	
280	  /* One focus style, globally. The old portal had none. */
281	  :focus-visible {
282	    outline: var(--nx-focus-width) solid var(--color-signal-edge);
283	    outline-offset: var(--nx-focus-offset);
284	    border-radius: var(--radius-xs);
285	  }
286	  :focus:not(:focus-visible) { outline: none; }
287	
288	  ::selection { background: rgb(46 123 246 / 0.32); color: var(--color-ink); }
289	
290	  ::-webkit-scrollbar { width: 10px; height: 10px; }
291	  ::-webkit-scrollbar-track { background: var(--color-base); }
292	  ::-webkit-scrollbar-thumb {
293	    background: var(--color-hairline-strong);
294	    border-radius: var(--radius-pill);
295	    border: 2px solid var(--color-base);
296	  }
297	  ::-webkit-scrollbar-thumb:hover { background: #3a4a66; }
298	
299	  /* Numbers never jitter. */
300	  table, .nx-tabular { font-variant-numeric: tabular-nums; }
301	}
302	
303	/* ============================================================================
304	   THE FOUR SURFACE ARCHETYPES
305	   The whole point: a border means "separate object". It is spent by role.
306	   ========================================================================= */
307	@layer components {
308	
309	  /* 1 — OBJECT. A thing the customer owns.
310	     Two clipped layers, not a clipped border: the outer layer paints the
311	     hairline, the inner layer paints the surface 1px inside it. That gives
312	     a real stroke along the chamfer — a single clip-path would cut the
313	     border off and leave the notch reading as a rendering artifact. */
314	  .nx-object {
315	    --nx-object-edge: var(--color-hairline);
316	    position: relative;
317	    isolation: isolate;
318	    background-color: var(--nx-object-edge);
319	    box-shadow: var(--shadow-raised);
320	    clip-path: polygon(
321	      var(--nx-notch) 0, 100% 0, 100% 100%, 0 100%, 0 var(--nx-notch)
322	    );
323	    transition: background-color var(--nx-dur-1) var(--nx-ease);
324	  }
325	  .nx-object::before {
326	    content: "";
327	    position: absolute;
328	    inset: 1px;
329	    z-index: 0;
330	    background-color: var(--color-raised);
331	    clip-path: polygon(
332	      calc(var(--nx-notch) - 1px) 0, 100% 0, 100% 100%, 0 100%,
333	      0 calc(var(--nx-notch) - 1px)
334	    );
335	    transition: background-color var(--nx-dur-1) var(--nx-ease);
336	  }
337	  /* Content sits above the inner fill layer. */
338	  .nx-object > * { position: relative; z-index: 1; }
339	
340	  .nx-object-interactive:hover { --nx-object-edge: var(--color-hairline-strong); }
341	  .nx-object-interactive:hover::before { background-color: var(--color-interactive); }
342	
343	  /* Selected object: the chamfer picks up the brand ramp, so the corner
344	     carries the selection rather than a heavy border doing it. */
345	  .nx-object-selected { --nx-object-edge: var(--color-brand-b); }
346	  .nx-object-selected::before { background-color: color-mix(in oklab, var(--color-brand-b) 9%, var(--color-raised)); }
347	
348	  /* 2 — CONTAINER. Groups information without claiming to be an object. */
349	  .nx-container-surface {
350	    background-color: var(--color-surface);
351	    border: 1px solid var(--color-hairline);
352	    border-radius: var(--radius-lg);
353	  }
354	
355	  /* 3 — PLATE. Recessed. Technical values live here and nowhere else. */
356	  .nx-plate {
357	    background-color: var(--color-plate);
358	    border: 1px solid var(--color-hairline);
359	    border-radius: var(--radius-md);
360	    box-shadow: var(--shadow-plate);
361	    font-family: var(--font-mono);
362	    font-size: var(--text-code);
363	    color: var(--color-ink-secondary);
364	  }
365	
366	  /* 4 — RULE. A labelled hairline. The primary grouping device, and the
367	     reason most of these sections need no border at all. */
368	  .nx-rule {
369	    display: flex;
370	    align-items: center;
371	    gap: 0.7rem;
372	  }
373	  .nx-rule::after {
374	    content: "";
375	    flex: 1 1 auto;
376	    height: 1px;
377	    background-color: var(--color-hairline);
378	  }
379	  .nx-rule > .nx-rule-label {
380	    font-family: var(--font-display);
381	    font-size: var(--text-label);
382	    font-weight: 600;
383	    letter-spacing: 0.11em;
384	    text-transform: uppercase;
385	    color: var(--color-ink-muted);
386	    white-space: nowrap;
387	  }
388	
389	  /* ---- The status filament --------------------------------------------
390	     Starts where the notch ends, so the chamfer and the filament read as
391	     one deliberate corner treatment rather than two clashing devices. */
392	  .nx-filament {
393	    position: absolute;
394	    left: 1px; top: var(--nx-notch); bottom: 1px;
395	    width: 2px;
396	    z-index: 2;
397	    overflow: hidden;
398	    background-color: currentColor;
399	  }
400	  .nx-filament[data-live="true"] {
401	    box-shadow: var(--nx-glow-neon);
402	  }
403	  .nx-filament[data-live="true"]::after {
404	    content: "";
405	    position: absolute;
406	    inset: 0;
407	    background: linear-gradient(to bottom, transparent, rgb(255 255 255 / 0.95), transparent);
408	    animation: var(--animate-nx-filament);
409	  }
410	
411	  /* ---- Brand gradient utilities --------------------------------------- */
412	  .nx-grad-brand {
413	    background-image: linear-gradient(
414	      100deg,
415	      var(--color-brand-a) 0%,
416	      var(--color-brand-b) 52%,
417	      var(--color-brand-c) 100%
418	    );
419	  }
420	  .nx-grad-text {
421	    background-image: linear-gradient(
422	      100deg, var(--color-brand-a), var(--color-brand-b) 55%, var(--color-brand-c)
423	    );
424	    -webkit-background-clip: text;
425	    background-clip: text;
426	    color: transparent;
427	  }
428	  /* A 1px brand rule — the gradient as a hairline rather than a fill. */
429	  .nx-grad-rule {
430	    height: 1px;
431	    background-image: linear-gradient(
432	      90deg, transparent, var(--color-brand-a), var(--color-brand-b), var(--color-brand-c), transparent
433	    );
434	  }
435	
436	  /* ---- THE DEPLOY BUTTON ----------------------------------------------
437	     The hover behaviour kept verbatim from the production portal, because it
438	     is the one interaction the owner wants carried forward: an animated
439	     gradient shift, a one-shot shimmer sweep, a 1px lift, and an arrow nudge.
440	     Only the palette changes — it now rides the new brand ramp. */
441	  .nx-deploy {
442	    position: relative;
443	    overflow: hidden;
444	    border-radius: var(--radius-pill);
445	    color: #fff;
446	    background-image: linear-gradient(
447	      110deg,
448	      var(--color-brand-a), var(--color-brand-b), var(--color-neon-cyan),
449	      var(--color-brand-c), var(--color-brand-a)
450	    );
451	    background-size: 220% 100%;
452	    background-position: 0% 0;
453	    box-shadow: 0 8px 26px -8px rgb(123 63 239 / 0.55),
454	                0 4px 30px -10px rgb(229 25 126 / 0.45),
455	                inset 0 1px 0 0 rgb(255 255 255 / 0.18);
456	    transition: transform 200ms ease, box-shadow 200ms ease, background-position 600ms ease;
457	  }
458	  .nx-deploy:hover {
459	    transform: translateY(-1px);
460	    background-position: 100% 0;
461	    box-shadow: 0 12px 34px -8px rgb(123 63 239 / 0.7),
462	                0 8px 40px -10px rgb(229 25 126 / 0.6),
463	                inset 0 1px 0 0 rgb(255 255 255 / 0.25);
464	  }
465	  .nx-deploy::before {
466	    content: "";
467	    position: absolute;
468	    inset-block: 0;
469	    left: 0;
470	    width: 60%;
471	    pointer-events: none;
472	    background: linear-gradient(90deg, transparent, rgb(255 255 255 / 0.38), transparent);
473	    transform: translateX(-130%) skewX(-12deg);
474	  }
475	  .nx-deploy:hover::before { animation: nx-deploy-sweep 750ms ease; }
476	  .nx-deploy .nx-arrow { transition: transform 250ms ease; }
477	  .nx-deploy:hover .nx-arrow { transform: translateX(3px); }
478	
479	  /* ---- GLOW ------------------------------------------------------------
480	     Glow is a property of importance, not decoration. Three levels, and a
481	     surface may carry at most one. */
482	  .nx-glow-soft {
483	    box-shadow: 0 0 0 1px rgb(123 63 239 / 0.12),
484	                0 18px 50px -28px rgb(123 63 239 / 0.55);
485	  }
486	  .nx-glow-card {
487	    box-shadow: 0 0 0 1px rgb(123 63 239 / 0.16),
488	                0 20px 60px -30px rgb(123 63 239 / 0.7),
489	                0 10px 40px -26px rgb(229 25 126 / 0.45);
490	  }
491	  .nx-glow-hero {
492	    box-shadow: 0 0 0 1px rgb(123 63 239 / 0.2),
493	                0 30px 90px -40px rgb(123 63 239 / 0.8),
494	                0 20px 70px -34px rgb(229 25 126 / 0.6),
495	                inset 0 1px 0 0 rgb(255 255 255 / 0.06);
496	  }
497	  /* A card that lifts and lights on hover. */
498	  .nx-lift {
499	    transition: transform var(--nx-dur-2) var(--nx-ease),
500	                box-shadow var(--nx-dur-2) var(--nx-ease);
501	  }
502	  .nx-lift:hover {
503	    transform: translateY(-2px);
504	    box-shadow: 0 0 0 1px rgb(123 63 239 / 0.22),
505	                0 24px 60px -28px rgb(123 63 239 / 0.75),
506	                0 12px 44px -26px rgb(229 25 126 / 0.5);
507	  }
508	  /* A hero surface: gradient hairline on top, aura behind. */
509	  .nx-hero {
510	    position: relative;
511	    isolation: isolate;
512	  }
513	  .nx-hero::after {
514	    content: "";
515	    position: absolute;
516	    inset: -30% -10% auto -10%;
517	    height: 70%;
518	    z-index: -1;
519	    pointer-events: none;
520	    background:
521	      radial-gradient(50% 60% at 22% 40%, rgb(59 107 232 / 0.28), transparent 70%),
522	      radial-gradient(45% 55% at 78% 30%, rgb(229 25 126 / 0.22), transparent 70%);
523	    filter: blur(6px);
524	  }
525	
526	  /* Primary brand action. The sweep is the one place a gradient moves. */
527	  .nx-cta {
528	    position: relative;
529	    overflow: hidden;
530	    background-image: linear-gradient(
531	      100deg, var(--color-brand-a), var(--color-brand-b) 55%, var(--color-brand-c)
532	    );
533	    box-shadow: var(--nx-glow-brand);
534	  }
535	  .nx-cta::after {
536	    content: "";
537	    position: absolute;
538	    inset: 0;
539	    background: linear-gradient(100deg, transparent 20%, rgb(255 255 255 / 0.22), transparent 80%);
540	    transform: translateX(-120%);
541	  }
542	  .nx-cta:hover::after { animation: nx-sweep 900ms var(--nx-ease) 1; }
543	
544	  /* ---- Precision grid: the infrastructure backdrop ---------------------
545	     A drawn field, not a decorative blob. Used behind topology and brand
546	     moments only, and it never sits under running text. */
547	  .nx-grid-field {
548	    background-image:
549	      linear-gradient(to right, rgb(123 63 239 / 0.055) 1px, transparent 1px),
550	      linear-gradient(to bottom, rgb(123 63 239 / 0.055) 1px, transparent 1px);
551	    background-size: 28px 28px;
552	  }
553	  .nx-grid-mask {
554	    -webkit-mask-image: radial-gradient(120% 90% at 50% 0%, #000 30%, transparent 78%);
555	    mask-image: radial-gradient(120% 90% at 50% 0%, #000 30%, transparent 78%);
556	  }
557	
558	  /* ---- Focus ring used inside composite controls ----------------------- */
559	  .nx-ring-focus:focus-within {
560	    outline: var(--nx-focus-width) solid var(--color-signal-edge);
561	    outline-offset: var(--nx-focus-offset);
562	  }
563	}
564	
565	/* ============================================================================
566	   REDUCED MOTION
567	   Global by default; nothing opts back in except opacity. The old portal
568	   guarded 8 of 69 animations — here the default is off.
569	   ========================================================================= */
570	/* Coarse pointers get a 44px minimum on every control, without inflating
571	   the same control on a desktop where a cursor is precise. */
572	@media (pointer: coarse) {
573	  button, [role="switch"], a[role="button"], summary {
574	    min-height: 44px;
575	  }
576	  button.nx-inline, .nx-inline button { min-height: 0; }
577	}
578	
579	@media (prefers-reduced-motion: reduce) {
580	  *, *::before, *::after {
581	    animation-duration: 0.001ms !important;
582	    animation-iteration-count: 1 !important;
583	    transition-duration: 0.001ms !important;
584	    scroll-behavior: auto !important;
585	  }
586	}
587

file.content:
@import "tailwindcss";

/* ============================================================================
   NXEON DESIGN SYSTEM — TOKENS
   Phase 2. Single source of truth. No component may declare a raw colour,
   a raw font size, a raw radius, a raw duration or a raw z-index.

   Navy is the Nxeon environment: this system is deliberately dark-first and
   commits to one visual world rather than inverting into a light theme.
   Every value is declared here so a second theme remains possible later
   without touching a single component.
   ========================================================================= */

@theme {
  /* ---- Surface layers -------------------------------------------------- */
  --color-base: #070b14;        /* page ground */
  --color-surface: #0c1220;     /* panels, containers */
  --color-raised: #131b2b;      /* owned objects */
  --color-interactive: #1b2437; /* hover, inputs, pressed */
  --color-plate: #05080f;       /* recessed technical data */
  --color-scrim: #03060c;       /* behind overlays */

  /* ---- Hairlines. Blue-grey, never neutral grey ------------------------ */
  --color-hairline: #1e2839;
  --color-hairline-strong: #2c3a52;

  /* ---- Text. Every value verified for AA on --color-surface ------------ */
  --color-ink: #e7edf6;           /* 15.6:1  primary */
  --color-ink-secondary: #a9b6ca; /*  9.2:1  secondary */
  --color-ink-muted: #8494ac;     /*  6.1:1  muted — replaces the 4.0:1 tone */
  --color-ink-disabled: #5b6880;  /*  3.3:1  disabled only, never information */
  --color-ink-inverse: #070b14;

  /* ---- Signal. The brand accent, and the one action on screen ---------- */
  --color-signal: #1e63d6;        /* fill; white on it = 5.5:1 */
  --color-signal-hover: #2e7bf6;
  --color-signal-press: #1750b4;
  --color-signal-text: #6ba5ff;   /* 7.6:1  signal as text or icon */
  --color-signal-edge: #2e7bf6;

  /* ---- Data. Charts, meters, topology. Never an action ----------------- */
  --color-data: #2bb3ce;
  --color-data-2: #6ba5ff;
  --color-data-3: #3fcb9e;
  --color-data-4: #f0b44a;
  --color-data-5: #a88bff;

  /* ---- Semantic state. Separate from the accent, always -------------- */
  --color-success: #0e7a5c;
  --color-success-text: #3fcb9e;  /* 9.3:1 */
  --color-warning: #8a5d10;
  --color-warning-text: #f0b44a;  /* 11.0:1 */
  --color-danger: #a83226;
  --color-danger-text: #ff8a7d;   /* 8.3:1 */
  --color-info: #1e63d6;
  --color-info-text: #6ba5ff;

  /* ---- Violet. Reserved: AI and Build surfaces only -------------------- */
  --color-ai: #6b4be8;
  --color-ai-text: #a88bff;       /* 6.9:1 */

  /* ---- THE BRAND GRADIENT ---------------------------------------------
     Sampled from the Nxeon lockup: the mark runs blue -> violet. The ramp
     is extended to a magenta terminus so the brand gradient carries the
     magenta end you asked for while still matching the logo exactly.
     Three stops, one place. Change `brand-c` to dial the magenta. */
  --color-brand-a: #3b6be8;       /* logo blue, left of the mark */
  --color-brand-b: #7b3fef;       /* logo violet, right of the mark */
  --color-brand-c: #e5197e;       /* magenta terminus — swap for the exact hex */

  /* ---- NEON --------------------------------------------------------
     Deliberate, and rationed. Neon is allowed on exactly three things:
     a live resource, the brand mark, and a primary brand moment such as
     the deploy action. It is never ambient and never decorative. */
  --color-neon-cyan: #34e6ff;
  --color-neon-magenta: #ff2f9a;

  /* ---- Type ------------------------------------------------------------ */
  --font-display: var(--font-archivo), "Helvetica Neue", Arial, sans-serif;
  --font-sans: var(--font-plex-sans), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-plex-mono), ui-monospace, "SFMono-Regular", Menlo, monospace;

  /* Scale. Nothing below 12px, and 12px is reserved for tracked labels.
     The old portal's 10px and 11px steps do not exist here by design. */
  --text-display: 2.25rem;      --text-display--line-height: 1.04;  --text-display--letter-spacing: -0.028em;  --text-display--font-weight: 700;
  --text-h1: 1.75rem;           --text-h1--line-height: 1.12;       --text-h1--letter-spacing: -0.022em;       --text-h1--font-weight: 700;
  --text-h2: 1.375rem;          --text-h2--line-height: 1.2;        --text-h2--letter-spacing: -0.016em;       --text-h2--font-weight: 600;
  --text-h3: 1.0625rem;         --text-h3--line-height: 1.3;        --text-h3--letter-spacing: -0.008em;       --text-h3--font-weight: 600;
  --text-h4: 0.9375rem;         --text-h4--line-height: 1.35;       --text-h4--letter-spacing: 0em;            --text-h4--font-weight: 600;
  --text-body: 0.9375rem;       --text-body--line-height: 1.6;
  --text-body-sm: 0.875rem;     --text-body-sm--line-height: 1.55;
  --text-caption: 0.8125rem;    --text-caption--line-height: 1.5;
  --text-label: 0.75rem;        --text-label--line-height: 1.2;     --text-label--letter-spacing: 0.11em;      --text-label--font-weight: 600;
  --text-code: 0.875rem;        --text-code--line-height: 1.5;
  --text-metric: 1.75rem;       --text-metric--line-height: 1;      --text-metric--letter-spacing: -0.03em;    --text-metric--font-weight: 700;
  --text-metric-sm: 1.125rem;   --text-metric-sm--line-height: 1.1; --text-metric-sm--letter-spacing: -0.02em; --text-metric-sm--font-weight: 600;

  /* ---- Radius. Small and deliberate. The notch is the object signature -- */
  --radius-xs: 2px;
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 10px;
  --radius-pill: 999px;
  --nx-notch: 15px;

  /* ---- Elevation. Separation is by layer and hairline first ------------ */
  --shadow-plate: inset 0 1px 0 0 rgb(255 255 255 / 0.03);
  --shadow-raised: 0 1px 2px 0 rgb(0 0 0 / 0.4);
  --shadow-overlay: 0 24px 64px -20px rgb(0 0 0 / 0.75), 0 0 0 1px rgb(44 58 82 / 0.7);
  --shadow-dock: 0 -12px 32px -16px rgb(0 0 0 / 0.7);

  /* ---- Glow. Rationed, and each one has a named owner ----------------- */
  --nx-glow-live: 0 0 0 1px rgb(63 203 158 / 0.35), 0 0 12px -2px rgb(63 203 158 / 0.45);
  --nx-glow-brand: 0 0 24px -6px rgb(123 63 239 / 0.55), 0 0 48px -18px rgb(229 25 126 / 0.4);
  --nx-glow-neon: 0 0 10px -1px rgb(52 230 255 / 0.55);

  /* ---- Motion ---------------------------------------------------------- */
  --nx-dur-1: 120ms;   /* state: hover, press, colour */
  --nx-dur-2: 180ms;   /* movement: reveal, tab, row */
  --nx-dur-3: 240ms;   /* surface: drawer, modal, wizard */
  --nx-ease: cubic-bezier(0.2, 0, 0, 1);
  --nx-ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --nx-ease-in: cubic-bezier(0.7, 0, 0.84, 0);

  /* ---- Z-index. The documented stacking contract. Nothing invents a tier */
  --nx-z-base: 0;
  --nx-z-raised: 10;
  --nx-z-sticky: 20;
  --nx-z-scrim: 30;   /* the drawer's backdrop sits BELOW the drawer */
  --nx-z-rail: 40;    /* ...and the drawer above it, or the nav is untappable */
  --nx-z-overlay: 50;
  --nx-z-toast: 60;
  --nx-z-tooltip: 70;

  /* ---- Focus ----------------------------------------------------------- */
  --nx-focus-width: 2px;
  --nx-focus-offset: 2px;

  /* ---- Breakpoints (Tailwind defaults, stated so they are a contract) --- */
  --breakpoint-sm: 40rem;
  --breakpoint-md: 48rem;
  --breakpoint-lg: 64rem;
  --breakpoint-xl: 80rem;
  --breakpoint-2xl: 96rem;

  /* ---- Keyframes ------------------------------------------------------- */
  --animate-nx-filament: nx-filament 2.4s ease-in-out infinite;
  --animate-nx-rise: nx-rise var(--nx-dur-3) var(--nx-ease-out) both;
  --animate-nx-fade: nx-fade var(--nx-dur-2) var(--nx-ease) both;
  --animate-nx-slide-right: nx-slide-right var(--nx-dur-3) var(--nx-ease-out) both;
  --animate-nx-slide-left: nx-slide-left var(--nx-dur-3) var(--nx-ease-out) both;
  --animate-nx-check: nx-check var(--nx-dur-3) var(--nx-ease-out) both;
  --animate-nx-sweep: nx-sweep 1.4s linear infinite;
  --animate-nx-pulse: nx-pulse 2s ease-in-out infinite;
  --animate-nx-trace: nx-trace 2.6s ease-in-out infinite;
  --animate-nx-node: nx-node 2.4s ease-in-out infinite;
  --animate-nx-grad-drift: nx-grad-drift 9s ease-in-out infinite;
  --animate-nx-scan: nx-scan 2.2s var(--nx-ease) infinite;
}

@keyframes nx-filament {
  0%, 100% { transform: translateY(-100%); }
  50%      { transform: translateY(100%); }
}
@keyframes nx-rise {
  from { opacity: 0; transform: translateY(6px); }
  to   { opacity: 1; transform: none; }
}
@keyframes nx-fade {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes nx-slide-right {
  from { transform: translateX(100%); }
  to   { transform: none; }
}
@keyframes nx-slide-left {
  from { transform: translateX(-100%); }
  to   { transform: none; }
}
@keyframes nx-check {
  from { stroke-dashoffset: 22; }
  to   { stroke-dashoffset: 0; }
}
@keyframes nx-sweep {
  from { transform: translateX(-100%); }
  to   { transform: translateX(300%); }
}
@keyframes nx-pulse {
  0%, 100% { opacity: 1; }
  50%      { opacity: 0.45; }
}
/* A packet travelling a topology path. */
@keyframes nx-trace {
  0%   { stroke-dashoffset: 220; opacity: 0; }
  12%  { opacity: 1; }
  88%  { opacity: 1; }
  100% { stroke-dashoffset: 0; opacity: 0; }
}
/* A node breathing on the map. */
@keyframes nx-node {
  0%, 100% { r: 3;   opacity: 0.9; }
  50%      { r: 4.6; opacity: 0.5; }
}
/* Slow drift across a brand gradient — the only ambient motion allowed. */
@keyframes nx-grad-drift {
  0%, 100% { background-position: 0% 50%; }
  50%      { background-position: 100% 50%; }
}
/* A provisioning scan line. */
/* --- deployment loader primitives --- */
@keyframes nx-block-in {
  0%, 12%  { opacity: 0; transform: translateY(5px) scaleY(0.4); }
  26%, 88% { opacity: 1; transform: none; }
  100%     { opacity: 0.35; transform: none; }
}
@keyframes nx-scanline {
  0%   { transform: translateY(-8%); opacity: 0; }
  15%  { opacity: 1; }
  85%  { opacity: 1; }
  100% { transform: translateY(108%); opacity: 0; }
}
@keyframes nx-ring-out {
  0%   { transform: scale(0.25); opacity: 0.85; }
  100% { transform: scale(1); opacity: 0; }
}
@keyframes nx-drop-in {
  0%, 10%  { opacity: 0; transform: translate(0,-14px); }
  30%, 82% { opacity: 1; transform: none; }
  100%     { opacity: 0; transform: translate(0,6px); }
}
@keyframes nx-tick-on {
  0%, 40%   { opacity: 0.2; }
  55%, 100% { opacity: 1; }
}
@keyframes nx-deploy-sweep {
  0%   { transform: translateX(-130%) skewX(-12deg); }
  100% { transform: translateX(130%) skewX(-12deg); }
}
@keyframes nx-scan {
  0%   { transform: translateY(-100%); opacity: 0; }
  20%  { opacity: 1; }
  80%  { opacity: 1; }
  100% { transform: translateY(400%); opacity: 0; }
}

/* ============================================================================
   BASE
   ========================================================================= */
@layer base {
  * { border-color: var(--color-hairline); }

  html { -webkit-text-size-adjust: 100%; }

  body {
    background-color: var(--color-base);
    color: var(--color-ink);
    font-family: var(--font-sans);
    font-size: var(--text-body);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }

  /* Atmosphere: one very low-contrast field. It must disappear behind
     content — it is never a feature, and it never moves. */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 0;
    background:
      radial-gradient(1100px 620px at 12% -8%, rgb(30 99 214 / 0.055), transparent 70%),
      radial-gradient(900px 520px at 100% 0%, rgb(43 179 206 / 0.035), transparent 70%);
  }

  h1, h2, h3, h4, h5, h6 { font-family: var(--font-display); text-wrap: balance; }

  /* One focus style, globally. The old portal had none. */
  :focus-visible {
    outline: var(--nx-focus-width) solid var(--color-signal-edge);
    outline-offset: var(--nx-focus-offset);
    border-radius: var(--radius-xs);
  }
  :focus:not(:focus-visible) { outline: none; }

  ::selection { background: rgb(46 123 246 / 0.32); color: var(--color-ink); }

  ::-webkit-scrollbar { width: 10px; height: 10px; }
  ::-webkit-scrollbar-track { background: var(--color-base); }
  ::-webkit-scrollbar-thumb {
    background: var(--color-hairline-strong);
    border-radius: var(--radius-pill);
    border: 2px solid var(--color-base);
  }
  ::-webkit-scrollbar-thumb:hover { background: #3a4a66; }

  /* Numbers never jitter. */
  table, .nx-tabular { font-variant-numeric: tabular-nums; }
}

/* ============================================================================
   THE FOUR SURFACE ARCHETYPES
   The whole point: a border means "separate object". It is spent by role.
   ========================================================================= */
@layer components {

  /* 1 — OBJECT. A thing the customer owns.
     Two clipped layers, not a clipped border: the outer layer paints the
     hairline, the inner layer paints the surface 1px inside it. That gives
     a real stroke along the chamfer — a single clip-path would cut the
     border off and leave the notch reading as a rendering artifact. */
  .nx-object {
    --nx-object-edge: var(--color-hairline);
    position: relative;
    isolation: isolate;
    background-color: var(--nx-object-edge);
    box-shadow: var(--shadow-raised);
    clip-path: polygon(
      var(--nx-notch) 0, 100% 0, 100% 100%, 0 100%, 0 var(--nx-notch)
    );
    transition: background-color var(--nx-dur-1) var(--nx-ease);
  }
  .nx-object::before {
    content: "";
    position: absolute;
    inset: 1px;
    z-index: 0;
    background-color: var(--color-raised);
    clip-path: polygon(
      calc(var(--nx-notch) - 1px) 0, 100% 0, 100% 100%, 0 100%,
      0 calc(var(--nx-notch) - 1px)
    );
    transition: background-color var(--nx-dur-1) var(--nx-ease);
  }
  /* Content sits above the inner fill layer. */
  .nx-object > * { position: relative; z-index: 1; }

  .nx-object-interactive:hover { --nx-object-edge: var(--color-hairline-strong); }
  .nx-object-interactive:hover::before { background-color: var(--color-interactive); }

  /* Selected object: the chamfer picks up the brand ramp, so the corner
     carries the selection rather than a heavy border doing it. */
  .nx-object-selected { --nx-object-edge: var(--color-brand-b); }
  .nx-object-selected::before { background-color: color-mix(in oklab, var(--color-brand-b) 9%, var(--color-raised)); }

  /* 2 — CONTAINER. Groups information without claiming to be an object. */
  .nx-container-surface {
    background-color: var(--color-surface);
    border: 1px solid var(--color-hairline);
    border-radius: var(--radius-lg);
  }

  /* 3 — PLATE. Recessed. Technical values live here and nowhere else. */
  .nx-plate {
    background-color: var(--color-plate);
    border: 1px solid var(--color-hairline);
    border-radius: var(--radius-md);
    box-shadow: var(--shadow-plate);
    font-family: var(--font-mono);
    font-size: var(--text-code);
    color: var(--color-ink-secondary);
  }

  /* 4 — RULE. A labelled hairline. The primary grouping device, and the
     reason most of these sections need no border at all. */
  .nx-rule {
    display: flex;
    align-items: center;
    gap: 0.7rem;
  }
  .nx-rule::after {
    content: "";
    flex: 1 1 auto;
    height: 1px;
    background-color: var(--color-hairline);
  }
  .nx-rule > .nx-rule-label {
    font-family: var(--font-display);
    font-size: var(--text-label);
    font-weight: 600;
    letter-spacing: 0.11em;
    text-transform: uppercase;
    color: var(--color-ink-muted);
    white-space: nowrap;
  }

  /* ---- The status filament --------------------------------------------
     Starts where the notch ends, so the chamfer and the filament read as
     one deliberate corner treatment rather than two clashing devices. */
  .nx-filament {
    position: absolute;
    left: 1px; top: var(--nx-notch); bottom: 1px;
    width: 2px;
    z-index: 2;
    overflow: hidden;
    background-color: currentColor;
  }
  .nx-filament[data-live="true"] {
    box-shadow: var(--nx-glow-neon);
  }
  .nx-filament[data-live="true"]::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(to bottom, transparent, rgb(255 255 255 / 0.95), transparent);
    animation: var(--animate-nx-filament);
  }

  /* ---- Brand gradient utilities --------------------------------------- */
  .nx-grad-brand {
    background-image: linear-gradient(
      100deg,
      var(--color-brand-a) 0%,
      var(--color-brand-b) 52%,
      var(--color-brand-c) 100%
    );
  }
  .nx-grad-text {
    background-image: linear-gradient(
      100deg, var(--color-brand-a), var(--color-brand-b) 55%, var(--color-brand-c)
    );
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }
  /* A 1px brand rule — the gradient as a hairline rather than a fill. */
  .nx-grad-rule {
    height: 1px;
    background-image: linear-gradient(
      90deg, transparent, var(--color-brand-a), var(--color-brand-b), var(--color-brand-c), transparent
    );
  }

  /* ---- THE DEPLOY BUTTON ----------------------------------------------
     The hover behaviour kept verbatim from the production portal, because it
     is the one interaction the owner wants carried forward: an animated
     gradient shift, a one-shot shimmer sweep, a 1px lift, and an arrow nudge.
     Only the palette changes — it now rides the new brand ramp. */
  .nx-deploy {
    position: relative;
    overflow: hidden;
    border-radius: var(--radius-pill);
    color: #fff;
    background-image: linear-gradient(
      110deg,
      var(--color-brand-a), var(--color-brand-b), var(--color-neon-cyan),
      var(--color-brand-c), var(--color-brand-a)
    );
    background-size: 220% 100%;
    background-position: 0% 0;
    box-shadow: 0 8px 26px -8px rgb(123 63 239 / 0.55),
                0 4px 30px -10px rgb(229 25 126 / 0.45),
                inset 0 1px 0 0 rgb(255 255 255 / 0.18);
    transition: transform 200ms ease, box-shadow 200ms ease, background-position 600ms ease;
  }
  .nx-deploy:hover {
    transform: translateY(-1px);
    background-position: 100% 0;
    box-shadow: 0 12px 34px -8px rgb(123 63 239 / 0.7),
                0 8px 40px -10px rgb(229 25 126 / 0.6),
                inset 0 1px 0 0 rgb(255 255 255 / 0.25);
  }
  .nx-deploy::before {
    content: "";
    position: absolute;
    inset-block: 0;
    left: 0;
    width: 60%;
    pointer-events: none;
    background: linear-gradient(90deg, transparent, rgb(255 255 255 / 0.38), transparent);
    transform: translateX(-130%) skewX(-12deg);
  }
  .nx-deploy:hover::before { animation: nx-deploy-sweep 750ms ease; }
  .nx-deploy .nx-arrow { transition: transform 250ms ease; }
  .nx-deploy:hover .nx-arrow { transform: translateX(3px); }

  /* ---- GLOW ------------------------------------------------------------
     Glow is a property of importance, not decoration. Three levels, and a
     surface may carry at most one. */
  .nx-glow-soft {
    box-shadow: 0 0 0 1px rgb(123 63 239 / 0.12),
                0 18px 50px -28px rgb(123 63 239 / 0.55);
  }
  .nx-glow-card {
    box-shadow: 0 0 0 1px rgb(123 63 239 / 0.16),
                0 20px 60px -30px rgb(123 63 239 / 0.7),
                0 10px 40px -26px rgb(229 25 126 / 0.45);
  }
  .nx-glow-hero {
    box-shadow: 0 0 0 1px rgb(123 63 239 / 0.2),
                0 30px 90px -40px rgb(123 63 239 / 0.8),
                0 20px 70px -34px rgb(229 25 126 / 0.6),
                inset 0 1px 0 0 rgb(255 255 255 / 0.06);
  }
  /* A card that lifts and lights on hover. */
  .nx-lift {
    transition: transform var(--nx-dur-2) var(--nx-ease),
                box-shadow var(--nx-dur-2) var(--nx-ease);
  }
  .nx-lift:hover {
    transform: translateY(-2px);
    box-shadow: 0 0 0 1px rgb(123 63 239 / 0.22),
                0 24px 60px -28px rgb(123 63 239 / 0.75),
                0 12px 44px -26px rgb(229 25 126 / 0.5);
  }
  /* A hero surface: gradient hairline on top, aura behind. */
  .nx-hero {
    position: relative;
    isolation: isolate;
  }
  .nx-hero::after {
    content: "";
    position: absolute;
    inset: -30% -10% auto -10%;
    height: 70%;
    z-index: -1;
    pointer-events: none;
    background:
      radial-gradient(50% 60% at 22% 40%, rgb(59 107 232 / 0.28), transparent 70%),
      radial-gradient(45% 55% at 78% 30%, rgb(229 25 126 / 0.22), transparent 70%);
    filter: blur(6px);
  }

  /* Primary brand action. The sweep is the one place a gradient moves. */
  .nx-cta {
    position: relative;
    overflow: hidden;
    background-image: linear-gradient(
      100deg, var(--color-brand-a), var(--color-brand-b) 55%, var(--color-brand-c)
    );
    box-shadow: var(--nx-glow-brand);
  }
  .nx-cta::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(100deg, transparent 20%, rgb(255 255 255 / 0.22), transparent 80%);
    transform: translateX(-120%);
  }
  .nx-cta:hover::after { animation: nx-sweep 900ms var(--nx-ease) 1; }

  /* ---- Precision grid: the infrastructure backdrop ---------------------
     A drawn field, not a decorative blob. Used behind topology and brand
     moments only, and it never sits under running text. */
  .nx-grid-field {
    background-image:
      linear-gradient(to right, rgb(123 63 239 / 0.055) 1px, transparent 1px),
      linear-gradient(to bottom, rgb(123 63 239 / 0.055) 1px, transparent 1px);
    background-size: 28px 28px;
  }
  .nx-grid-mask {
    -webkit-mask-image: radial-gradient(120% 90% at 50% 0%, #000 30%, transparent 78%);
    mask-image: radial-gradient(120% 90% at 50% 0%, #000 30%, transparent 78%);
  }

  /* ---- Focus ring used inside composite controls ----------------------- */
  .nx-ring-focus:focus-within {
    outline: var(--nx-focus-width) solid var(--color-signal-edge);
    outline-offset: var(--nx-focus-offset);
  }
}

/* ============================================================================
   REDUCED MOTION
   Global by default; nothing opts back in except opacity. The old portal
   guarded 8 of 69 animations — here the default is off.
   ========================================================================= */
/* Coarse pointers get a 44px minimum on every control, without inflating
   the same control on a desktop where a cursor is precise. */
@media (pointer: coarse) {
  button, [role="switch"], a[role="button"], summary {
    min-height: 44px;
  }
  button.nx-inline, .nx-inline button { min-height: 0; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

