/* ================================================================ LADDER */
const LADDER: string[] = [
  "Allocating your server",
  "Configuring the network",
  "Starting your server",
  "Booting the operating system",
  "Waiting for network access",
];

export function Ladder() {
  const [at, setAt] = useState(1);
  const [secs, setSecs] = useState(38);
  useEffect(() => {
    const t = window.setInterval(() => setSecs((s) => s + 1), 1000);
    return () => window.clearInterval(t);
  }, []);

  const rungs: Rung[] = LADDER.map((label, i) => ({
    label, state: i < at ? "done" : i === at ? "active" : "pending",
  }));
  const mm = String(Math.floor(secs / 60)).padStart(2, "0");
  const ss = String(secs % 60).padStart(2, "0");

  return (
    <>
      <PageHeader
        eyebrow="Patterns"
        title="Deployment ladder"
        description="The signature post-payment moment, and the pattern with the strictest rule in the system: it may never claim more than the backend knows."
      />

      {/* The brand moment: gradient, grid and node field, used once */}
      <div className="nx-container-surface relative mb-5 overflow-hidden">
        <span className="nx-grad-rule absolute inset-x-0 top-0" aria-hidden="true" />
        <div className="nx-grid-field nx-grid-mask pointer-events-none absolute inset-0" aria-hidden="true" />
        <NodeField />
        <div className="relative flex flex-wrap items-center gap-6 px-6 py-7">
          <Assembling size={150} />
          <div className="min-w-0 flex-1">
            <p className="font-display text-label uppercase tracking-[0.13em] text-ink-muted">Deploying</p>
            <h2 className="mt-1 text-h1"><span className="nx-grad-text">survival-smp</span></h2>
            <p className="mt-1.5 max-w-[52ch] text-body-sm text-ink-secondary">
              Minecraft · Pro · Singapore. You can close this tab — we will email you when it is ready.
            </p>
          </div>
        </div>
      </div>

      <Alert tone="signal" title="Why there is no percentage here">
        The provisioning worker writes exactly six coarse step labels and no progress figure, no
        estimate and no status endpoint. So the component takes named stages and has no percentage
        prop to pass. It shows elapsed time and a typical range instead of a countdown it cannot honour.
      </Alert>

      <div className="mt-4 grid gap-4 lg:grid-cols-[minmax(0,1fr)_300px]">
        <DeploymentLadder
          rungs={rungs}
          elapsedLabel={`${mm}:${ss} elapsed`}
          typicalLabel="usually 1–3 min"
          overdue={at >= LADDER.length - 1}
          onCheckStatus={() => {}}
        />
        <Container className="flex flex-col gap-3 self-start px-5 py-5">
          <h3 className="text-h4 text-ink">Demonstration</h3>
          <p className="text-caption text-ink-muted">Step through the real backend states. Nothing is interpolated.</p>
          <div className="flex gap-2">
            <Button size="sm" variant="secondary" onClick={() => setAt((n) => Math.max(0, n - 1))}>Back</Button>
            <Button size="sm" variant="primary" onClick={() => setAt((n) => Math.min(LADDER.length, n + 1))}>Advance</Button>
          </div>
          <p className="border-t border-hairline pt-3 text-caption text-ink-secondary">
            Past the expected window the message changes and offers an action, rather than spinning
            silently. Advance to the last rung to see it.
          </p>
        </Container>
      </div>

      <SectionRule label="First value arrives as soon as it exists" />
      <div className="grid gap-3 sm:grid-cols-2">
        <DataPlate label="Connect address" value="play.example.nx:25565" />
        <DataPlate label="Console password" value="w8Rq-4Tz9-Lm2P" masked />
      </div>
    </>
  );
}

