            <ResourceMeter label="Bandwidth" used={3.8} total={4} unit="TB" format={(n) => n.toFixed(1)} />
          </Container>

          <SectionRule label="Attached" />
          <TopologyDiagram
            center="atlas-web"
            attached={[
              { label: "archive-vol", kind: "250 GB block storage", live: true },
              { label: "example.nx", kind: "domain · A record" },
              { label: "sgp-02", kind: "node · 12 ms" },
            ]}
          />
          <p className="mt-2 text-caption text-ink-muted">
            What a resource is attached to, drawn. A list of tabs cannot show a relationship.
          </p>
        </div>

        <aside className="flex flex-col gap-3">
          <Container className="px-5 py-4">
            <p className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">Access</p>
            <div className="mt-3 flex flex-col gap-3">
              <DataPlate label="Public address" value="198.51.100.24" />
              <DataPlate label="Shell" value="ssh root@198.51.100.24" />
            </div>
          </Container>
          <Container className="flex flex-col gap-3.5 px-5 py-4">
            <p className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">Settings</p>
            <Toggle checked={auto} onChange={setAuto} label="Auto-renew" description="Renews 1 October for $22.99." />
            <Toggle checked label="Daily backups" description="Seven restore points kept." />
          </Container>
          <div className="rounded-lg border border-danger-text/30 bg-surface px-5 py-4">
            <p className="font-display text-h4 text-ink">Destroy this server</p>
            <p className="mt-1 text-caption text-ink-secondary">
              Removes the disk, all snapshots and all backups. The address returns to the pool.
            </p>
            <Button variant="danger" size="sm" icon="trash" className="mt-3">Destroy</Button>
          </div>
        </aside>
      </div>
    </>
  );
}

/* ============================================================= INVENTORY */
const ROWS = [
  { n: "atlas-web",    k: "VPS",     s: "running" as const,      a: "198.51.100.24",         r: "Singapore", p: "Pro · 3 vCPU" },
  { n: "survival-smp", k: "Game",    s: "running" as const,      a: "play.example.nx:25565", r: "Singapore", p: "Minecraft · 8 GB" },
  { n: "kestrel-api",  k: "VPS",     s: "provisioning" as const, a: "assigning address",     r: "Frankfurt", p: "Standard · 2 vCPU" },
  { n: "studio-site",  k: "Hosting", s: "running" as const,      a: "studio.example.nx",     r: "Singapore", p: "Business" },
  { n: "archive-vol",  k: "Volume",  s: "stopped" as const,      a: "vol_8f2a1c",            r: "Singapore", p: "250 GB block" },
  { n: "legacy-mail",  k: "VPS",     s: "suspended" as const,    a: "198.51.100.71",         r: "Singapore", p: "Starter · 1 vCPU" },
];

export function Inventory() {
  return (
    <>
      <PageHeader
        eyebrow="Patterns"
        title="Resource inventory"
        description="One surface for everything the customer owns, filtered by kind. This replaces five sidebar rows over two backends and gives the four orphaned resource types a home."
        actions={<Button variant="brand" icon="deploy">Deploy</Button>}
      />
      <div className="flex flex-col gap-1.5">
        {ROWS.map((r) => (
          <ObjectSurface key={r.n} status={r.s} interactive className="px-4 py-3">
            <div className="flex flex-wrap items-center gap-x-5 gap-y-1.5 pl-2.5">
              <div className="min-w-44 flex-1">
                <div className="flex items-center gap-2.5">
                  <span className="font-display text-h4 text-ink">{r.n}</span>
                  <Badge size="sm">{r.k}</Badge>
                </div>
                <p className="mt-0.5 font-mono text-caption text-ink-muted">{r.a}</p>
              </div>
              <span className="hidden text-caption text-ink-secondary sm:block">{r.p}</span>
              <span className="hidden text-caption text-ink-muted md:block">{r.r}</span>
              <StatusIndicator status={r.s} size="sm" />
              <Button size="sm" variant="secondary">Manage</Button>
            </div>
          </ObjectSurface>
        ))}
      </div>
    </>
  );
}

/* ============================================================== TOPOLOGY */
export function TopologyView() {
  const [region, setRegion] = useState("sgp");
  return (
    <>
      <PageHeader
        eyebrow="Patterns"
        title="Topology"
        description="The Nxeon infrastructure visual language. Regions, networking and relationships are drawn as diagrams — never flags, stock maps or 3D server art."
      />

      <SectionRule label="Region selector" />
      <p className="mb-3 max-w-[68ch] text-body-sm text-ink-secondary">
        A region is a node on a network, not an option in a list. Selecting one lights it and traces
        the paths that reach it, so latency and peering are visible rather than described.
      </p>
      <RegionMap value={region} onChange={setRegion} />

      <SectionRule label="Resource relationships" />
      <TopologyDiagram
        center="atlas-web"
        attached={[
          { label: "archive-vol", kind: "250 GB block storage", live: true },
          { label: "example.nx", kind: "domain · A record" },
          { label: "sgp-02", kind: "node · 12 ms" },
        ]}
      />

      <SectionRule label="The rules" />
      <ul className="flex max-w-[68ch] list-disc flex-col gap-1.5 pl-5 text-body-sm text-ink-secondary">
        <li>Geometry is abstract and deliberate. It is never a literal world map.</li>
        <li>Every stroke is a token colour, so a theme change reaches the diagrams.</li>
        <li>Motion means traffic. A static path is an idle path.</li>
        <li>Nothing is filler — each drawing carries state the customer needs.</li>
      </ul>
    </>
  );
}

