"use client";

/* ============================================================================
   THE DESIGN SYSTEM SHOWCASE
   Lives inside the real shell, so navigating the documentation exercises the
   navigation being documented.
   ========================================================================= */

import { useState } from "react";
import { AppShell, type NavGroup, type BottomNavItem } from "@/components/shell/AppShell";
import { ToastProvider } from "@/components/system/overlays";
import { Colour, Typography, Surfaces, Icons, Motion } from "./foundations";
import { Buttons, Forms, NavigationView, DataView, Overlays, States } from "./componentsview";
import { Ladder, Checkout, Setup, Detail, Inventory, TopologyView } from "./patterns";
import { Regions, Loaders, GameServers } from "./showpieces";
import { PageHeader, SectionRule, Container } from "@/components/system/primitives";

const GROUPS: NavGroup[] = [
  { items: [{ id: "overview", label: "Overview", icon: "home" }] },
  {
    label: "Foundations",
    items: [
      { id: "colour", label: "Colour", icon: "region" },
      { id: "type", label: "Typography", icon: "files" },
      { id: "surfaces", label: "Surfaces", icon: "resources" },
      { id: "icons", label: "Iconography", icon: "deploy" },
      { id: "motion", label: "Motion", icon: "activity" },
    ],
  },
  {
    label: "Components",
    items: [
      { id: "buttons", label: "Buttons", icon: "play" },
      { id: "forms", label: "Forms", icon: "edit" },
      { id: "navigation", label: "Navigation", icon: "menu" },
      { id: "data", label: "Data display", icon: "storage" },
      { id: "overlays", label: "Overlays", icon: "console" },
      { id: "states", label: "States", icon: "info" },
    ],
  },
  {
    label: "Patterns",
    items: [
      { id: "regions", label: "Region selector", icon: "region" },
      { id: "games", label: "Game servers", icon: "game" },
      { id: "loaders", label: "Deploy loaders", icon: "deploy" },
      { id: "topology", label: "Topology", icon: "topology" },
      { id: "inventory", label: "Inventory", icon: "vps" },
      { id: "detail", label: "Resource detail", icon: "node" },
      { id: "checkout", label: "Two-stage checkout", icon: "billing" },
      { id: "ladder", label: "Deployment ladder", icon: "deploy" },
      { id: "setup", label: "Post-payment setup", icon: "check" },
    ],
  },
];

/* Four thumb-reachable destinations plus More. In the real portal these would
   be Home, Resources, Deploy and Account. */
const BOTTOM: BottomNavItem[] = [
  { id: "overview", label: "Home", icon: "home" },
  { id: "inventory", label: "Resources", icon: "vps" },
  { id: "regions", label: "Deploy", icon: "deploy" },
  { id: "detail", label: "Detail", icon: "node" },
];

function Overview({ go }: { go: (id: string) => void }) {
  return (
    <>
      <PageHeader
        eyebrow="Phase 2"
        title="Nxeon Design System"
        description="The foundation every later phase builds on: tokens, four surface archetypes, one icon family, one component library and the composed Nxeon patterns. Nothing here connects to a backend."
      />

      <SectionRule label="What this is" />
      <div className="grid gap-3 lg:grid-cols-3">
        {[
          { t: "Foundations", d: "Colour with one meaning per token, a type scale with a real display tier, four surface archetypes, one icon family and a motion language.", to: "colour" },
          { t: "Components", d: "Buttons, forms, navigation, data display, overlays and states — each with default, hover, active, focus, disabled, loading, error and success.", to: "buttons" },
          { t: "Patterns", d: "The composed signatures: the inventory, the resource detail hierarchy, two-stage checkout, the deployment ladder and post-payment setup.", to: "inventory" },
        ].map((c) => (
          <button key={c.t} type="button" onClick={() => go(c.to)}
            className="nx-container-surface nx-glow-soft nx-lift px-5 py-5 text-left">
            <h3 className="text-h3 text-ink">{c.t}</h3>
            <p className="mt-2 text-body-sm text-ink-secondary">{c.d}</p>
          </button>
        ))}
      </div>

      <SectionRule label="What it replaces" />
      <div className="grid grid-cols-2 gap-px overflow-hidden rounded-lg border border-hairline bg-hairline lg:grid-cols-4">
        {[
          ["21", "spellings of an inset panel, across ~145 places"],
          ["24", "modal implementations with zero focus traps"],
          ["60", "destructive actions confirmed by the browser dialog"],
          ["8", "tab-bar styles, two of which broke the Back button"],
          ["214", "hand-drawn icons at 18 stroke widths"],
          ["385", "hand-typed font sizes, and no display tier"],
          ["694", "uses of a text colour failing contrast on navy"],
          ["0", "toast systems, in a product with 19 bespoke ones"],
        ].map(([n, d]) => (
          <div key={d} className="bg-surface px-4 py-3.5">
            <span className="font-display text-metric tabular-nums text-signal-text">{n}</span>
            <span className="mt-1.5 block text-caption leading-snug text-ink-secondary">{d}</span>
          </div>
        ))}
      </div>

      <SectionRule label="Isolation" />
      <Container className="px-5 py-4">
        <p className="max-w-[68ch] text-body-sm text-ink-secondary">
          This sandbox has no environment file, no database client, no payment, registrar, mail or
          hypervisor library, and makes no network request. Its entire dependency list is Next, React
          and React DOM. Every figure on screen comes from one mock file, and every address shown is
          from a documentation-reserved range, so nothing here can be confused with live customer
          infrastructure.
        </p>
      </Container>
    </>
  );
}

export default function DesignSystemPage() {
  const [active, setActive] = useState("overview");

  const view = () => {
    switch (active) {
      case "colour": return <Colour />;
      case "type": return <Typography />;
      case "surfaces": return <Surfaces />;
      case "icons": return <Icons />;
      case "motion": return <Motion />;
      case "buttons": return <Buttons />;
      case "forms": return <Forms />;
      case "navigation": return <NavigationView />;
      case "data": return <DataView />;
      case "overlays": return <Overlays />;
      case "states": return <States />;
      case "regions": return <Regions />;
      case "games": return <GameServers />;
      case "loaders": return <Loaders />;
      case "topology": return <TopologyView />;
      case "inventory": return <Inventory />;
      case "detail": return <Detail />;
      case "checkout": return <Checkout />;
      case "ladder": return <Ladder />;
      case "setup": return <Setup />;
      default: return <Overview go={setActive} />;
    }
  };

  return (
    <ToastProvider>
      <AppShell groups={GROUPS} active={active} onNavigate={setActive} title="Nxeon" bottomNav={BOTTOM}>
        {view()}
      </AppShell>
    </ToastProvider>
  );
}

