1	"use client";
2	
3	/* ============================================================================
4	   THE GLOBE — the region selector's hero graphic
5	   A rotating dot-matrix Earth drawn on canvas: ~20,000 land cells from
6	   public-domain Natural Earth data, a lat/lon network grid, great-circle
7	   routes between Nxeon regions with travelling packets, a neon rim and a
8	   reflected plinth.
9	
10	   No 3D library. Land cells are projected once into unit vectors at mount and
11	   only rotated per frame, so the whole thing is a few milliseconds of maths.
12	   Honours prefers-reduced-motion by holding still rather than spinning.
13	   ========================================================================= */
14	
15	import { useEffect, useRef } from "react";
16	import { LAND_W, LAND_H, isLand } from "@/lib/land";
17	
18	export interface GlobeRegion {
19	  id: string;
20	  label: string;
21	  lat: number;
22	  lon: number;
23	  latencyMs: number;
24	  available?: boolean;
25	}
26	
27	export const GLOBE_REGIONS: GlobeRegion[] = [
28	  { id: "sgp", label: "Singapore",   lat: 1.35,  lon: 103.8, latencyMs: 12 },
29	  { id: "jpn", label: "Japan",       lat: 35.7,  lon: 139.7, latencyMs: 32 },
30	  { id: "aus", label: "Australia",   lat: -33.9, lon: 151.2, latencyMs: 42 },
31	  { id: "eur", label: "Europe",      lat: 50.1,  lon: 8.7,   latencyMs: 68 },
32	  { id: "usw", label: "US West",     lat: 37.4,  lon: -122.1, latencyMs: 48 },
33	  { id: "use", label: "US East",     lat: 40.7,  lon: -74.0, latencyMs: 52 },
34	  { id: "sam", label: "South America", lat: -23.5, lon: -46.6, latencyMs: 85 },
35	  { id: "mea", label: "Middle East", lat: 25.2,  lon: 55.3,  latencyMs: 78, available: false },
36	];
37	
38	const ROUTES: [string, string][] = [
39	  ["sgp", "jpn"], ["sgp", "aus"], ["sgp", "eur"], ["eur", "use"],
40	  ["use", "usw"], ["use", "sam"], ["eur", "mea"], ["sgp", "usw"],
41	];
42	
43	const toVec = (latDeg: number, lonDeg: number): [number, number, number] => {
44	  const la = (latDeg * Math.PI) / 180, lo = (lonDeg * Math.PI) / 180;
45	  return [Math.cos(la) * Math.sin(lo), Math.sin(la), Math.cos(la) * Math.cos(lo)];
46	};
47	
48	/** Reads a CSS custom property so the globe stays on the token system. */
49	function tokenRgb(el: HTMLElement, name: string): [number, number, number] {
50	  const v = getComputedStyle(el).getPropertyValue(name).trim();
51	  const m = v.match(/^#([0-9a-f]{6})$/i);
52	  if (m) {
53	    const n = parseInt(m[1], 16);
54	    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
55	  }
56	  return [110, 140, 255];
57	}
58	
59	export function Globe({
60	  regions = GLOBE_REGIONS,
61	  selected,
62	  onSelect,
63	  height = 460,
64	}: {
65	  regions?: GlobeRegion[];
66	  selected: string;
67	  onSelect?: (id: string) => void;
68	  height?: number;
69	}) {
70	  const canvasRef = useRef<HTMLCanvasElement>(null);
71	  const wrapRef = useRef<HTMLDivElement>(null);
72	  const selRef = useRef(selected);
73	  selRef.current = selected;
74	
75	  useEffect(() => {
76	    const canvas = canvasRef.current, wrap = wrapRef.current;
77	    if (!canvas || !wrap) return;
78	    const ctx = canvas.getContext("2d");
79	    if (!ctx) return;
80	
81	    /* ---- land cells -> unit vectors, once ---- */
82	    const pts: number[] = [];
83	    for (let iy = 0; iy < LAND_H; iy++) {
84	      // Thin the sampling toward the poles, where 1 degree of longitude is tiny.
85	      const lat = 90 - iy - 0.5;
86	      const step = Math.abs(lat) > 72 ? 3 : Math.abs(lat) > 55 ? 2 : 1;
87	      for (let ix = 0; ix < LAND_W; ix += step) {
88	        if (!isLand(ix, iy)) continue;
89	        const [x, y, z] = toVec(lat, ix - 180 + 0.5);
90	        pts.push(x, y, z);
91	      }
92	    }
93	    const land = new Float32Array(pts);
94	    const N = land.length / 3;
95	
96	    const A = tokenRgb(wrap, "--color-brand-a");
97	    const B = tokenRgb(wrap, "--color-brand-b");
98	    const C = tokenRgb(wrap, "--color-brand-c");
99	    const NEON = tokenRgb(wrap, "--color-neon-cyan");
100	
101	    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
102	
103	    let raf = 0, t = 0, dpr = 1, W = 0, H = 0, R = 0, cx = 0, cy = 0;
104	
105	    const resize = () => {
106	      dpr = Math.min(window.devicePixelRatio || 1, 2);
107	      W = wrap.clientWidth; H = height;
108	      canvas.width = W * dpr; canvas.height = H * dpr;
109	      canvas.style.width = `${W}px`; canvas.style.height = `${H}px`;
110	      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
111	      R = Math.min(W, H) * 0.36;
112	      cx = W / 2; cy = H * 0.46;
113	    };
114	    resize();
115	    const ro = new ResizeObserver(resize);
116	    ro.observe(wrap);
117	
118	    /* Blend the brand ramp left-to-right across the sphere. */
119	    const ramp = (u: number): [number, number, number] => {
120	      if (u < 0.5) {
121	        const k = u * 2;
122	        return [A[0] + (B[0] - A[0]) * k, A[1] + (B[1] - A[1]) * k, A[2] + (B[2] - A[2]) * k];
123	      }
124	      const k = (u - 0.5) * 2;
125	      return [B[0] + (C[0] - B[0]) * k, B[1] + (C[1] - B[1]) * k, B[2] + (C[2] - B[2]) * k];
126	    };
127	
128	    const draw = () => {
129	      ctx.clearRect(0, 0, W, H);
130	      const rot = reduce ? 0.6 : t * 0.00022;
131	      const cos = Math.cos(rot), sin = Math.sin(rot);
132	
133	      /* ---- atmosphere ---- */
134	      const atmo = ctx.createRadialGradient(cx, cy, R * 0.72, cx, cy, R * 1.5);
135	      atmo.addColorStop(0, `rgba(${B[0]},${B[1]},${B[2]},0.22)`);
136	      atmo.addColorStop(0.55, `rgba(${C[0]},${C[1]},${C[2]},0.10)`);
137	      atmo.addColorStop(1, "rgba(0,0,0,0)");
138	      ctx.fillStyle = atmo;
139	      ctx.beginPath(); ctx.arc(cx, cy, R * 1.5, 0, Math.PI * 2); ctx.fill();
140	
141	      /* ---- sphere body ---- */
142	      const body = ctx.createRadialGradient(cx - R * 0.3, cy - R * 0.35, R * 0.1, cx, cy, R);
143	      body.addColorStop(0, "rgba(19,27,43,0.95)");
144	      body.addColorStop(1, "rgba(5,8,15,0.98)");
145	      ctx.fillStyle = body;
146	      ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.fill();
147	
148	      /* ---- network grid: parallels and meridians ---- */
149	      ctx.lineWidth = 0.6;
150	      for (let latD = -60; latD <= 60; latD += 30) {
151	        ctx.beginPath();
152	        let started = false;
153	        for (let lonD = -180; lonD <= 180; lonD += 3) {
154	          const [x, y, z] = toVec(latD, lonD);
155	          const rx = x * cos + z * sin, rz = -x * sin + z * cos;
156	          if (rz <= 0) { started = false; continue; }
157	          const sx = cx + rx * R, sy = cy - y * R;
158	          if (!started) { ctx.moveTo(sx, sy); started = true; } else ctx.lineTo(sx, sy);
159	        }
160	        ctx.strokeStyle = `rgba(${B[0]},${B[1]},${B[2]},0.16)`;
161	        ctx.stroke();
162	      }
163	      for (let lonD = -180; lonD < 180; lonD += 30) {
164	        ctx.beginPath();
165	        let started = false;
166	        for (let latD = -90; latD <= 90; latD += 3) {
167	          const [x, y, z] = toVec(latD, lonD);
168	          const rx = x * cos + z * sin, rz = -x * sin + z * cos;
169	          if (rz <= 0) { started = false; continue; }
170	          const sx = cx + rx * R, sy = cy - y * R;
171	          if (!started) { ctx.moveTo(sx, sy); started = true; } else ctx.lineTo(sx, sy);
172	        }
173	        ctx.strokeStyle = `rgba(${B[0]},${B[1]},${B[2]},0.13)`;
174	        ctx.stroke();
175	      }
176	
177	      /* ---- land dots ---- */
178	      for (let i = 0; i < N; i++) {
179	        const x = land[i * 3], y = land[i * 3 + 1], z = land[i * 3 + 2];
180	        const rx = x * cos + z * sin, rz = -x * sin + z * cos;
181	        if (rz <= 0.02) continue;
182	        const sx = cx + rx * R, sy = cy - y * R;
183	        const u = (rx + 1) / 2;
184	        const [r, g, b] = ramp(u);
185	        const a = 0.25 + rz * 0.7;
186	        const s = rz > 0.75 ? 1.7 : 1.3;
187	        ctx.fillStyle = `rgba(${r | 0},${g | 0},${b | 0},${a})`;
188	        ctx.fillRect(sx, sy, s, s);
189	      }
190	
191	      /* ---- routes between regions ---- */
192	      const byId = (id: string) => regions.find((r) => r.id === id);
193	      ROUTES.forEach(([a, b], idx) => {
194	        const RA = byId(a), RB = byId(b);
195	        if (!RA || !RB) return;
196	        const va = toVec(RA.lat, RA.lon), vb = toVec(RB.lat, RB.lon);
197	        const hot = selRef.current === a || selRef.current === b;
198	
199	        const pathPts: [number, number, number][] = [];
200	        for (let s = 0; s <= 1.0001; s += 1 / 48) {
201	          // Slerp along the great circle, lifted off the surface at the midpoint.
202	          const d = Math.acos(Math.max(-1, Math.min(1, va[0] * vb[0] + va[1] * vb[1] + va[2] * vb[2])));
203	          const k = d < 1e-6 ? 1 : Math.sin(d);
204	          const w1 = Math.sin((1 - s) * d) / k, w2 = Math.sin(s * d) / k;
205	          const lift = 1 + 0.17 * Math.sin(Math.PI * s);
206	          pathPts.push([
207	            (va[0] * w1 + vb[0] * w2) * lift,
208	            (va[1] * w1 + vb[1] * w2) * lift,
209	            (va[2] * w1 + vb[2] * w2) * lift,
210	          ]);
211	        }
212	
213	        ctx.beginPath();
214	        let started = false;
215	        pathPts.forEach(([x, y, z]) => {
216	          const rx = x * cos + z * sin, rz = -x * sin + z * cos;
217	          if (rz <= 0) { started = false; return; }
218	          const sx = cx + rx * R, sy = cy - y * R;
219	          if (!started) { ctx.moveTo(sx, sy); started = true; } else ctx.lineTo(sx, sy);
220	        });
221	        ctx.lineWidth = hot ? 1.4 : 0.8;
222	        ctx.strokeStyle = hot
223	          ? `rgba(${NEON[0]},${NEON[1]},${NEON[2]},0.85)`
224	          : `rgba(${C[0]},${C[1]},${C[2]},0.28)`;
225	        ctx.stroke();
226	
227	        /* travelling packet */
228	        if (!reduce) {
229	          const prog = ((t * 0.00035 + idx * 0.13) % 1);
230	          const p = pathPts[Math.floor(prog * (pathPts.length - 1))];
231	          const rx = p[0] * cos + p[2] * sin, rz = -p[0] * sin + p[2] * cos;
232	          if (rz > 0) {
233	            const sx = cx + rx * R, sy = cy - p[1] * R;
234	            ctx.beginPath();
235	            ctx.arc(sx, sy, hot ? 2.6 : 1.8, 0, Math.PI * 2);
236	            ctx.fillStyle = hot
237	              ? `rgba(${NEON[0]},${NEON[1]},${NEON[2]},1)`
238	              : `rgba(${C[0]},${C[1]},${C[2]},0.75)`;
239	            ctx.shadowBlur = hot ? 12 : 6;
240	            ctx.shadowColor = hot ? `rgb(${NEON.join(",")})` : `rgb(${C.join(",")})`;
241	            ctx.fill();
242	            ctx.shadowBlur = 0;
243	          }
244	        }
245	      });
246	
247	      /* ---- region markers ---- */
248	      regions.forEach((r) => {
249	        const [x, y, z] = toVec(r.lat, r.lon);
250	        const rx = x * cos + z * sin, rz = -x * sin + z * cos;
251	        if (rz <= 0) return;
252	        const sx = cx + rx * R, sy = cy - y * R;
253	        const on = selRef.current === r.id;
254	        const dim = r.available === false;
255	
256	        if (on) {
257	          const pulse = reduce ? 0.5 : (Math.sin(t * 0.004) + 1) / 2;
258	          ctx.beginPath();
259	          ctx.arc(sx, sy, 8 + pulse * 7, 0, Math.PI * 2);
260	          ctx.strokeStyle = `rgba(${C[0]},${C[1]},${C[2]},${0.5 - pulse * 0.35})`;
261	          ctx.lineWidth = 1.2;
262	          ctx.stroke();
263	        }
264	        ctx.beginPath();
265	        ctx.arc(sx, sy, on ? 4.6 : 3, 0, Math.PI * 2);
266	        ctx.fillStyle = dim
267	          ? "rgba(140,155,180,0.6)"
268	          : on ? `rgb(${C.join(",")})` : `rgba(${NEON[0]},${NEON[1]},${NEON[2]},0.9)`;
269	        ctx.shadowBlur = on ? 16 : 7;
270	        ctx.shadowColor = dim ? "transparent" : on ? `rgb(${C.join(",")})` : `rgb(${NEON.join(",")})`;
271	        ctx.fill();
272	        ctx.shadowBlur = 0;
273	      });
274	
275	      /* ---- rim ---- */
276	      ctx.beginPath();
277	      ctx.arc(cx, cy, R, 0, Math.PI * 2);
278	      const rim = ctx.createLinearGradient(cx - R, cy, cx + R, cy);
279	      rim.addColorStop(0, `rgba(${NEON[0]},${NEON[1]},${NEON[2]},0.55)`);
280	      rim.addColorStop(0.5, `rgba(${B[0]},${B[1]},${B[2]},0.35)`);
281	      rim.addColorStop(1, `rgba(${C[0]},${C[1]},${C[2]},0.6)`);
282	      ctx.strokeStyle = rim; ctx.lineWidth = 1.1; ctx.stroke();
283	
284	      /* ---- plinth: reflected rings under the sphere ---- */
285	      const by = cy + R * 1.06;
286	      for (let i = 0; i < 3; i++) {
287	        const rr = R * (0.62 + i * 0.19);
288	        ctx.beginPath();
289	        ctx.ellipse(cx, by + i * 5, rr, rr * 0.17, 0, 0, Math.PI * 2);
290	        const g = ctx.createLinearGradient(cx - rr, 0, cx + rr, 0);
291	        g.addColorStop(0, `rgba(${NEON[0]},${NEON[1]},${NEON[2]},${0.34 - i * 0.1})`);
292	        g.addColorStop(1, `rgba(${C[0]},${C[1]},${C[2]},${0.34 - i * 0.1})`);
293	        ctx.strokeStyle = g; ctx.lineWidth = i === 0 ? 1.6 : 1; ctx.stroke();
294	      }
295	
296	      t += 16;
297	      raf = requestAnimationFrame(draw);
298	    };
299	
300	    raf = requestAnimationFrame(draw);
301	    return () => { cancelAnimationFrame(raf); ro.disconnect(); };
302	  }, [regions, height]);
303	
304	  return (
305	    <div ref={wrapRef} className="relative w-full" style={{ height }}>
306	      <canvas ref={canvasRef} className="block" aria-hidden="true" />
307	      {/* The accessible equivalent: the canvas is decorative, the list is real. */}
308	      <ul className="sr-only">
309	        {regions.map((r) => (
310	          <li key={r.id}>
311	            <button type="button" onClick={() => onSelect?.(r.id)} aria-pressed={r.id === selected}>
312	              {r.label}, {r.latencyMs} milliseconds{r.available === false ? ", at capacity" : ""}
313	            </button>
314	          </li>
315	        ))}
316	      </ul>
317	    </div>
318	  );
319	}
