"use client";

/* ============================================================================
   THE GLOBE — the region selector's hero graphic
   A rotating dot-matrix Earth drawn on canvas: ~20,000 land cells from
   public-domain Natural Earth data, a lat/lon network grid, great-circle
   routes between Nxeon regions with travelling packets, a neon rim and a
   reflected plinth.

   No 3D library. Land cells are projected once into unit vectors at mount and
   only rotated per frame, so the whole thing is a few milliseconds of maths.
   Honours prefers-reduced-motion by holding still rather than spinning.
   ========================================================================= */

import { useEffect, useRef } from "react";
import { LAND_W, LAND_H, isLand } from "@/lib/land";

export interface GlobeRegion {
  id: string;
  label: string;
  lat: number;
  lon: number;
  latencyMs: number;
  available?: boolean;
}

export const GLOBE_REGIONS: GlobeRegion[] = [
  { id: "sgp", label: "Singapore",   lat: 1.35,  lon: 103.8, latencyMs: 12 },
  { id: "jpn", label: "Japan",       lat: 35.7,  lon: 139.7, latencyMs: 32 },
  { id: "aus", label: "Australia",   lat: -33.9, lon: 151.2, latencyMs: 42 },
  { id: "eur", label: "Europe",      lat: 50.1,  lon: 8.7,   latencyMs: 68 },
  { id: "usw", label: "US West",     lat: 37.4,  lon: -122.1, latencyMs: 48 },
  { id: "use", label: "US East",     lat: 40.7,  lon: -74.0, latencyMs: 52 },
  { id: "sam", label: "South America", lat: -23.5, lon: -46.6, latencyMs: 85 },
  { id: "mea", label: "Middle East", lat: 25.2,  lon: 55.3,  latencyMs: 78, available: false },
];

const ROUTES: [string, string][] = [
  ["sgp", "jpn"], ["sgp", "aus"], ["sgp", "eur"], ["eur", "use"],
  ["use", "usw"], ["use", "sam"], ["eur", "mea"], ["sgp", "usw"],
];

const toVec = (latDeg: number, lonDeg: number): [number, number, number] => {
  const la = (latDeg * Math.PI) / 180, lo = (lonDeg * Math.PI) / 180;
  return [Math.cos(la) * Math.sin(lo), Math.sin(la), Math.cos(la) * Math.cos(lo)];
};

/** Reads a CSS custom property so the globe stays on the token system. */
function tokenRgb(el: HTMLElement, name: string): [number, number, number] {
  const v = getComputedStyle(el).getPropertyValue(name).trim();
  const m = v.match(/^#([0-9a-f]{6})$/i);
  if (m) {
    const n = parseInt(m[1], 16);
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  }
  return [110, 140, 255];
}

export function Globe({
  regions = GLOBE_REGIONS,
  selected,
  onSelect,
  height = 460,
}: {
  regions?: GlobeRegion[];
  selected: string;
  onSelect?: (id: string) => void;
  height?: number;
}) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const wrapRef = useRef<HTMLDivElement>(null);
  const selRef = useRef(selected);
  selRef.current = selected;

  useEffect(() => {
    const canvas = canvasRef.current, wrap = wrapRef.current;
    if (!canvas || !wrap) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    /* ---- land cells -> unit vectors, once ---- */
    const pts: number[] = [];
    for (let iy = 0; iy < LAND_H; iy++) {
      // Thin the sampling toward the poles, where 1 degree of longitude is tiny.
      const lat = 90 - iy - 0.5;
      const step = Math.abs(lat) > 72 ? 3 : Math.abs(lat) > 55 ? 2 : 1;
      for (let ix = 0; ix < LAND_W; ix += step) {
        if (!isLand(ix, iy)) continue;
        const [x, y, z] = toVec(lat, ix - 180 + 0.5);
        pts.push(x, y, z);
      }
    }
    const land = new Float32Array(pts);
    const N = land.length / 3;

    const A = tokenRgb(wrap, "--color-brand-a");
    const B = tokenRgb(wrap, "--color-brand-b");
    const C = tokenRgb(wrap, "--color-brand-c");
    const NEON = tokenRgb(wrap, "--color-neon-cyan");

    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let raf = 0, t = 0, dpr = 1, W = 0, H = 0, R = 0, cx = 0, cy = 0;

    const resize = () => {
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      W = wrap.clientWidth; H = height;
      canvas.width = W * dpr; canvas.height = H * dpr;
      canvas.style.width = `${W}px`; canvas.style.height = `${H}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      R = Math.min(W, H) * 0.36;
      cx = W / 2; cy = H * 0.46;
    };
    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(wrap);

    /* Blend the brand ramp left-to-right across the sphere. */
    const ramp = (u: number): [number, number, number] => {
      if (u < 0.5) {
        const k = u * 2;
        return [A[0] + (B[0] - A[0]) * k, A[1] + (B[1] - A[1]) * k, A[2] + (B[2] - A[2]) * k];
      }
      const k = (u - 0.5) * 2;
      return [B[0] + (C[0] - B[0]) * k, B[1] + (C[1] - B[1]) * k, B[2] + (C[2] - B[2]) * k];
    };

    const draw = () => {
      ctx.clearRect(0, 0, W, H);
      const rot = reduce ? 0.6 : t * 0.00022;
      const cos = Math.cos(rot), sin = Math.sin(rot);

      /* ---- atmosphere ---- */
      const atmo = ctx.createRadialGradient(cx, cy, R * 0.72, cx, cy, R * 1.5);
      atmo.addColorStop(0, `rgba(${B[0]},${B[1]},${B[2]},0.22)`);
      atmo.addColorStop(0.55, `rgba(${C[0]},${C[1]},${C[2]},0.10)`);
      atmo.addColorStop(1, "rgba(0,0,0,0)");
      ctx.fillStyle = atmo;
      ctx.beginPath(); ctx.arc(cx, cy, R * 1.5, 0, Math.PI * 2); ctx.fill();

      /* ---- sphere body ---- */
      const body = ctx.createRadialGradient(cx - R * 0.3, cy - R * 0.35, R * 0.1, cx, cy, R);
      body.addColorStop(0, "rgba(19,27,43,0.95)");
      body.addColorStop(1, "rgba(5,8,15,0.98)");
      ctx.fillStyle = body;
      ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.fill();

      /* ---- network grid: parallels and meridians ---- */
      ctx.lineWidth = 0.6;
      for (let latD = -60; latD <= 60; latD += 30) {
        ctx.beginPath();
        let started = false;
        for (let lonD = -180; lonD <= 180; lonD += 3) {
          const [x, y, z] = toVec(latD, lonD);
          const rx = x * cos + z * sin, rz = -x * sin + z * cos;
          if (rz <= 0) { started = false; continue; }
          const sx = cx + rx * R, sy = cy - y * R;
          if (!started) { ctx.moveTo(sx, sy); started = true; } else ctx.lineTo(sx, sy);
        }
        ctx.strokeStyle = `rgba(${B[0]},${B[1]},${B[2]},0.16)`;
        ctx.stroke();
      }
      for (let lonD = -180; lonD < 180; lonD += 30) {
        ctx.beginPath();
        let started = false;
        for (let latD = -90; latD <= 90; latD += 3) {
          const [x, y, z] = toVec(latD, lonD);
          const rx = x * cos + z * sin, rz = -x * sin + z * cos;
          if (rz <= 0) { started = false; continue; }
          const sx = cx + rx * R, sy = cy - y * R;
          if (!started) { ctx.moveTo(sx, sy); started = true; } else ctx.lineTo(sx, sy);
        }
        ctx.strokeStyle = `rgba(${B[0]},${B[1]},${B[2]},0.13)`;
        ctx.stroke();
      }

      /* ---- land dots ---- */
      for (let i = 0; i < N; i++) {
        const x = land[i * 3], y = land[i * 3 + 1], z = land[i * 3 + 2];
        const rx = x * cos + z * sin, rz = -x * sin + z * cos;
        if (rz <= 0.02) continue;
        const sx = cx + rx * R, sy = cy - y * R;
        const u = (rx + 1) / 2;
        const [r, g, b] = ramp(u);
        const a = 0.25 + rz * 0.7;
        const s = rz > 0.75 ? 1.7 : 1.3;
        ctx.fillStyle = `rgba(${r | 0},${g | 0},${b | 0},${a})`;
        ctx.fillRect(sx, sy, s, s);
      }

      /* ---- routes between regions ---- */
      const byId = (id: string) => regions.find((r) => r.id === id);
      ROUTES.forEach(([a, b], idx) => {
        const RA = byId(a), RB = byId(b);
        if (!RA || !RB) return;
        const va = toVec(RA.lat, RA.lon), vb = toVec(RB.lat, RB.lon);
        const hot = selRef.current === a || selRef.current === b;

        const pathPts: [number, number, number][] = [];
        for (let s = 0; s <= 1.0001; s += 1 / 48) {
          // Slerp along the great circle, lifted off the surface at the midpoint.
          const d = Math.acos(Math.max(-1, Math.min(1, va[0] * vb[0] + va[1] * vb[1] + va[2] * vb[2])));
          const k = d < 1e-6 ? 1 : Math.sin(d);
          const w1 = Math.sin((1 - s) * d) / k, w2 = Math.sin(s * d) / k;
          const lift = 1 + 0.17 * Math.sin(Math.PI * s);
          pathPts.push([
            (va[0] * w1 + vb[0] * w2) * lift,
            (va[1] * w1 + vb[1] * w2) * lift,
            (va[2] * w1 + vb[2] * w2) * lift,
          ]);
        }

        ctx.beginPath();
        let started = false;
        pathPts.forEach(([x, y, z]) => {
          const rx = x * cos + z * sin, rz = -x * sin + z * cos;
          if (rz <= 0) { started = false; return; }
          const sx = cx + rx * R, sy = cy - y * R;
          if (!started) { ctx.moveTo(sx, sy); started = true; } else ctx.lineTo(sx, sy);
        });
        ctx.lineWidth = hot ? 1.4 : 0.8;
        ctx.strokeStyle = hot
          ? `rgba(${NEON[0]},${NEON[1]},${NEON[2]},0.85)`
          : `rgba(${C[0]},${C[1]},${C[2]},0.28)`;
        ctx.stroke();

        /* travelling packet */
        if (!reduce) {
          const prog = ((t * 0.00035 + idx * 0.13) % 1);
          const p = pathPts[Math.floor(prog * (pathPts.length - 1))];
          const rx = p[0] * cos + p[2] * sin, rz = -p[0] * sin + p[2] * cos;
          if (rz > 0) {
            const sx = cx + rx * R, sy = cy - p[1] * R;
            ctx.beginPath();
            ctx.arc(sx, sy, hot ? 2.6 : 1.8, 0, Math.PI * 2);
            ctx.fillStyle = hot
              ? `rgba(${NEON[0]},${NEON[1]},${NEON[2]},1)`
              : `rgba(${C[0]},${C[1]},${C[2]},0.75)`;
            ctx.shadowBlur = hot ? 12 : 6;
            ctx.shadowColor = hot ? `rgb(${NEON.join(",")})` : `rgb(${C.join(",")})`;
            ctx.fill();
            ctx.shadowBlur = 0;
          }
        }
      });

      /* ---- region markers ---- */
      regions.forEach((r) => {
        const [x, y, z] = toVec(r.lat, r.lon);
        const rx = x * cos + z * sin, rz = -x * sin + z * cos;
        if (rz <= 0) return;
        const sx = cx + rx * R, sy = cy - y * R;
        const on = selRef.current === r.id;
        const dim = r.available === false;

        if (on) {
          const pulse = reduce ? 0.5 : (Math.sin(t * 0.004) + 1) / 2;
          ctx.beginPath();
          ctx.arc(sx, sy, 8 + pulse * 7, 0, Math.PI * 2);
          ctx.strokeStyle = `rgba(${C[0]},${C[1]},${C[2]},${0.5 - pulse * 0.35})`;
          ctx.lineWidth = 1.2;
          ctx.stroke();
        }
        ctx.beginPath();
        ctx.arc(sx, sy, on ? 4.6 : 3, 0, Math.PI * 2);
        ctx.fillStyle = dim
          ? "rgba(140,155,180,0.6)"
          : on ? `rgb(${C.join(",")})` : `rgba(${NEON[0]},${NEON[1]},${NEON[2]},0.9)`;
        ctx.shadowBlur = on ? 16 : 7;
        ctx.shadowColor = dim ? "transparent" : on ? `rgb(${C.join(",")})` : `rgb(${NEON.join(",")})`;
        ctx.fill();
        ctx.shadowBlur = 0;
      });

      /* ---- rim ---- */
      ctx.beginPath();
      ctx.arc(cx, cy, R, 0, Math.PI * 2);
      const rim = ctx.createLinearGradient(cx - R, cy, cx + R, cy);
      rim.addColorStop(0, `rgba(${NEON[0]},${NEON[1]},${NEON[2]},0.55)`);
      rim.addColorStop(0.5, `rgba(${B[0]},${B[1]},${B[2]},0.35)`);
      rim.addColorStop(1, `rgba(${C[0]},${C[1]},${C[2]},0.6)`);
      ctx.strokeStyle = rim; ctx.lineWidth = 1.1; ctx.stroke();

      /* ---- plinth: reflected rings under the sphere ---- */
      const by = cy + R * 1.06;
      for (let i = 0; i < 3; i++) {
        const rr = R * (0.62 + i * 0.19);
        ctx.beginPath();
        ctx.ellipse(cx, by + i * 5, rr, rr * 0.17, 0, 0, Math.PI * 2);
        const g = ctx.createLinearGradient(cx - rr, 0, cx + rr, 0);
        g.addColorStop(0, `rgba(${NEON[0]},${NEON[1]},${NEON[2]},${0.34 - i * 0.1})`);
        g.addColorStop(1, `rgba(${C[0]},${C[1]},${C[2]},${0.34 - i * 0.1})`);
        ctx.strokeStyle = g; ctx.lineWidth = i === 0 ? 1.6 : 1; ctx.stroke();
      }

      t += 16;
      raf = requestAnimationFrame(draw);
    };

    raf = requestAnimationFrame(draw);
    return () => { cancelAnimationFrame(raf); ro.disconnect(); };
  }, [regions, height]);

  return (
    <div ref={wrapRef} className="relative w-full" style={{ height }}>
      <canvas ref={canvasRef} className="block" aria-hidden="true" />
      {/* The accessible equivalent: the canvas is decorative, the list is real. */}
      <ul className="sr-only">
        {regions.map((r) => (
          <li key={r.id}>
            <button type="button" onClick={() => onSelect?.(r.id)} aria-pressed={r.id === selected}>
              {r.label}, {r.latencyMs} milliseconds{r.available === false ? ", at capacity" : ""}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

