"use client";

/* ============================================================================
   DEPLOYMENT LOADERS
   One per product, because "your server is being built" and "your domain is
   propagating" are not the same event and should not look the same.

   Each loader shows the shape of the work actually happening:
     vps      — a rack filling, then a boot scan
     game     — a world assembling block by block, then players connecting
     hosting  — a site rendering in, then the certificate landing
     domain   — records propagating outward to resolvers
     email    — mail routing in while the four DNS checks come up

   These are loops, not progress. Real progress is the DeploymentLadder, which
   is driven by backend states — a loader never implies completion it cannot
   know about. Reduced motion is honoured by the global rule.
   ========================================================================= */

import type { CSSProperties } from "react";

export type DeployProduct = "vps" | "game" | "hosting" | "domain" | "email";

const CYC = "3.6s";
const d = (i: number, n: number, cycle = CYC): CSSProperties => ({
  animationDelay: `${((i / n) * parseFloat(cycle) * 0.7).toFixed(2)}s`,
});

function Shell({ children, label }: { children: React.ReactNode; label: string }) {
  return (
    <div
      className="nx-glow-card relative flex aspect-[3/2] w-full items-center justify-center overflow-hidden rounded-lg border border-hairline bg-plate"
      role="img"
      aria-label={label}
    >
      <div className="nx-grid-field nx-grid-mask pointer-events-none absolute inset-0" aria-hidden="true" />
      <svg viewBox="0 0 240 160" className="relative w-full">{children}</svg>
    </div>
  );
}

const GRAD = (id: string) => (
  <defs>
    <linearGradient id={id} x1="0" y1="0" x2="1" y2="0">
      <stop offset="0%" stopColor="var(--color-brand-a)" />
      <stop offset="55%" stopColor="var(--color-brand-b)" />
      <stop offset="100%" stopColor="var(--color-brand-c)" />
    </linearGradient>
  </defs>
);

/* ------------------------------------------------------------------- VPS */
function Vps() {
  const slots = Array.from({ length: 7 });
  return (
    <Shell label="Building your server">
      {GRAD("g-vps")}
      {/* chassis */}
      <path d="M56,26 L184,26 L184,134 L44,134 L44,38 Z" fill="none" stroke="var(--color-hairline-strong)" />
      {slots.map((_, i) => (
        <g key={i}>
          <rect x={58} y={36 + i * 14} width={112} height={9} rx={1.5}
            fill="var(--color-hairline)" opacity={0.55} />
          <rect x={58} y={36 + i * 14} width={112} height={9} rx={1.5}
            fill="url(#g-vps)" opacity={0}
            style={{ animation: `nx-block-in ${CYC} ease-in-out infinite`, transformOrigin: "left center", ...d(i, slots.length) }} />
          <circle cx={176} cy={40.5 + i * 14} r={2} fill="var(--color-neon-cyan)" opacity={0}
            style={{ animation: `nx-tick-on ${CYC} ease-in-out infinite`, ...d(i, slots.length) }} />
        </g>
      ))}
      {/* boot scan */}
      <rect x={44} y={26} width={140} height={3} fill="var(--color-neon-cyan)" opacity={0.85}
        style={{ animation: `nx-scanline ${CYC} linear infinite`, filter: "drop-shadow(0 0 6px var(--color-neon-cyan))" }} />
    </Shell>
  );
}

/* ------------------------------------------------------------------ GAME */
function Game() {
  // An isometric world assembling, then two players connecting to it.
  const cubes = [
    [120, 96], [96, 82], [144, 82], [72, 68], [120, 68], [168, 68],
    [96, 54], [144, 54], [120, 40],
  ];
  return (
    <Shell label="Building your game server">
      {GRAD("g-game")}
      {cubes.map(([x, y], i) => (
        <g key={i} opacity={0}
          style={{ animation: `nx-block-in ${CYC} ease-in-out infinite`, transformOrigin: `${x}px ${y}px`, ...d(i, cubes.length) }}>
          <path d={`M${x},${y - 12} L${x + 22},${y} L${x},${y + 12} L${x - 22},${y} Z`}
            fill="url(#g-game)" fillOpacity="0.5" stroke="var(--color-brand-b)" strokeOpacity="0.7" />
          <path d={`M${x - 22},${y} L${x},${y + 12} L${x},${y + 24} L${x - 22},${y + 12} Z`}
            fill="var(--color-brand-a)" fillOpacity="0.28" />
          <path d={`M${x + 22},${y} L${x},${y + 12} L${x},${y + 24} L${x + 22},${y + 12} Z`}
            fill="var(--color-brand-c)" fillOpacity="0.22" />
        </g>
      ))}
      {[[26, 120], [214, 120]].map(([x, y], i) => (
        <g key={`p${i}`}>
          <path d={`M${x},${y} C${x + (i ? -50 : 50)},${y - 10} ${x + (i ? -60 : 60)},100 120,104`}
            fill="none" stroke="var(--color-neon-cyan)" strokeWidth="1.2" strokeDasharray="6 120"
            className="animate-nx-trace" style={{ animationDelay: `${1.4 + i * 0.5}s` }} />
          <circle cx={x} cy={y} r="4" fill="var(--color-neon-cyan)" opacity={0}
            style={{ animation: `nx-tick-on ${CYC} ease-in-out infinite`, animationDelay: `${1.4 + i * 0.5}s`,
              filter: "drop-shadow(0 0 5px var(--color-neon-cyan))" }} />
        </g>
      ))}
    </Shell>
  );
}

/* --------------------------------------------------------------- HOSTING */
function Hosting() {
  const rows = [
    { x: 62, w: 60, h: 7 }, { x: 62, w: 108, h: 5 }, { x: 62, w: 92, h: 5 },
    { x: 62, w: 46, h: 26 }, { x: 116, w: 62, h: 26 },
  ];
  return (
    <Shell label="Preparing your site">
      {GRAD("g-host")}
      <rect x={48} y={24} width={144} height={112} rx={4} fill="none" stroke="var(--color-hairline-strong)" />
      <path d="M48,40 H192" stroke="var(--color-hairline-strong)" />
      {[56, 64, 72].map((cxx) => <circle key={cxx} cx={cxx} cy={32} r="2.2" fill="var(--color-hairline-strong)" />)}
      {rows.map((r, i) => (
        <rect key={i} x={r.x} y={i < 3 ? 52 + i * 14 : 96} width={r.w} height={r.h} rx={1.5}
          fill="url(#g-host)" opacity={0}
          style={{ animation: `nx-block-in ${CYC} ease-in-out infinite`, transformOrigin: "left top", ...d(i, rows.length) }} />
      ))}
      {/* the certificate lands last */}
      <g opacity={0} style={{ animation: `nx-tick-on ${CYC} ease-in-out infinite`, animationDelay: "1.9s" }}>
        <rect x={162} y={28} width={22} height={9} rx={2} fill="var(--color-success)" fillOpacity="0.35"
          stroke="var(--color-success-text)" strokeOpacity="0.8" />
        <path d="M167,32.5 l2,2 l4,-4.5" stroke="var(--color-success-text)" strokeWidth="1.3"
          fill="none" strokeLinecap="round" strokeLinejoin="round" />
      </g>
    </Shell>
  );
}

/* ---------------------------------------------------------------- DOMAIN */
function Domain() {
  const resolvers = [[52, 44], [188, 44], [40, 108], [200, 108], [120, 26], [120, 140]];
  return (
    <Shell label="Propagating your domain">
      {GRAD("g-dom")}
      {[0, 1, 2].map((i) => (
        <circle key={i} cx={120} cy={82} r={54} fill="none"
          stroke="var(--color-brand-c)" strokeOpacity="0.5" strokeWidth="1"
          style={{ animation: `nx-ring-out ${CYC} ease-out infinite`, transformOrigin: "120px 82px", animationDelay: `${i * 1.2}s` }} />
      ))}
      {resolvers.map(([x, y], i) => (
        <g key={i}>
          <line x1={120} y1={82} x2={x} y2={y} stroke="var(--color-hairline-strong)" strokeWidth="0.8" />
          <circle cx={x} cy={y} r="3.4" fill="var(--color-neon-cyan)" opacity={0}
            style={{ animation: `nx-tick-on ${CYC} ease-in-out infinite`, ...d(i, resolvers.length),
              filter: "drop-shadow(0 0 5px var(--color-neon-cyan))" }} />
        </g>
      ))}
      <circle cx={120} cy={82} r="13" fill="url(#g-dom)" fillOpacity="0.9"
        style={{ filter: "drop-shadow(0 0 10px var(--color-brand-c))" }} />
      <text x={120} y={86} textAnchor="middle" fontSize="9" fontFamily="var(--font-mono)" fill="#fff">NS</text>
    </Shell>
  );
}

/* ----------------------------------------------------------------- EMAIL */
function Email() {
  const checks = ["MX", "SPF", "DKIM", "DMARC"];
  return (
    <Shell label="Setting up your mail">
      {GRAD("g-mail")}
      {/* mailbox */}
      <path d="M92,74 L148,74 L148,120 L92,120 Z" fill="none" stroke="var(--color-hairline-strong)" />
      <path d="M92,74 L120,94 L148,74" fill="none" stroke="url(#g-mail)" strokeWidth="1.4" />
      {/* envelopes dropping in */}
      {[0, 1, 2].map((i) => (
        <g key={i} opacity={0}
          style={{ animation: `nx-drop-in ${CYC} ease-in-out infinite`, animationDelay: `${i * 0.55}s` }}>
          <rect x={108 - i * 2} y={38} width={24} height={16} rx={2}
            fill="var(--color-brand-b)" fillOpacity="0.35" stroke="var(--color-brand-c)" strokeOpacity="0.75" />
          <path d={`M${108 - i * 2},38 L${120 - i * 2},48 L${132 - i * 2},38`}
            fill="none" stroke="var(--color-brand-c)" strokeWidth="1" />
        </g>
      ))}
      {/* the four checks coming up */}
      {checks.map((c, i) => (
        <g key={c} opacity={0}
          style={{ animation: `nx-tick-on ${CYC} ease-in-out infinite`, ...d(i, checks.length) }}>
          <rect x={22} y={44 + i * 20} width={52} height={14} rx={3}
            fill="var(--color-success)" fillOpacity="0.2" stroke="var(--color-success-text)" strokeOpacity="0.55" />
          <text x={34} y={54 + i * 20} fontSize="8" fontFamily="var(--font-mono)"
            fill="var(--color-success-text)">{c}</text>
          <path d={`M${63},${50 + i * 20} l1.8,1.8 l3.4,-3.6`} stroke="var(--color-success-text)"
            strokeWidth="1.2" fill="none" strokeLinecap="round" strokeLinejoin="round" />
        </g>
      ))}
      <line x1={168} y1={97} x2={200} y2={97} stroke="var(--color-neon-cyan)" strokeWidth="1.2"
        strokeDasharray="5 60" className="animate-nx-trace" />
    </Shell>
  );
}

const MAP: Record<DeployProduct, () => React.JSX.Element> = {
  vps: Vps, game: Game, hosting: Hosting, domain: Domain, email: Email,
};

export const DEPLOY_COPY: Record<DeployProduct, { title: string; sub: string }> = {
  vps:     { title: "Building your server",      sub: "Allocating resources and booting the operating system." },
  game:    { title: "Building your game server", sub: "Installing the game and opening the connect address." },
  hosting: { title: "Preparing your site",       sub: "Creating the account, then issuing your certificate." },
  domain:  { title: "Propagating your domain",   sub: "Publishing records to resolvers worldwide." },
  email:   { title: "Setting up your mail",      sub: "Routing mail and verifying the four DNS records." },
};

export function DeployLoader({ product }: { product: DeployProduct }) {
  const C = MAP[product];
  return <C />;
}

