"use client";

/* ============================================================================
   TOPOLOGY — the Nxeon infrastructure visual language
   The blueprint promised "topology, not clip art": regions, networking and
   infrastructure are drawn as vector diagrams, never flags, stock maps or
   3D server art. This file is that vocabulary.

   Rules:
     - geometry is abstract and deliberate, never a literal world map
     - every stroke is a token colour, so a theme reaches the diagrams
     - motion means traffic; a static path is an idle path
     - nothing here is decorative filler: each drawing carries real state
   ========================================================================= */

import { useId } from "react";

export interface RegionNode {
  id: string;
  label: string;
  /** Percentage coordinates within the diagram, so layout is resolution-free. */
  x: number;
  y: number;
  latencyMs?: number;
  available?: boolean;
}

export const NXEON_REGIONS: RegionNode[] = [
  { id: "sgp", label: "Singapore",   x: 84, y: 55, latencyMs: 12,  available: true },
  { id: "fra", label: "Frankfurt",   x: 57, y: 24, latencyMs: 168, available: true },
  { id: "nyc", label: "New York",    x: 32, y: 46, latencyMs: 214, available: true },
  { id: "lax", label: "Los Angeles", x: 12, y: 76, latencyMs: 182, available: false },
];

/* Which regions are peered. Drawn as the network fabric. */
const LINKS: [string, string][] = [
  ["lax", "nyc"], ["nyc", "fra"], ["fra", "sgp"], ["lax", "sgp"], ["nyc", "sgp"],
];

/**
 * The region selector, drawn as a network rather than listed as options.
 * Selecting a region lights its node and traces the paths that reach it.
 */
export function RegionMap({
  regions = NXEON_REGIONS,
  value,
  onChange,
  height = 260,
}: {
  regions?: RegionNode[];
  value: string;
  onChange?: (id: string) => void;
  height?: number;
}) {
  const uid = useId().replace(/:/g, "");
  const W = 600, H = height;
  const px = (n: number) => (n / 100) * W;
  const py = (n: number) => (n / 100) * H;
  const at = (id: string) => regions.find((r) => r.id === id);

  return (
    <div className="nx-container-surface relative overflow-hidden">
      <div className="nx-grid-field nx-grid-mask pointer-events-none absolute inset-0" aria-hidden="true" />

      <svg
        viewBox={`0 0 ${W} ${H}`}
        className="relative w-full"
        role="group"
        aria-label="Nxeon regions"
      >
        <defs>
          <linearGradient id={`${uid}-link`} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stopColor="var(--color-brand-a)" stopOpacity="0.55" />
            <stop offset="55%" stopColor="var(--color-brand-b)" stopOpacity="0.5" />
            <stop offset="100%" stopColor="var(--color-brand-c)" stopOpacity="0.45" />
          </linearGradient>
          <radialGradient id={`${uid}-halo`}>
            <stop offset="0%" stopColor="var(--color-brand-c)" stopOpacity="0.5" />
            <stop offset="100%" stopColor="var(--color-brand-c)" stopOpacity="0" />
          </radialGradient>
        </defs>

        {/* Fabric */}
        <g>
          {LINKS.map(([a, b]) => {
            const A = at(a), B = at(b);
            if (!A || !B) return null;
            const hot = value === a || value === b;
            const x1 = px(A.x), y1 = py(A.y), x2 = px(B.x), y2 = py(B.y);
            const mx = (x1 + x2) / 2, my = (y1 + y2) / 2 - Math.abs(x2 - x1) * 0.12;
            const d = `M${x1},${y1} Q${mx},${my} ${x2},${y2}`;
            return (
              <g key={`${a}-${b}`}>
                <path
                  d={d}
                  fill="none"
                  stroke={hot ? `url(#${uid}-link)` : "var(--color-hairline-strong)"}
                  strokeWidth={hot ? 1.5 : 1}
                  strokeLinecap="round"
                />
                {hot && (
                  <path
                    d={d}
                    fill="none"
                    stroke="var(--color-neon-cyan)"
                    strokeWidth={2}
                    strokeLinecap="round"
                    strokeDasharray="18 202"
                    className="animate-nx-trace"
                    style={{ filter: "drop-shadow(0 0 4px var(--color-neon-cyan))" }}
                  />
                )}
              </g>
            );
          })}
        </g>

        {/* Nodes */}
        {regions.map((r) => {
          const on = r.id === value;
          const cx = px(r.x), cy = py(r.y);
          return (
            <g
              key={r.id}
              transform={`translate(${cx},${cy})`}
              className={r.available === false ? "opacity-45" : "cursor-pointer"}
              onClick={() => r.available !== false && onChange?.(r.id)}
              role="button"
              aria-label={`${r.label}${r.latencyMs ? `, ${r.latencyMs} milliseconds` : ""}${r.available === false ? ", unavailable" : ""}`}
              aria-pressed={on}
              tabIndex={r.available === false ? -1 : 0}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onChange?.(r.id); }
              }}
            >
              {on && <circle r={34} fill={`url(#${uid}-halo)`} />}
              {on && (
                <circle
                  r={13}
                  fill="none"
                  stroke="var(--color-brand-c)"
                  strokeOpacity="0.55"
                  strokeWidth={1}
                />
              )}
              <circle
                r={on ? 5.5 : 3.5}
                fill={on ? "var(--color-brand-c)" : "var(--color-data-2)"}
                className={on ? "" : "animate-nx-node"}
                style={on ? { filter: "drop-shadow(0 0 6px var(--color-brand-c))" } : undefined}
              />
              <text
                y={-20}
                textAnchor={r.x < 20 ? "start" : r.x > 80 ? "end" : "middle"}
                x={r.x < 20 ? -6 : r.x > 80 ? 6 : 0}
                fontSize="12.5"
                fontFamily="var(--font-display)"
                fontWeight="600"
                fill={on ? "var(--color-ink)" : "var(--color-ink-secondary)"}
              >
                {r.label}
              </text>
              <text
                y={24}
                textAnchor={r.x < 20 ? "start" : r.x > 80 ? "end" : "middle"}
                x={r.x < 20 ? -6 : r.x > 80 ? 6 : 0}
                fontSize="11"
                fontFamily="var(--font-mono)"
                fill={r.available === false ? "var(--color-warning-text)" : "var(--color-ink-muted)"}
              >
                {r.available === false ? "at capacity" : `${r.latencyMs} ms`}
              </text>
            </g>
          );
        })}
      </svg>
    </div>
  );
}

/**
 * A resource's relationships, drawn. Used on a detail page to show what a
 * server is actually attached to — the thing a list of tabs cannot show.
 */
export function TopologyDiagram({
  center, attached,
}: { center: string; attached: { label: string; kind: string; live?: boolean }[] }) {
  const uid = useId().replace(/:/g, "");
  const W = 600, H = 200, cx = 150, cy = H / 2;

  return (
    <div className="nx-container-surface relative overflow-hidden">
      <div className="nx-grid-field nx-grid-mask pointer-events-none absolute inset-0" aria-hidden="true" />
      <svg viewBox={`0 0 ${W} ${H}`} className="relative w-full" role="img"
        aria-label={`${center} is attached to ${attached.map((a) => a.label).join(", ")}`}>
        <defs>
          <linearGradient id={`${uid}-edge`} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stopColor="var(--color-brand-b)" stopOpacity="0.6" />
            <stop offset="100%" stopColor="var(--color-brand-c)" stopOpacity="0.35" />
          </linearGradient>
        </defs>

        {attached.map((a, i) => {
          const y = 40 + (i * (H - 80)) / Math.max(1, attached.length - 1);
          const tx = 430;
          const d = `M${cx + 46},${cy} C${cx + 150},${cy} ${tx - 130},${y} ${tx - 8},${y}`;
          return (
            <g key={a.label}>
              <path d={d} fill="none" stroke={`url(#${uid}-edge)`} strokeWidth={1.25} />
              {a.live && (
                <path d={d} fill="none" stroke="var(--color-neon-cyan)" strokeWidth={1.75}
                  strokeDasharray="14 206" className="animate-nx-trace"
                  style={{ filter: "drop-shadow(0 0 3px var(--color-neon-cyan))" }} />
              )}
              <g transform={`translate(${tx},${y})`}>
                <rect x={0} y={-15} width={150} height={30} rx={4}
                  fill="var(--color-raised)" stroke="var(--color-hairline-strong)" />
                <text x={12} y={-2} fontSize="12" fontFamily="var(--font-display)" fontWeight="600"
                  fill="var(--color-ink)">{a.label}</text>
                <text x={12} y={10} fontSize="10" fontFamily="var(--font-mono)"
                  fill="var(--color-ink-muted)">{a.kind}</text>
              </g>
            </g>
          );
        })}

        {/* The subject, drawn with the object notch so it matches the surfaces */}
        <g transform={`translate(${cx},${cy})`}>
          <path
            d="M-34,-30 L46,-30 L46,30 L-46,30 L-46,-18 Z"
            fill="var(--color-raised)"
            stroke="var(--color-brand-b)"
            strokeOpacity="0.55"
          />
          <text textAnchor="middle" y={-4} fontSize="13" fontFamily="var(--font-display)"
            fontWeight="700" fill="var(--color-ink)">{center}</text>
          <text textAnchor="middle" y={12} fontSize="10" fontFamily="var(--font-mono)"
            fill="var(--color-ink-muted)">this resource</text>
        </g>
      </svg>
    </div>
  );
}

/** A quiet node field. The one approved backdrop for brand moments.
    Drawn in a wide viewBox so the dots stay small when the field is stretched
    across a hero — a square viewBox scaled to a banner turns them into blobs. */
export function NodeField({ className = "" }: { className?: string }) {
  const pts: [number, number][] = [
    [48, 88], [132, 232], [222, 72], [306, 184], [396, 104], [468, 248],
    [546, 136], [90, 312], [264, 328], [432, 352], [528, 288], [180, 152],
  ];
  return (
    <svg viewBox="0 0 600 400" preserveAspectRatio="none"
      className={`pointer-events-none absolute inset-0 h-full w-full ${className}`} aria-hidden="true">
      {pts.map(([x, y], i) => {
        const n = pts[(i + 3) % pts.length];
        return <line key={`l${i}`} x1={x} y1={y} x2={n[0]} y2={n[1]}
          stroke="var(--color-brand-b)" strokeOpacity="0.13" strokeWidth="0.9" />;
      })}
      {pts.map(([x, y], i) => (
        <circle key={`c${i}`} cx={x} cy={y} r="1.6"
          fill="var(--color-brand-c)" fillOpacity="0.45" />
      ))}
    </svg>
  );
}

