"use client";

/* ============================================================================
   SURFACES, RULES, PLATES, STATUS
   The four archetypes plus the signature devices built on them.
   ========================================================================= */

import { useCallback, useState, type ReactNode, type HTMLAttributes } from "react";
import { Icon, type IconName } from "./Icon";

export type Tone = "neutral" | "signal" | "success" | "warning" | "danger" | "ai";

/* One status table for the whole product. The old portal had this map
   redefined privately in 20 files, which is why a "running" server was a
   different green depending on which page you were looking at. */
export const STATUS_TONE: Record<string, { tone: Tone; label: string; live?: boolean }> = {
  running:      { tone: "success", label: "Running" },
  active:       { tone: "success", label: "Active" },
  ready:        { tone: "success", label: "Ready" },
  healthy:      { tone: "success", label: "Healthy" },
  provisioning: { tone: "signal",  label: "Provisioning", live: true },
  pending:      { tone: "signal",  label: "Pending", live: true },
  reinstalling: { tone: "signal",  label: "Reinstalling", live: true },
  deleting:     { tone: "danger",  label: "Deleting", live: true },
  stopped:      { tone: "neutral", label: "Stopped" },
  suspended:    { tone: "warning", label: "Suspended" },
  expiring:     { tone: "warning", label: "Expiring" },
  degraded:     { tone: "warning", label: "Degraded" },
  error:        { tone: "danger",  label: "Error" },
  failed:       { tone: "danger",  label: "Failed" },
};

export const TONE_TEXT: Record<Tone, string> = {
  neutral: "text-ink-muted",
  signal:  "text-signal-text",
  success: "text-success-text",
  warning: "text-warning-text",
  danger:  "text-danger-text",
  ai:      "text-ai-text",
};

const TONE_CHIP: Record<Tone, string> = {
  neutral: "border-hairline-strong text-ink-secondary",
  signal:  "border-signal-edge/45 text-signal-text",
  success: "border-success-text/40 text-success-text",
  warning: "border-warning-text/40 text-warning-text",
  danger:  "border-danger-text/40 text-danger-text",
  ai:      "border-ai-text/40 text-ai-text",
};

/* ---------------------------------------------------------------- OBJECT */
interface ObjectSurfaceProps extends HTMLAttributes<HTMLDivElement> {
  status?: keyof typeof STATUS_TONE;
  interactive?: boolean;
  children: ReactNode;
}
/** A thing the customer owns. The notch and the filament belong to this and
    to nothing else, so both read as "yours" without a label. */
export function ObjectSurface({
  status, interactive, className = "", children, ...rest
}: ObjectSurfaceProps) {
  const s = status ? STATUS_TONE[status] : undefined;
  return (
    <div
      className={`nx-object ${interactive ? "nx-object-interactive" : ""} ${className}`}
      {...rest}
    >
      {s && (
        <span
          className={`nx-filament ${TONE_TEXT[s.tone]}`}
          data-live={s.live ? "true" : "false"}
          aria-hidden="true"
        />
      )}
      {children}
    </div>
  );
}

/* ------------------------------------------------------------- CONTAINER */
/** Groups information. Deliberately plainer than an object — this is what
    stops every paragraph in the portal from becoming a bordered rectangle. */
export function Container({ className = "", children, ...rest }: HTMLAttributes<HTMLDivElement>) {
  return (
    <div className={`nx-container-surface ${className}`} {...rest}>{children}</div>
  );
}

/* ----------------------------------------------------------------- RULE */
export function SectionRule({ label, action }: { label: string; action?: ReactNode }) {
  return (
    <div className="nx-rule mb-3 mt-6 first:mt-0">
      <span className="nx-rule-label">{label}</span>
      {action && <div className="order-last shrink-0 pl-3">{action}</div>}
    </div>
  );
}

/* ---------------------------------------------------------------- PLATE */
interface DataPlateProps {
  label?: string;
  value: string;
  /** Renders a copy affordance. Technical values almost always want one. */
  copyable?: boolean;
  masked?: boolean;
  className?: string;
}
/** Every technical value in the product renders here: addresses, commands,
    identifiers, node names, ports, DNS values, hashes. One treatment, so
    infrastructure data looks like infrastructure data. */
export function DataPlate({ label, value, copyable = true, masked = false, className = "" }: DataPlateProps) {
  const [revealed, setRevealed] = useState(!masked);
  const shown = revealed ? value : "•".repeat(Math.min(value.length, 18));
  return (
    <div className={className}>
      {label && (
        <div className="mb-1.5 font-display text-label uppercase tracking-[0.11em] text-ink-muted">
          {label}
        </div>
      )}
      <div className="nx-plate flex items-center gap-2 px-3 py-2">
        <code className="min-w-0 flex-1 overflow-x-auto whitespace-nowrap text-ink">{shown}</code>
        {masked && (
          <button
            type="button"
            onClick={() => setRevealed((v) => !v)}
            className="shrink-0 rounded-sm px-1.5 py-0.5 font-display text-label uppercase tracking-[0.11em] text-ink-muted transition-colors duration-[var(--nx-dur-1)] hover:text-ink"
          >
            {revealed ? "Hide" : "Show"}
          </button>
        )}
        {copyable && <CopyButton value={value} />}
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------- COPY */
/** One copy interaction for the product. The old portal had thirteen, each
    with its own confirmation behaviour. */
export function CopyButton({ value, label = "Copy" }: { value: string; label?: string }) {
  const [done, setDone] = useState(false);
  const copy = useCallback(() => {
    void navigator.clipboard?.writeText(value).then(() => {
      setDone(true);
      window.setTimeout(() => setDone(false), 1600);
    });
  }, [value]);
  return (
    <button
      type="button"
      onClick={copy}
      className={`shrink-0 rounded-sm p-1 transition-colors duration-[var(--nx-dur-1)] ${
        done ? "text-success-text" : "text-ink-muted hover:text-ink"
      }`}
      aria-label={done ? "Copied" : label}
    >
      <Icon name={done ? "check" : "copy"} size="sm" />
    </button>
  );
}

/* --------------------------------------------------------------- BADGE */
export function Badge({
  children, tone = "neutral", size = "md", icon,
}: { children: ReactNode; tone?: Tone; size?: "sm" | "md"; icon?: IconName }) {
  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-sm border bg-transparent font-display font-semibold uppercase tracking-[0.09em] ${TONE_CHIP[tone]} ${
        size === "sm" ? "px-1.5 py-0.5 text-[0.6875rem]" : "px-2 py-1 text-label"
      }`}
    >
      {icon && <Icon name={icon} size="sm" />}
      {children}
    </span>
  );
}

/* ------------------------------------------------------ STATUS INDICATOR */
/** State is encoded in form as well as colour: a live state animates, a
    steady state does not, so the difference survives a greyscale screenshot. */
export function StatusIndicator({
  status, showLabel = true, size = "md",
}: { status: keyof typeof STATUS_TONE; showLabel?: boolean; size?: "sm" | "md" }) {
  const s = STATUS_TONE[status] ?? { tone: "neutral" as Tone, label: status };
  const dot = size === "sm" ? "h-1.5 w-1.5" : "h-2 w-2";
  return (
    <span className={`inline-flex items-center gap-2 ${TONE_TEXT[s.tone]}`}>
      <span className={`relative ${dot} shrink-0`}>
        <span className={`absolute inset-0 rounded-full bg-current ${s.live ? "animate-nx-pulse" : ""}`} />
        {s.live && <span className="absolute -inset-1 rounded-full border border-current opacity-40" />}
      </span>
      {showLabel && (
        <span className={`font-display font-semibold ${size === "sm" ? "text-[0.75rem]" : "text-body-sm"}`}>
          {s.label}
        </span>
      )}
    </span>
  );
}

/* --------------------------------------------------------- PAGE HEADER */
interface PageHeaderProps {
  eyebrow?: string;
  title: string;
  description?: string;
  status?: keyof typeof STATUS_TONE;
  meta?: ReactNode;
  actions?: ReactNode;
}
/** The single page-header contract. In the old portal 60 of 64 routes
    bypassed the shared header and six different heading recipes coexisted. */
export function PageHeader({ eyebrow, title, description, status, meta, actions }: PageHeaderProps) {
  return (
    <header className="mb-5 border-b border-hairline pb-4">
      {eyebrow && (
        <div className="mb-2 font-display text-label uppercase tracking-[0.13em] text-signal-text">
          {eyebrow}
        </div>
      )}
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="min-w-0">
          <div className="flex flex-wrap items-center gap-3">
            <h1 className="text-h1 text-ink">{title}</h1>
            {status && <StatusIndicator status={status} />}
          </div>
          {description && (
            <p className="mt-2 max-w-[68ch] text-body text-ink-secondary">{description}</p>
          )}
          {meta && <div className="mt-3 flex flex-wrap items-center gap-x-5 gap-y-2">{meta}</div>}
        </div>
        {actions && <div className="flex shrink-0 flex-wrap items-center gap-2">{actions}</div>}
      </div>
    </header>
  );
}

/** A compact label/value pair for header metadata. */
export function MetaItem({ label, value, mono }: { label: string; value: ReactNode; mono?: boolean }) {
  return (
    <div className="flex items-baseline gap-2">
      <span className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">{label}</span>
      <span className={`text-body-sm text-ink-secondary ${mono ? "font-mono" : ""}`}>{value}</span>
    </div>
  );
}

