55	
56	export function Button({
57	  variant = "secondary", size = "md", loading, icon, iconRight, block,
58	  className = "", children, disabled, ...rest
59	}: ButtonProps) {
60	  return (
61	    <button
62	      className={`inline-flex items-center justify-center rounded-md font-display font-semibold
63	        transition-[background-color,border-color,color] duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
