84	/** Icon-only control. The label is required, not optional — that is how the
85	    nine unnamed icon buttons in the old portal stop being possible. */
86	export function IconButton({
87	  name, label, variant = "ghost", size = "md", className = "", ...rest
88	}: { name: IconName; label: string; variant?: Variant; size?: Size } & ButtonHTMLAttributes<HTMLButtonElement>) {
89	  const box = size === "sm" ? "h-8 w-8" : size === "lg" ? "h-12 w-12" : "h-10 w-10";
