106	  label: string;
107	  hint?: string;
108	  error?: string;
109	  success?: string;
110	  required?: boolean;
111	  children: (props: { id: string; describedBy?: string; invalid: boolean }) => ReactNode;
112	}
113	/** One label, hint, error and success structure for every form in the
114	    product. 61% of labels in the old portal had no programmatic association;
115	    here association is produced by the wrapper, not by discipline. */
116	export function Field({ label, hint, error, success, required, children }: FieldProps) {
117	  const id = useId();
118	  const hintId = `${id}-hint`;
119	  const msgId = `${id}-msg`;
120	  const describedBy = [hint ? hintId : null, error || success ? msgId : null]
121	    .filter(Boolean).join(" ") || undefined;
122	
123	  return (
124	    <div className="flex flex-col gap-1.5">
125	      <label htmlFor={id} className="font-display text-label uppercase tracking-[0.11em] text-ink-secondary">
