127	        {required && <span className="ml-1 text-danger-text" aria-hidden="true">*</span>}
128	      </label>
129	      {hint && <p id={hintId} className="text-caption text-ink-muted">{hint}</p>}
130	      {children({ id, describedBy, invalid: Boolean(error) })}
131	      {(error || success) && (
132	        <p
133	          id={msgId}
134	          role={error ? "alert" : "status"}
135	          className={`flex items-start gap-1.5 text-caption ${error ? "text-danger-text" : "text-success-text"}`}
136	        >
137	          <Icon name={error ? "alert" : "check"} size="sm" className="mt-0.5" />
138	          <span>{error || success}</span>
139	        </p>
140	      )}
141	    </div>
142	  );
143	}
144	
145	const CONTROL_BASE =
146	  "w-full rounded-md border bg-plate px-3 text-body text-ink placeholder:text-ink-muted " +
147	  "transition-[border-color,background-color] duration-[var(--nx-dur-1)] " +
148	  "hover:border-hairline-strong disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:border-hairline";
