151	export function Input({
152	  invalid, mono, className = "", ...rest
153	}: { invalid?: boolean; mono?: boolean } & InputHTMLAttributes<HTMLInputElement>) {
154	  return (
155	    <input
156	      aria-invalid={invalid || undefined}
157	      className={`${CONTROL_BASE} h-10 ${invalid ? "border-danger-text/60" : "border-hairline"} ${mono ? "font-mono text-code" : ""} ${className}`}
158	      {...rest}
159	    />
160	  );
161	}
162	
163	/* ------------------------------------------------------------- SELECT */
164	export function Select({
165	  invalid, className = "", children, ...rest
166	}: { invalid?: boolean } & SelectHTMLAttributes<HTMLSelectElement>) {
167	  return (
168	    <div className="relative">
169	      <select
170	        aria-invalid={invalid || undefined}
171	        className={`${CONTROL_BASE} h-10 appearance-none pr-9 ${invalid ? "border-danger-text/60" : "border-hairline"} ${className}`}
172	        {...rest}
173	      >
174	        {children}
175	      </select>
176	      <Icon name="chevronDown" size="md"
177	        className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-ink-muted" />
178	    </div>
179	  );
180	}
181	
182	/* ----------------------------------------------------------- TEXTAREA */
183	export function Textarea({
184	  invalid, className = "", ...rest
185	}: { invalid?: boolean } & InputHTMLAttributes<HTMLTextAreaElement>) {
186	  return (
187	    <textarea
188	      aria-invalid={invalid || undefined}
189	      className={`${CONTROL_BASE} min-h-24 resize-y py-2.5 ${invalid ? "border-danger-text/60" : "border-hairline"} ${className}`}
190	      {...(rest as object)}
191	    />
192	  );
193	}
194	
195	/* ----------------------------------------------------------- COMBOBOX */
196	export interface ComboOption { value: string; label: string; hint?: string; icon?: IconName }
197	/** Filterable single-select with full keyboard support. */
198	export function Combobox({
199	  options, value, onChange, placeholder = "Search…", id, describedBy,
200	}: {
201	  options: ComboOption[]; value?: string; onChange?: (v: string) => void;
202	  placeholder?: string; id?: string; describedBy?: string;
203	}) {
204	  const [open, setOpen] = useState(false);
205	  const [query, setQuery] = useState("");
206	  const [active, setActive] = useState(0);
207	  const wrapRef = useRef<HTMLDivElement>(null);
208	  const listId = useId();
209	
210	  const selected = options.find((o) => o.value === value);
211	  const filtered = query
212	    ? options.filter((o) => o.label.toLowerCase().includes(query.toLowerCase()))
213	    : options;
214	
215	  useEffect(() => {
216	    if (!open) return;
217	    const onDoc = (e: MouseEvent) => {
218	      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) setOpen(false);
219	    };
220	    document.addEventListener("mousedown", onDoc);
221	    return () => document.removeEventListener("mousedown", onDoc);
222	  }, [open]);
223	
224	  const commit = (v: string) => { onChange?.(v); setOpen(false); setQuery(""); };
225	
226	  return (
227	    <div ref={wrapRef} className="relative">
228	      <input
229	        id={id}
230	        aria-describedby={describedBy}
231	        role="combobox"
232	        aria-expanded={open}
233	        aria-controls={listId}
234	        aria-autocomplete="list"
235	        value={open ? query : selected?.label ?? ""}
236	        placeholder={placeholder}
237	        onChange={(e) => { setQuery(e.target.value); setOpen(true); setActive(0); }}
238	        onFocus={() => setOpen(true)}
239	        onKeyDown={(e) => {
240	          if (e.key === "ArrowDown") { e.preventDefault(); setOpen(true); setActive((i) => Math.min(i + 1, filtered.length - 1)); }
241	          else if (e.key === "ArrowUp") { e.preventDefault(); setActive((i) => Math.max(i - 1, 0)); }
242	          else if (e.key === "Enter" && open && filtered[active]) { e.preventDefault(); commit(filtered[active].value); }
243	          else if (e.key === "Escape") { setOpen(false); }
244	        }}
245	        className={`${CONTROL_BASE} h-10 border-hairline pr-9`}
246	      />
247	      <Icon name="search" size="md" className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-ink-muted" />
248	      {open && (
249	        <ul
250	          id={listId}
251	          role="listbox"
252	          className="absolute left-0 right-0 top-[calc(100%+4px)] z-[var(--nx-z-overlay)] max-h-64 overflow-y-auto rounded-md border border-hairline-strong bg-surface py-1 shadow-overlay"
253	        >
254	          {filtered.length === 0 && (
255	            <li className="px-3 py-2 text-body-sm text-ink-muted">No matches for “{query}”.</li>
256	          )}
257	          {filtered.map((o, i) => (
258	            <li key={o.value} role="option" aria-selected={o.value === value}>
259	              <button
260	                type="button"
261	                onMouseEnter={() => setActive(i)}
262	                onClick={() => commit(o.value)}
263	                className={`flex w-full items-center gap-2.5 px-3 py-2 text-left text-body-sm transition-colors duration-[var(--nx-dur-1)] ${
264	                  i === active ? "bg-interactive text-ink" : "text-ink-secondary"
265	                }`}
266	              >
267	                {o.icon && <Icon name={o.icon} size="md" className="text-ink-muted" />}
268	                <span className="flex-1">{o.label}</span>
269	                {o.hint && <span className="font-mono text-caption text-ink-muted">{o.hint}</span>}
270	                {o.value === value && <Icon name="check" size="sm" className="text-signal-text" />}
271	              </button>
272	            </li>
273	          ))}
274	        </ul>
275	      )}
276	    </div>
277	  );
278	}
279	
280	/* ------------------------------------------------------------- TOGGLE */
281	/** One switch for the product. The old portal had six, in two sizes and two
282	    DOM strategies, none using the switch role. */
283	export function Toggle({
284	  checked, onChange, label, description, disabled,
285	}: { checked: boolean; onChange?: (v: boolean) => void; label: string; description?: string; disabled?: boolean }) {
286	  return (
287	    <label className={`flex items-start gap-3 ${disabled ? "opacity-50" : "cursor-pointer"}`}>
288	      <button
289	        type="button"
290	        role="switch"
291	        aria-checked={checked}
292	        aria-label={label}
293	        disabled={disabled}
294	        onClick={() => onChange?.(!checked)}
295	        className={`relative mt-0.5 h-5 w-9 shrink-0 rounded-pill border transition-colors duration-[var(--nx-dur-1)] ease-[var(--nx-ease)] ${
296	          checked ? "border-signal bg-signal" : "border-hairline-strong bg-interactive"
297	        } ${disabled ? "cursor-not-allowed" : ""}`}
298	      >
299	        <span
300	          className={`absolute top-1/2 h-3.5 w-3.5 -translate-y-1/2 rounded-full bg-white transition-[left] duration-[var(--nx-dur-1)] ease-[var(--nx-ease)] ${
301	            checked ? "left-[1.125rem]" : "left-0.5"
302	          }`}
303	        />
304	      </button>
305	      <span className="min-w-0">
306	        <span className="block text-body-sm font-medium text-ink">{label}</span>
307	        {description && <span className="block text-caption text-ink-muted">{description}</span>}
308	      </span>
309	    </label>
310	  );
311	}
312	
313	/* ---------------------------------------------------- CHECKBOX / RADIO */
314	export function Checkbox({
315	  checked, onChange, label, description, disabled,
316	}: { checked: boolean; onChange?: (v: boolean) => void; label: string; description?: string; disabled?: boolean }) {
317	  return (
318	    <label className={`flex items-start gap-3 ${disabled ? "opacity-50" : "cursor-pointer"}`}>
319	      <span className="relative mt-0.5 flex h-[1.125rem] w-[1.125rem] shrink-0">
320	        <input
321	          type="checkbox"
322	          checked={checked}
323	          disabled={disabled}
324	          onChange={(e) => onChange?.(e.target.checked)}
325	          className="peer absolute inset-0 cursor-pointer opacity-0 disabled:cursor-not-allowed"
326	        />
327	        <span className={`pointer-events-none flex h-full w-full items-center justify-center rounded-sm border transition-colors duration-[var(--nx-dur-1)] peer-focus-visible:outline peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-signal-edge ${
328	          checked ? "border-signal bg-signal text-white" : "border-hairline-strong bg-plate text-transparent"
329	        }`}>
330	          <Icon name="check" size="sm" />
331	        </span>
332	      </span>
333	      <span className="min-w-0">
334	        <span className="block text-body-sm font-medium text-ink">{label}</span>
335	        {description && <span className="block text-caption text-ink-muted">{description}</span>}
336	      </span>
337	    </label>
338	  );
339	}
340	
341	export function Radio({
342	  checked, onChange, label, description, name, disabled,
343	}: { checked: boolean; onChange?: () => void; label: string; description?: string; name: string; disabled?: boolean }) {
344	  return (
345	    <label className={`flex items-start gap-3 ${disabled ? "opacity-50" : "cursor-pointer"}`}>
346	      <span className="relative mt-0.5 flex h-[1.125rem] w-[1.125rem] shrink-0">
347	        <input
348	          type="radio" name={name} checked={checked} disabled={disabled} onChange={() => onChange?.()}
349	          className="peer absolute inset-0 cursor-pointer opacity-0 disabled:cursor-not-allowed"
350	        />
351	        <span className={`pointer-events-none flex h-full w-full items-center justify-center rounded-full border transition-colors duration-[var(--nx-dur-1)] peer-focus-visible:outline peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-signal-edge ${
352	          checked ? "border-signal" : "border-hairline-strong bg-plate"
353	        }`}>
354	          {checked && <span className="h-2 w-2 rounded-full bg-signal" />}
355	        </span>
356	      </span>
357	      <span className="min-w-0">
358	        <span className="block text-body-sm font-medium text-ink">{label}</span>
359	        {description && <span className="block text-caption text-ink-muted">{description}</span>}
360	      </span>
361	    </label>
362	  );
363	}
