"use client";

/* ============================================================================
   BUTTONS AND FORM CONTROLS
   Every control ships default, hover, active, focus, disabled, loading,
   error and success. Sizes are variants, never overrides — the old portal
   hand-tuned every small button because no size variant existed.
   ========================================================================= */

import {
  useId, useState, useRef, useEffect,
  type ButtonHTMLAttributes, type InputHTMLAttributes,
  type SelectHTMLAttributes, type ReactNode,
} from "react";
import { Icon, type IconName } from "./Icon";

/* ------------------------------------------------------------- BUTTON */
type Variant = "deploy" | "brand" | "primary" | "secondary" | "ghost" | "danger" | "ai";
type Size = "sm" | "md" | "lg";

const VARIANT: Record<Variant, string> = {
  /* The Deploy CTA. Hover behaviour carried over verbatim from production:
     gradient shift, shimmer sweep, 1px lift, arrow nudge. */
  deploy: "nx-deploy border-0",
  /* The brand gradient action. Reserved for the single most important
     commitment on a screen — deploy, pay, go live. One per view, never two. */
  brand:
    "nx-cta text-white border-0 hover:brightness-[1.06] active:brightness-95",
  primary:
    "bg-signal text-white border border-signal hover:bg-signal-hover active:bg-signal-press",
  secondary:
    "bg-interactive text-ink border border-hairline-strong hover:bg-[#22304a] hover:border-[#3a4a66] active:bg-interactive",
  ghost:
    "bg-transparent text-ink-secondary border border-transparent hover:bg-interactive hover:text-ink active:bg-[#22304a]",
  danger:
    "bg-transparent text-danger-text border border-danger-text/40 hover:bg-danger/25 hover:border-danger-text/70 active:bg-danger/35",
  ai:
    "bg-ai text-white border border-ai hover:brightness-110 active:brightness-95",
};

const SIZE: Record<Size, string> = {
  sm: "h-8 px-3 text-[0.8125rem] gap-1.5",
  md: "h-10 px-4 text-body-sm gap-2",
  lg: "h-12 px-5 text-body gap-2",
};

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: Variant;
  size?: Size;
  loading?: boolean;
  icon?: IconName;
  iconRight?: IconName;
  block?: boolean;
}

export function Button({
  variant = "secondary", size = "md", loading, icon, iconRight, block,
  className = "", children, disabled, ...rest
}: ButtonProps) {
  return (
    <button
      className={`inline-flex items-center justify-center rounded-md font-display font-semibold
        transition-[background-color,border-color,color] duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
        disabled:cursor-not-allowed disabled:opacity-45
        ${VARIANT[variant]} ${SIZE[size]} ${block ? "w-full" : ""} ${className}`}
      disabled={disabled || loading}
      aria-busy={loading || undefined}
      {...rest}
    >
      {loading ? (
        <Icon name="spinner" size={size === "lg" ? "lg" : "md"} className="animate-spin" />
      ) : icon ? (
        <Icon name={icon} size={size === "lg" ? "lg" : "md"} />
      ) : null}
      {children}
      {iconRight && !loading && (
        <Icon name={iconRight} size={size === "lg" ? "lg" : "md"}
          className={variant === "deploy" ? "nx-arrow" : undefined} />
      )}
    </button>
  );
}

/** Icon-only control. The label is required, not optional — that is how the
    nine unnamed icon buttons in the old portal stop being possible. */
export function IconButton({
  name, label, variant = "ghost", size = "md", className = "", ...rest
}: { name: IconName; label: string; variant?: Variant; size?: Size } & ButtonHTMLAttributes<HTMLButtonElement>) {
  const box = size === "sm" ? "h-8 w-8" : size === "lg" ? "h-12 w-12" : "h-10 w-10";
  return (
    <button
      aria-label={label}
      title={label}
      className={`inline-flex items-center justify-center rounded-md
        transition-[background-color,border-color,color] duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
        disabled:cursor-not-allowed disabled:opacity-45 ${VARIANT[variant]} ${box} ${className}`}
      {...rest}
    >
      <Icon name={name} size={size === "sm" ? "sm" : size === "lg" ? "lg" : "md"} />
    </button>
  );
}

/* -------------------------------------------------------------- FIELD */
interface FieldProps {
  label: string;
  hint?: string;
  error?: string;
  success?: string;
  required?: boolean;
  children: (props: { id: string; describedBy?: string; invalid: boolean }) => ReactNode;
}
/** One label, hint, error and success structure for every form in the
    product. 61% of labels in the old portal had no programmatic association;
    here association is produced by the wrapper, not by discipline. */
export function Field({ label, hint, error, success, required, children }: FieldProps) {
  const id = useId();
  const hintId = `${id}-hint`;
  const msgId = `${id}-msg`;
  const describedBy = [hint ? hintId : null, error || success ? msgId : null]
    .filter(Boolean).join(" ") || undefined;

  return (
    <div className="flex flex-col gap-1.5">
      <label htmlFor={id} className="font-display text-label uppercase tracking-[0.11em] text-ink-secondary">
        {label}
        {required && <span className="ml-1 text-danger-text" aria-hidden="true">*</span>}
      </label>
      {hint && <p id={hintId} className="text-caption text-ink-muted">{hint}</p>}
      {children({ id, describedBy, invalid: Boolean(error) })}
      {(error || success) && (
        <p
          id={msgId}
          role={error ? "alert" : "status"}
          className={`flex items-start gap-1.5 text-caption ${error ? "text-danger-text" : "text-success-text"}`}
        >
          <Icon name={error ? "alert" : "check"} size="sm" className="mt-0.5" />
          <span>{error || success}</span>
        </p>
      )}
    </div>
  );
}

const CONTROL_BASE =
  "w-full rounded-md border bg-plate px-3 text-body text-ink placeholder:text-ink-muted " +
  "transition-[border-color,background-color] duration-[var(--nx-dur-1)] " +
  "hover:border-hairline-strong disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:border-hairline";

/* -------------------------------------------------------------- INPUT */
export function Input({
  invalid, mono, className = "", ...rest
}: { invalid?: boolean; mono?: boolean } & InputHTMLAttributes<HTMLInputElement>) {
  return (
    <input
      aria-invalid={invalid || undefined}
      className={`${CONTROL_BASE} h-10 ${invalid ? "border-danger-text/60" : "border-hairline"} ${mono ? "font-mono text-code" : ""} ${className}`}
      {...rest}
    />
  );
}

/* ------------------------------------------------------------- SELECT */
export function Select({
  invalid, className = "", children, ...rest
}: { invalid?: boolean } & SelectHTMLAttributes<HTMLSelectElement>) {
  return (
    <div className="relative">
      <select
        aria-invalid={invalid || undefined}
        className={`${CONTROL_BASE} h-10 appearance-none pr-9 ${invalid ? "border-danger-text/60" : "border-hairline"} ${className}`}
        {...rest}
      >
        {children}
      </select>
      <Icon name="chevronDown" size="md"
        className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-ink-muted" />
    </div>
  );
}

/* ----------------------------------------------------------- TEXTAREA */
export function Textarea({
  invalid, className = "", ...rest
}: { invalid?: boolean } & InputHTMLAttributes<HTMLTextAreaElement>) {
  return (
    <textarea
      aria-invalid={invalid || undefined}
      className={`${CONTROL_BASE} min-h-24 resize-y py-2.5 ${invalid ? "border-danger-text/60" : "border-hairline"} ${className}`}
      {...(rest as object)}
    />
  );
}

/* ----------------------------------------------------------- COMBOBOX */
export interface ComboOption { value: string; label: string; hint?: string; icon?: IconName }
/** Filterable single-select with full keyboard support. */
export function Combobox({
  options, value, onChange, placeholder = "Search…", id, describedBy,
}: {
  options: ComboOption[]; value?: string; onChange?: (v: string) => void;
  placeholder?: string; id?: string; describedBy?: string;
}) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(0);
  const wrapRef = useRef<HTMLDivElement>(null);
  const listId = useId();

  const selected = options.find((o) => o.value === value);
  const filtered = query
    ? options.filter((o) => o.label.toLowerCase().includes(query.toLowerCase()))
    : options;

  useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, [open]);

  const commit = (v: string) => { onChange?.(v); setOpen(false); setQuery(""); };

  return (
    <div ref={wrapRef} className="relative">
      <input
        id={id}
        aria-describedby={describedBy}
        role="combobox"
        aria-expanded={open}
        aria-controls={listId}
        aria-autocomplete="list"
        value={open ? query : selected?.label ?? ""}
        placeholder={placeholder}
        onChange={(e) => { setQuery(e.target.value); setOpen(true); setActive(0); }}
        onFocus={() => setOpen(true)}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown") { e.preventDefault(); setOpen(true); setActive((i) => Math.min(i + 1, filtered.length - 1)); }
          else if (e.key === "ArrowUp") { e.preventDefault(); setActive((i) => Math.max(i - 1, 0)); }
          else if (e.key === "Enter" && open && filtered[active]) { e.preventDefault(); commit(filtered[active].value); }
          else if (e.key === "Escape") { setOpen(false); }
        }}
        className={`${CONTROL_BASE} h-10 border-hairline pr-9`}
      />
      <Icon name="search" size="md" className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-ink-muted" />
      {open && (
        <ul
          id={listId}
          role="listbox"
          className="absolute left-0 right-0 top-[calc(100%+4px)] z-[var(--nx-z-overlay)] max-h-64 overflow-y-auto rounded-md border border-hairline-strong bg-surface py-1 shadow-overlay"
        >
          {filtered.length === 0 && (
            <li className="px-3 py-2 text-body-sm text-ink-muted">No matches for “{query}”.</li>
          )}
          {filtered.map((o, i) => (
            <li key={o.value} role="option" aria-selected={o.value === value}>
              <button
                type="button"
                onMouseEnter={() => setActive(i)}
                onClick={() => commit(o.value)}
                className={`flex w-full items-center gap-2.5 px-3 py-2 text-left text-body-sm transition-colors duration-[var(--nx-dur-1)] ${
                  i === active ? "bg-interactive text-ink" : "text-ink-secondary"
                }`}
              >
                {o.icon && <Icon name={o.icon} size="md" className="text-ink-muted" />}
                <span className="flex-1">{o.label}</span>
                {o.hint && <span className="font-mono text-caption text-ink-muted">{o.hint}</span>}
                {o.value === value && <Icon name="check" size="sm" className="text-signal-text" />}
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/* ------------------------------------------------------------- TOGGLE */
/** One switch for the product. The old portal had six, in two sizes and two
    DOM strategies, none using the switch role. */
export function Toggle({
  checked, onChange, label, description, disabled,
}: { checked: boolean; onChange?: (v: boolean) => void; label: string; description?: string; disabled?: boolean }) {
  return (
    <label className={`flex items-start gap-3 ${disabled ? "opacity-50" : "cursor-pointer"}`}>
      <button
        type="button"
        role="switch"
        aria-checked={checked}
        aria-label={label}
        disabled={disabled}
        onClick={() => onChange?.(!checked)}
        className={`relative mt-0.5 h-5 w-9 shrink-0 rounded-pill border transition-colors duration-[var(--nx-dur-1)] ease-[var(--nx-ease)] ${
          checked ? "border-signal bg-signal" : "border-hairline-strong bg-interactive"
        } ${disabled ? "cursor-not-allowed" : ""}`}
      >
        <span
          className={`absolute top-1/2 h-3.5 w-3.5 -translate-y-1/2 rounded-full bg-white transition-[left] duration-[var(--nx-dur-1)] ease-[var(--nx-ease)] ${
            checked ? "left-[1.125rem]" : "left-0.5"
          }`}
        />
      </button>
      <span className="min-w-0">
        <span className="block text-body-sm font-medium text-ink">{label}</span>
        {description && <span className="block text-caption text-ink-muted">{description}</span>}
      </span>
    </label>
  );
}

/* ---------------------------------------------------- CHECKBOX / RADIO */
export function Checkbox({
  checked, onChange, label, description, disabled,
}: { checked: boolean; onChange?: (v: boolean) => void; label: string; description?: string; disabled?: boolean }) {
  return (
    <label className={`flex items-start gap-3 ${disabled ? "opacity-50" : "cursor-pointer"}`}>
      <span className="relative mt-0.5 flex h-[1.125rem] w-[1.125rem] shrink-0">
        <input
          type="checkbox"
          checked={checked}
          disabled={disabled}
          onChange={(e) => onChange?.(e.target.checked)}
          className="peer absolute inset-0 cursor-pointer opacity-0 disabled:cursor-not-allowed"
        />
        <span className={`pointer-events-none flex h-full w-full items-center justify-center rounded-sm border transition-colors duration-[var(--nx-dur-1)] peer-focus-visible:outline peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-signal-edge ${
          checked ? "border-signal bg-signal text-white" : "border-hairline-strong bg-plate text-transparent"
        }`}>
          <Icon name="check" size="sm" />
        </span>
      </span>
      <span className="min-w-0">
        <span className="block text-body-sm font-medium text-ink">{label}</span>
        {description && <span className="block text-caption text-ink-muted">{description}</span>}
      </span>
    </label>
  );
}

export function Radio({
  checked, onChange, label, description, name, disabled,
}: { checked: boolean; onChange?: () => void; label: string; description?: string; name: string; disabled?: boolean }) {
  return (
    <label className={`flex items-start gap-3 ${disabled ? "opacity-50" : "cursor-pointer"}`}>
      <span className="relative mt-0.5 flex h-[1.125rem] w-[1.125rem] shrink-0">
        <input
          type="radio" name={name} checked={checked} disabled={disabled} onChange={() => onChange?.()}
          className="peer absolute inset-0 cursor-pointer opacity-0 disabled:cursor-not-allowed"
        />
        <span className={`pointer-events-none flex h-full w-full items-center justify-center rounded-full border transition-colors duration-[var(--nx-dur-1)] peer-focus-visible:outline peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-signal-edge ${
          checked ? "border-signal" : "border-hairline-strong bg-plate"
        }`}>
          {checked && <span className="h-2 w-2 rounded-full bg-signal" />}
        </span>
      </span>
      <span className="min-w-0">
        <span className="block text-body-sm font-medium text-ink">{label}</span>
        {description && <span className="block text-caption text-ink-muted">{description}</span>}
      </span>
    </label>
  );
}

