"use client";

/* ============================================================================
   CORE SHELL
   The foundational frame only — enough to demonstrate the system. No product
   pages are migrated into it in Phase 2.

   Geometry is a contract, not a per-page decision:
     rail 15rem (collapsed 4.5rem) · header 3.5rem · content max 90rem
   ========================================================================= */

import { useEffect, useState, type ReactNode } from "react";
import { Icon, type IconName } from "../system/Icon";
import { IconButton } from "../system/controls";
import { Badge } from "../system/primitives";

export interface NavItem {
  id: string;
  label: string;
  icon: IconName;
  badge?: string | number;
  /** Marks a kind the customer does not own yet — grouped under Explore. */
  owned?: boolean;
}
export interface NavGroup { label?: string; items: NavItem[] }

/** Up to four thumb-reachable destinations plus More. Mobile navigation is a
    bar, not a hamburger: a drawer costs two taps for every move, and the
    brief is explicit that mobile is not a shrunken desktop. */
export interface BottomNavItem { id: string; label: string; icon: IconName }

export function AppShell({
  groups, active, onNavigate, children, title = "Nxeon", bottomNav = [],
}: {
  groups: NavGroup[]; active: string; onNavigate: (id: string) => void;
  children: ReactNode; title?: string; bottomNav?: BottomNavItem[];
}) {
  const [collapsed, setCollapsed] = useState(false);
  const [drawer, setDrawer] = useState(false);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") setDrawer(false); };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, []);

  const railWidth = collapsed ? "lg:w-18" : "lg:w-60";

  return (
    <div className="relative z-[var(--nx-z-raised)] flex min-h-screen">
      {/* Mobile scrim */}
      {drawer && (
        <div
          className="fixed inset-0 z-[var(--nx-z-scrim)] bg-scrim/75 lg:hidden"
          onClick={() => setDrawer(false)}
          aria-hidden="true"
        />
      )}

      {/* ---------------------------------------------------------- RAIL */}
      <aside
        id="nx-rail"
        inert={!drawer && typeof window !== "undefined" && window.innerWidth < 1024 ? true : undefined}
        className={`fixed inset-y-0 left-0 z-[var(--nx-z-rail)] flex w-60 flex-col border-r border-hairline bg-surface
          transition-transform duration-[var(--nx-dur-3)] ease-[var(--nx-ease)]
          ${drawer ? "translate-x-0" : "-translate-x-full"}
          lg:sticky lg:top-0 lg:h-screen lg:translate-x-0 ${railWidth}`}
      >
        {/* Brand */}
        <div className="flex h-14 shrink-0 items-center gap-2.5 border-b border-hairline px-4">
          <NxeonMark />
          {!collapsed && (
            <span className="font-display text-h4 font-bold tracking-[-0.01em] text-ink">{title}</span>
          )}
          <div className="ml-auto lg:hidden">
            <IconButton name="close" label="Close navigation" size="sm" onClick={() => setDrawer(false)} />
          </div>
        </div>

        {/* Nav */}
        <nav aria-label="Primary" className="min-h-0 flex-1 overflow-y-auto px-2.5 py-3">
          {groups.map((g, gi) => (
            <div key={g.label ?? gi} className="mb-4 last:mb-0">
              {g.label && !collapsed && (
                <div className="mb-1.5 px-2 font-display text-label uppercase tracking-[0.13em] text-ink-muted">
                  {g.label}
                </div>
              )}
              {g.label && collapsed && <div className="mx-2 mb-2 h-px bg-hairline" />}
              <ul className="flex flex-col gap-0.5">
                {g.items.map((it) => {
                  const on = it.id === active;
                  return (
                    <li key={it.id}>
                      <button
                        type="button"
                        onClick={() => { onNavigate(it.id); setDrawer(false); }}
                        aria-current={on ? "page" : undefined}
                        title={collapsed ? it.label : undefined}
                        className={`group relative flex w-full items-center gap-2.5 rounded-md py-2 pl-3 pr-2 text-left
                          font-display text-body-sm font-medium
                          transition-colors duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
                          ${on ? "bg-interactive text-ink" : "text-ink-secondary hover:bg-surface hover:text-ink"}
                          ${collapsed ? "lg:justify-center lg:px-0" : ""}`}
                      >
                        {/* The Nxeon active indicator: a signal filament, not a filled pill */}
                        <span
                          className={`absolute left-0 top-1/2 h-5 w-0.5 -translate-y-1/2 rounded-pill transition-all duration-[var(--nx-dur-1)] ${
                            on ? "bg-signal-edge opacity-100" : "bg-transparent opacity-0"
                          }`}
                          aria-hidden="true"
                        />
                        <Icon name={it.icon} size="md" className={on ? "text-signal-text" : "text-ink-muted group-hover:text-ink-secondary"} />
                        {!collapsed && <span className="flex-1 truncate">{it.label}</span>}
                        {!collapsed && it.badge !== undefined && (
                          <span className="rounded-sm bg-plate px-1.5 py-0.5 font-mono text-[0.6875rem] tabular-nums text-ink-secondary">
                            {it.badge}
                          </span>
                        )}
                        {collapsed && it.badge !== undefined && (
                          <span className="absolute right-2 top-1.5 h-1.5 w-1.5 rounded-full bg-signal-edge" aria-hidden="true" />
                        )}
                      </button>
                    </li>
                  );
                })}
              </ul>
            </div>
          ))}
        </nav>

        {/* Rail footer */}
        <div className="shrink-0 border-t border-hairline p-2.5">
          <button
            type="button"
            onClick={() => setCollapsed((v) => !v)}
            className={`hidden w-full items-center gap-2.5 rounded-md px-3 py-2 font-display text-caption font-medium text-ink-muted transition-colors duration-[var(--nx-dur-1)] hover:bg-surface hover:text-ink lg:flex ${
              collapsed ? "justify-center px-0" : ""
            }`}
            aria-label={collapsed ? "Expand navigation" : "Collapse navigation"}
          >
            <Icon name="collapse" size="md" className={collapsed ? "rotate-180" : ""} />
            {!collapsed && <span>Collapse</span>}
          </button>
        </div>
      </aside>

      {/* -------------------------------------------------------- COLUMN */}
      <div className="flex min-w-0 flex-1 flex-col">
        <header className="sticky top-0 z-[var(--nx-z-sticky)] flex h-14 shrink-0 items-center gap-3 border-b border-hairline bg-base/85 px-4 backdrop-blur-md sm:px-6">
          <div className="lg:hidden">
            <IconButton
              name="menu" label="Open navigation" size="sm"
              aria-expanded={drawer} aria-controls="nx-rail"
              onClick={() => setDrawer(true)}
            />
          </div>

          <button
            type="button"
            className="group flex h-9 min-w-0 flex-1 items-center gap-2.5 rounded-md border border-hairline bg-surface px-3 text-left transition-colors duration-[var(--nx-dur-1)] hover:border-hairline-strong sm:max-w-md"
          >
            <Icon name="search" size="md" className="text-ink-muted" />
            <span className="flex-1 truncate text-body-sm text-ink-muted">Search or run a command…</span>
            <kbd className="hidden rounded-sm border border-hairline-strong bg-plate px-1.5 py-0.5 font-mono text-[0.6875rem] text-ink-muted sm:block">
              ⌘K
            </kbd>
          </button>

          <div className="ml-auto flex items-center gap-1.5">
            <span className="hidden sm:block"><Badge tone="signal" size="sm">Sandbox</Badge></span>
            <IconButton name="bell" label="Notifications" size="sm" />
            <span className="ml-1 flex h-8 w-8 items-center justify-center rounded-md border border-hairline-strong bg-interactive font-display text-caption font-semibold text-ink">
              N
            </span>
          </div>
        </header>

        <main
          id="nx-main"
          className="mx-auto w-full max-w-[90rem] flex-1 px-4 py-6 sm:px-6 lg:px-7"
          style={{ paddingBottom: bottomNav.length ? "calc(5.25rem + env(safe-area-inset-bottom))" : undefined }}
        >
          {children}
        </main>

        {/* ---------------------------------------------------- BOTTOM NAV */}
        {bottomNav.length > 0 && (
          <nav
            aria-label="Primary, compact"
            className="fixed inset-x-0 bottom-0 z-[var(--nx-z-sticky)] flex border-t border-hairline bg-surface/95 backdrop-blur-md lg:hidden"
            style={{ paddingBottom: "env(safe-area-inset-bottom)" }}
          >
            {bottomNav.slice(0, 4).map((it) => {
              const on = it.id === active;
              return (
                <button
                  key={it.id}
                  type="button"
                  onClick={() => onNavigate(it.id)}
                  aria-current={on ? "page" : undefined}
                  className={`relative flex min-h-14 flex-1 flex-col items-center justify-center gap-1 px-1 py-2
                    font-display text-[0.6875rem] font-semibold transition-colors duration-[var(--nx-dur-1)]
                    ${on ? "text-ink" : "text-ink-muted"}`}
                >
                  {on && (
                    <span className="nx-grad-brand absolute inset-x-3 top-0 h-0.5 rounded-pill" aria-hidden="true" />
                  )}
                  <Icon name={it.icon} size="lg" className={on ? "text-signal-text" : undefined} />
                  <span className="truncate">{it.label}</span>
                </button>
              );
            })}
            <button
              type="button"
              onClick={() => setDrawer(true)}
              aria-label="More"
              aria-expanded={drawer}
              aria-controls="nx-rail"
              className="flex min-h-14 flex-1 flex-col items-center justify-center gap-1 px-1 py-2 font-display text-[0.6875rem] font-semibold text-ink-muted"
            >
              <Icon name="menu" size="lg" />
              <span>More</span>
            </button>
          </nav>
        )}
      </div>
    </div>
  );
}

/** The mark, drawn rather than raster — the audit found no vector master
    existed and every consumer scaled one 496x85 PNG. */
export function NxeonMark({ size = 22 }: { size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" aria-hidden="true" className="shrink-0">
      <defs>
        <linearGradient id="nx-mark-grad" x1="0" y1="1" x2="1" y2="0">
          <stop offset="0%" stopColor="var(--color-brand-a)" />
          <stop offset="55%" stopColor="var(--color-brand-b)" />
          <stop offset="100%" stopColor="var(--color-brand-c)" />
        </linearGradient>
      </defs>
      <path d="M3 20V4l9 12V4" fill="none" stroke="url(#nx-mark-grad)" strokeWidth="2.3"
        strokeLinecap="round" strokeLinejoin="round" />
      <path d="M15.5 8.5 21 15.5M21 8.5l-5.5 7" fill="none" stroke="url(#nx-mark-grad)" strokeWidth="2.3"
        strokeLinecap="round" />
