"use client";

/* ============================================================================
   LOADING, EMPTY, ERROR, SUCCESS — and the deployment ladder
   The old portal served all 58 routes from one loading file and one error
   file, showed "Something went wrong" eleven times, and had no not-found
   inside the shell at all. Each state here is a designed surface.
   ========================================================================= */

import { useState, type ReactNode } from "react";
import { Icon, type IconName } from "./Icon";
import { Button } from "./controls";
import { EmptySlot, BrokenPath, ConvergedNode, EmptySearch } from "./illustrations";

/* ------------------------------------------------------------ SKELETON */
export function Skeleton({ className = "" }: { className?: string }) {
  return <div className={`animate-nx-pulse rounded-sm bg-interactive ${className}`} aria-hidden="true" />;
}

/** Shape-matched loading. A skeleton should predict the content that follows,
    which is why this takes a shape rather than being one generic block. */
export function LoadingState({ shape = "list", label = "Loading" }: { shape?: "list" | "metrics" | "detail"; label?: string }) {
  return (
    <div role="status" aria-live="polite" aria-busy="true">
      <span className="sr-only">{label}…</span>
      {shape === "metrics" && (
        <div className="grid grid-cols-2 gap-px overflow-hidden rounded-lg border border-hairline bg-hairline lg:grid-cols-4">
          {Array.from({ length: 4 }).map((_, i) => (
            <div key={i} className="flex flex-col gap-2.5 bg-surface px-4 py-3.5">
              <Skeleton className="h-3 w-20" />
              <Skeleton className="h-7 w-24" />
            </div>
          ))}
        </div>
      )}
      {shape === "list" && (
        <div className="flex flex-col gap-2">
          {Array.from({ length: 4 }).map((_, i) => (
            <div key={i} className="nx-object flex items-center gap-4 px-4 py-3.5">
              <Skeleton className="h-8 w-8 rounded-md" />
              <div className="flex flex-1 flex-col gap-2">
                <Skeleton className="h-3.5 w-40" />
                <Skeleton className="h-3 w-64" />
              </div>
              <Skeleton className="h-7 w-20 rounded-md" />
            </div>
          ))}
        </div>
      )}
      {shape === "detail" && (
        <div className="flex flex-col gap-5">
          <Skeleton className="h-8 w-64" />
          <div className="grid gap-3 sm:grid-cols-2">
            <Skeleton className="h-24" /><Skeleton className="h-24" />
          </div>
          <Skeleton className="h-40" />
        </div>
      )}
    </div>
  );
}

export function Spinner({ label = "Working" }: { label?: string }) {
  return (
    <span role="status" className="inline-flex items-center gap-2 text-ink-muted">
      <Icon name="spinner" size="md" className="animate-spin" />
      <span className="text-body-sm">{label}…</span>
    </span>
  );
}

/* --------------------------------------------------------- EMPTY STATE */
/** Explains the situation and offers the next action. Never "No data." */
export function EmptyState({
  art = "slot", title, description, action, secondary,
}: { art?: "slot" | "search"; title: string; description: string; action?: ReactNode; secondary?: ReactNode }) {
  const Art = art === "search" ? EmptySearch : EmptySlot;
  return (
    <div className="nx-container-surface relative flex flex-col items-center overflow-hidden px-6 py-11 text-center">
      <div className="nx-grid-field nx-grid-mask pointer-events-none absolute inset-0" aria-hidden="true" />
      <Art className="relative mb-4" size={148} />
      <h3 className="relative text-h3 text-ink">{title}</h3>
      <p className="relative mt-2 max-w-[48ch] text-body-sm text-ink-secondary">{description}</p>
      {(action || secondary) && (
        <div className="relative mt-5 flex flex-wrap items-center justify-center gap-2">{action}{secondary}</div>
      )}
    </div>
  );
}

/* --------------------------------------------------------- ERROR STATE */
/** What happened, why, and how to fix it. Technical detail is available but
    never leads — the old portal put a bare digest on screen in a tone that
    failed contrast. */
export function ErrorState({
  title, reason, fix, technical, onRetry, onSupport,
}: {
  title: string; reason?: string; fix?: string; technical?: string;
  onRetry?: () => void; onSupport?: () => void;
}) {
  const [open, setOpen] = useState(false);
  return (
    <div className="nx-container-surface px-6 py-10" role="alert">
      <div className="mx-auto flex max-w-[52ch] flex-col items-center text-center">
        <BrokenPath className="mb-4" size={148} />
        <h3 className="text-h3 text-ink">{title}</h3>
        {reason && <p className="mt-2 text-body-sm text-ink-secondary">{reason}</p>}
        {fix && <p className="mt-2 text-body-sm text-ink-secondary">{fix}</p>}
        <div className="mt-5 flex flex-wrap items-center justify-center gap-2">
          {onRetry && <Button variant="primary" icon="restart" onClick={onRetry}>Try again</Button>}
          {onSupport && <Button variant="secondary" icon="support" onClick={onSupport}>Contact support</Button>}
        </div>
        {technical && (
          <div className="mt-5 w-full">
            <button
              type="button"
              onClick={() => setOpen((v) => !v)}
              aria-expanded={open}
              className="inline-flex items-center gap-1.5 font-display text-caption font-semibold text-ink-muted transition-colors duration-[var(--nx-dur-1)] hover:text-ink-secondary"
            >
              <Icon name="chevronRight" size="sm" className={open ? "rotate-90 transition-transform" : "transition-transform"} />
              View technical details
            </button>
            {open && (
              <pre className="nx-plate mt-2 overflow-x-auto px-3 py-2 text-left text-code text-ink-secondary">{technical}</pre>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

/* ------------------------------------------------------- SUCCESS STATE */
/** Rewarding without celebration effects: an elegant mark, the facts, and
    the one next action. */
export function SuccessState({
  title, summary, facts, action,
}: { title: string; summary?: string; facts?: { label: string; value: string; mono?: boolean }[]; action?: ReactNode }) {
  return (
    <div className="nx-container-surface px-6 py-10">
      <div className="mx-auto flex max-w-[52ch] flex-col items-center text-center">
        <ConvergedNode className="mb-4" size={152} />
        <h3 className="text-h2 text-ink">{title}</h3>
        {summary && <p className="mt-2 text-body-sm text-ink-secondary">{summary}</p>}
        {facts && (
          <dl className="mt-5 grid w-full grid-cols-1 gap-px overflow-hidden rounded-lg border border-hairline bg-hairline sm:grid-cols-2">
            {facts.map((f) => (
              <div key={f.label} className="bg-surface px-4 py-3 text-left">
                <dt className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">{f.label}</dt>
                <dd className={`mt-1 text-body-sm text-ink ${f.mono ? "font-mono text-code" : ""}`}>{f.value}</dd>
              </div>
            ))}
          </dl>
        )}
        {action && <div className="mt-5">{action}</div>}
      </div>
    </div>
  );
}

/* ---------------------------------------------------- DEPLOYMENT LADDER */
export type RungState = "done" | "active" | "pending" | "failed";
export interface Rung { label: string; state: RungState }

/**
 * The signature post-payment moment.
 *
 * Honesty rules, enforced by the component's own API:
 *   - it takes named stages, and there is no percentage prop to pass
 *   - it shows elapsed time and a typical range, never a countdown
 *   - past the expected window it says so and offers an action, rather than
 *     spinning silently
 * The backend reports six coarse stages and no progress figure, so six rungs
 * is exactly what this can honestly draw.
 */
export function DeploymentLadder({
  rungs, elapsedLabel, typicalLabel, overdue, onCheckStatus,
}: {
  rungs: Rung[]; elapsedLabel: string; typicalLabel: string;
  overdue?: boolean; onCheckStatus?: () => void;
}) {
  return (
    <div className="nx-container-surface overflow-hidden">
      <div className="relative flex flex-wrap items-baseline justify-between gap-2 overflow-hidden border-b border-hairline px-5 py-3.5">
        <span className="nx-grad-rule absolute inset-x-0 top-0" aria-hidden="true" />
        <span className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">Provisioning</span>
        <span className="font-mono text-caption tabular-nums text-ink-secondary">
          {elapsedLabel} <span className="text-ink-muted">· {typicalLabel}</span>
        </span>
      </div>

      <ol className="px-5 py-2" aria-live="polite">
        {rungs.map((r, i) => (
          <li key={r.label} className="flex items-start gap-3 py-2.5">
            <span className="relative flex flex-col items-center self-stretch" aria-hidden="true">
              <span
                className={`mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full border
                  ${r.state === "done" ? "border-success-text/50 bg-success/30 text-success-text"
                    : r.state === "active" ? "border-signal-edge bg-signal/25 text-signal-text"
                    : r.state === "failed" ? "border-danger-text/50 bg-danger/25 text-danger-text"
                    : "border-hairline-strong text-ink-disabled"}`}
              >
                {r.state === "done" && <Icon name="check" size="sm" />}
                {r.state === "active" && <span className="h-1.5 w-1.5 rounded-full bg-current animate-nx-pulse" />}
                {r.state === "failed" && <Icon name="close" size="sm" />}
              </span>
              {i < rungs.length - 1 && (
                <span className={`w-px flex-1 ${r.state === "done" ? "bg-success-text/35" : "bg-hairline"}`} />
              )}
            </span>
            <span className={`pt-0.5 text-body-sm ${
              r.state === "pending" ? "text-ink-muted"
                : r.state === "failed" ? "text-danger-text"
                : "text-ink"}`}>
              {r.label}
            </span>
          </li>
        ))}
      </ol>

      {overdue && (
        <div className="border-t border-hairline px-5 py-3.5">
          <p className="text-body-sm text-warning-text">
            This is taking longer than usual. Your server is still being built and you have not been charged twice.
          </p>
          {onCheckStatus && (
            <Button variant="secondary" size="sm" icon="support" className="mt-2.5" onClick={onCheckStatus}>
              Check status
            </Button>
          )}
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------ SETUP CHECKLIST */
export interface Task { label: string; detail?: string; done: boolean; optional?: boolean; action?: ReactNode }

/** Stage two of a purchase, and the standing task list on the dashboard.
    Skipped items do not vanish; they persist as tasks. */
export function SetupChecklist({ title, tasks }: { title: string; tasks: Task[] }) {
  const done = tasks.filter((t) => t.done).length;
  return (
    <div className="nx-container-surface overflow-hidden">
      <div className="flex flex-wrap items-baseline justify-between gap-2 border-b border-hairline px-5 py-3.5">
        <span className="font-display text-h4 text-ink">{title}</span>
        <span className="font-mono text-caption tabular-nums text-ink-muted">{done} of {tasks.length} done</span>
      </div>
      <ul className="divide-y divide-hairline">
        {tasks.map((t) => (
          <li key={t.label} className="flex items-start gap-3 px-5 py-3.5">
            <span
              className={`mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full border ${
                t.done ? "border-success-text/50 bg-success/30 text-success-text" : "border-hairline-strong text-transparent"
              }`}
              aria-hidden="true"
            >
              <Icon name="check" size="sm" />
            </span>
            <span className="min-w-0 flex-1">
              <span className={`block text-body-sm font-medium ${t.done ? "text-ink-secondary line-through decoration-hairline-strong" : "text-ink"}`}>
                {t.label}
                {t.optional && !t.done && (
                  <span className="ml-2 font-display text-label uppercase tracking-[0.11em] text-ink-muted">Optional</span>
                )}
              </span>
              {t.detail && <span className="mt-0.5 block text-caption text-ink-muted">{t.detail}</span>}
            </span>
            {t.action && <span className="shrink-0 self-center">{t.action}</span>}
          </li>
        ))}
      </ul>
    </div>
  );
}

