3	/* ============================================================================
4	   TABS, SEGMENTED CONTROLS, STEPPERS, PROGRESS, WIZARD
5	   One tab mechanism for the product. The old portal had eight tab-bar styles
6	   plus eight one-off segmented rows, and its two most-used implementations
7	   rewrote the URL without adding history, so Back left the page.
8	   ========================================================================= */
9	
10	import { useId, useRef, type ReactNode, type KeyboardEvent } from "react";
11	import { Icon, type IconName } from "./Icon";
12	
13	/* ---------------------------------------------------------------- TABS */
14	export interface TabItem { id: string; label: string; icon?: IconName; badge?: string | number; disabled?: boolean }
15	
16	/** Arrow keys move, Home and End jump, Enter and Space are implicit on a
17	    button. Roving tabindex, so the tab list is one stop in the page order. */
18	export function Tabs({
19	  items, active, onChange, ariaLabel = "Sections",
20	}: { items: TabItem[]; active: string; onChange: (id: string) => void; ariaLabel?: string }) {
21	  const ref = useRef<HTMLDivElement>(null);
22	  const base = useId();
23	
24	  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
25	    const enabled = items.filter((i) => !i.disabled);
26	    const idx = enabled.findIndex((i) => i.id === active);
27	    let next = -1;
28	    if (e.key === "ArrowRight") next = (idx + 1) % enabled.length;
29	    else if (e.key === "ArrowLeft") next = (idx - 1 + enabled.length) % enabled.length;
30	    else if (e.key === "Home") next = 0;
31	    else if (e.key === "End") next = enabled.length - 1;
32	    if (next >= 0) {
33	      e.preventDefault();
34	      onChange(enabled[next].id);
35	      const el = ref.current?.querySelector<HTMLButtonElement>(`#${CSS.escape(`${base}-${enabled[next].id}`)}`);
36	      el?.focus();
37	    }
38	  };
39	
40	  return (
41	    <div
42	      ref={ref}
43	      role="tablist"
44	      aria-label={ariaLabel}
45	      onKeyDown={onKeyDown}
46	      className="flex gap-0.5 overflow-x-auto border-b border-hairline"
47	    >
48	      {items.map((t) => {
49	        const on = t.id === active;
50	        return (
51	          <button
52	            key={t.id}
53	            id={`${base}-${t.id}`}
54	            role="tab"
55	            aria-selected={on}
56	            aria-controls={`${base}-panel-${t.id}`}
57	            tabIndex={on ? 0 : -1}
58	            disabled={t.disabled}
59	            onClick={() => onChange(t.id)}
60	            className={`relative -mb-px inline-flex shrink-0 items-center gap-2 whitespace-nowrap border-b-2 px-3.5 py-2.5 font-display text-body-sm font-semibold
61	              transition-colors duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
62	              disabled:cursor-not-allowed disabled:opacity-40
63	              ${on
64	                ? "border-signal-edge text-ink"
65	                : "border-transparent text-ink-muted hover:border-hairline-strong hover:text-ink-secondary"}`}
66	          >
67	            {t.icon && <Icon name={t.icon} size="md" />}
68	            {t.label}
69	            {t.badge !== undefined && (
70	              <span className="rounded-sm bg-interactive px-1.5 py-0.5 font-mono text-[0.6875rem] text-ink-secondary">
71	                {t.badge}
72	              </span>
73	            )}
74	          </button>
75	        );
76	      })}
77	    </div>
78	  );
79	}
80	
81	export function TabPanel({ id, active, children }: { id: string; active: string; children: ReactNode }) {
82	  if (id !== active) return null;
83	  return (
84	    <div role="tabpanel" className="animate-nx-fade pt-5">
85	      {children}
86	    </div>
87	  );
88	}
89	
90	/* --------------------------------------------------- SEGMENTED CONTROL */
91	/** For switching a view of the same data — a time range, a density. Visually
92	    distinct from tabs on purpose: tabs change what you are looking at, a
93	    segment changes how. */
94	export function SegmentedControl<T extends string>({
95	  options, value, onChange, size = "md", ariaLabel,
96	}: {
97	  options: { value: T; label: string }[]; value: T; onChange: (v: T) => void;
98	  size?: "sm" | "md"; ariaLabel: string;
99	}) {
100	  return (
101	    <div
102	      role="group"
103	      aria-label={ariaLabel}
104	      className="inline-flex rounded-md border border-hairline bg-plate p-0.5"
105	    >
106	      {options.map((o) => {
107	        const on = o.value === value;
108	        return (
109	          <button
110	            key={o.value}
