"use client";

/* ============================================================================
   TABS, SEGMENTED CONTROLS, STEPPERS, PROGRESS, WIZARD
   One tab mechanism for the product. The old portal had eight tab-bar styles
   plus eight one-off segmented rows, and its two most-used implementations
   rewrote the URL without adding history, so Back left the page.
   ========================================================================= */

import { useId, useRef, type ReactNode, type KeyboardEvent } from "react";
import { Icon, type IconName } from "./Icon";

/* ---------------------------------------------------------------- TABS */
export interface TabItem { id: string; label: string; icon?: IconName; badge?: string | number; disabled?: boolean }

/** Arrow keys move, Home and End jump, Enter and Space are implicit on a
    button. Roving tabindex, so the tab list is one stop in the page order. */
export function Tabs({
  items, active, onChange, ariaLabel = "Sections",
}: { items: TabItem[]; active: string; onChange: (id: string) => void; ariaLabel?: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const base = useId();

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const enabled = items.filter((i) => !i.disabled);
    const idx = enabled.findIndex((i) => i.id === active);
    let next = -1;
    if (e.key === "ArrowRight") next = (idx + 1) % enabled.length;
    else if (e.key === "ArrowLeft") next = (idx - 1 + enabled.length) % enabled.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = enabled.length - 1;
    if (next >= 0) {
      e.preventDefault();
      onChange(enabled[next].id);
      const el = ref.current?.querySelector<HTMLButtonElement>(`#${CSS.escape(`${base}-${enabled[next].id}`)}`);
      el?.focus();
    }
  };

  return (
    <div
      ref={ref}
      role="tablist"
      aria-label={ariaLabel}
      onKeyDown={onKeyDown}
      className="flex gap-0.5 overflow-x-auto border-b border-hairline"
    >
      {items.map((t) => {
        const on = t.id === active;
        return (
          <button
            key={t.id}
            id={`${base}-${t.id}`}
            role="tab"
            aria-selected={on}
            aria-controls={`${base}-panel-${t.id}`}
            tabIndex={on ? 0 : -1}
            disabled={t.disabled}
            onClick={() => onChange(t.id)}
            className={`relative -mb-px inline-flex shrink-0 items-center gap-2 whitespace-nowrap border-b-2 px-3.5 py-2.5 font-display text-body-sm font-semibold
              transition-colors duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
              disabled:cursor-not-allowed disabled:opacity-40
              ${on
                ? "border-signal-edge text-ink"
                : "border-transparent text-ink-muted hover:border-hairline-strong hover:text-ink-secondary"}`}
          >
            {t.icon && <Icon name={t.icon} size="md" />}
            {t.label}
            {t.badge !== undefined && (
              <span className="rounded-sm bg-interactive px-1.5 py-0.5 font-mono text-[0.6875rem] text-ink-secondary">
                {t.badge}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}

export function TabPanel({ id, active, children }: { id: string; active: string; children: ReactNode }) {
  if (id !== active) return null;
  return (
    <div role="tabpanel" className="animate-nx-fade pt-5">
      {children}
    </div>
  );
}

/* --------------------------------------------------- SEGMENTED CONTROL */
/** For switching a view of the same data — a time range, a density. Visually
    distinct from tabs on purpose: tabs change what you are looking at, a
    segment changes how. */
export function SegmentedControl<T extends string>({
  options, value, onChange, size = "md", ariaLabel,
}: {
  options: { value: T; label: string }[]; value: T; onChange: (v: T) => void;
  size?: "sm" | "md"; ariaLabel: string;
}) {
  return (
    <div
      role="group"
      aria-label={ariaLabel}
      className="inline-flex rounded-md border border-hairline bg-plate p-0.5"
    >
      {options.map((o) => {
        const on = o.value === value;
        return (
          <button
            key={o.value}
            type="button"
            aria-pressed={on}
            onClick={() => onChange(o.value)}
            className={`rounded-sm font-display font-semibold transition-colors duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
              ${size === "sm" ? "px-2 py-1 text-[0.75rem]" : "px-3 py-1.5 text-[0.8125rem]"}
              ${on ? "bg-interactive text-ink" : "text-ink-muted hover:text-ink-secondary"}`}
          >
            {o.label}
          </button>
        );
      })}
    </div>
  );
}

/* ------------------------------------------------------------- STEPPER */
export interface Step { id: string; label: string }

export function Stepper({ steps, current }: { steps: Step[]; current: number }) {
  return (
    <ol className="flex flex-wrap items-center gap-x-2 gap-y-2">
      {steps.map((s, i) => {
        const done = i < current;
        const now = i === current;
        return (
          <li key={s.id} className="flex items-center gap-2">
            <span
              className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full border font-mono text-[0.6875rem] font-semibold
                ${done ? "border-success-text/50 bg-success/30 text-success-text"
                  : now ? "border-signal-edge bg-signal/25 text-signal-text"
                  : "border-hairline-strong text-ink-muted"}`}
              aria-hidden="true"
            >
              {done ? <Icon name="check" size="sm" /> : i + 1}
            </span>
            <span className={`font-display text-body-sm font-semibold ${now ? "text-ink" : done ? "text-ink-secondary" : "text-ink-muted"}`}>
              {s.label}
            </span>
            {i < steps.length - 1 && (
              <span className="mx-1 h-px w-6 bg-hairline-strong sm:w-10" aria-hidden="true" />
            )}
          </li>
        );
      })}
    </ol>
  );
}

/* ------------------------------------------------------------ PROGRESS */
export function Progress({
  value, max = 100, label, tone = "signal", showValue = true,
}: { value: number; max?: number; label?: string; tone?: "signal" | "success" | "warning" | "danger"; showValue?: boolean }) {
  const pct = Math.max(0, Math.min(100, (value / max) * 100));
  const bar = {
    signal: "bg-signal", success: "bg-success-text", warning: "bg-warning-text", danger: "bg-danger-text",
  }[tone];
  return (
    <div>
      {(label || showValue) && (
        <div className="mb-1.5 flex items-baseline justify-between gap-3">
          {label && <span className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">{label}</span>}
          {showValue && <span className="font-mono text-caption tabular-nums text-ink-secondary">{Math.round(pct)}%</span>}
        </div>
      )}
      <div
        className="h-1.5 w-full overflow-hidden rounded-pill bg-plate"
        role="progressbar"
        aria-valuenow={Math.round(pct)}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-label={label}
      >
        <div className={`h-full rounded-pill ${bar} transition-[width] duration-[var(--nx-dur-3)] ease-[var(--nx-ease)]`} style={{ width: `${pct}%` }} />
      </div>
    </div>
  );
}

/* -------------------------------------------------------------- WIZARD */
/** The shell a purchase flow lives in. The price summary is a sibling of the
    step content, not a child, so on mobile it pins to the bottom and the
    price can never scroll out of view. */
export function Wizard({
  steps, current, onBack, children, summary, primary,
}: {
  steps: Step[]; current: number; onBack?: () => void;
  children: ReactNode; summary?: ReactNode; primary?: ReactNode;
}) {
  return (
    <div className="nx-container-surface overflow-hidden">
      <div className="border-b border-hairline px-5 py-4">
        <Stepper steps={steps} current={current} />
      </div>

      <div className="px-5 py-6 lg:px-6">{children}</div>

      <div className="sticky bottom-0 flex flex-wrap items-center justify-between gap-3 border-t border-hairline bg-surface/95 px-5 py-3.5 backdrop-blur">
        <div className="min-w-0">{summary}</div>
        <div className="flex items-center gap-2">
          {onBack && current > 0 && (
            <button
              type="button"
              onClick={onBack}
              className="inline-flex items-center gap-1.5 rounded-md px-3 py-2 font-display text-body-sm font-semibold text-ink-muted transition-colors duration-[var(--nx-dur-1)] hover:text-ink"
            >
              <Icon name="chevronLeft" size="md" /> Back
            </button>
          )}
          {primary}
        </div>
      </div>
    </div>
  );
}

