1	"use client";
2	
3	/* ============================================================================
4	   MODALS, DRAWERS, CONFIRMATIONS, DROPDOWNS, TOOLTIPS, TOASTS
5	   One implementation each, all with focus management. The old portal had 24
6	   independent overlays with zero focus traps, 60 browser confirmations and
7	   10 browser alerts, and no toast system at all.
8	   ========================================================================= */
9	
10	import {
11	  createContext, useContext, useCallback, useEffect, useId, useRef, useState,
12	  type ReactNode,
13	} from "react";
14	import { Icon, type IconName } from "./Icon";
15	import { Button, IconButton } from "./controls";
16	import type { Tone } from "./primitives";
17	
18	/* ------------------------------------------------------- focus plumbing */
19	function useFocusTrap(open: boolean, onClose: () => void) {
20	  const ref = useRef<HTMLDivElement>(null);
21	  const restoreTo = useRef<HTMLElement | null>(null);
22	
23	  useEffect(() => {
24	    if (!open) return;
25	    restoreTo.current = document.activeElement as HTMLElement;
26	
27	    const node = ref.current;
28	    const focusables = () =>
29	      Array.from(
30	        node?.querySelectorAll<HTMLElement>(
31	          'a[href],button:not([disabled]),textarea,input,select,[tabindex]:not([tabindex="-1"])'
32	        ) ?? []
33	      ).filter((el) => el.offsetParent !== null);
34	
35	    focusables()[0]?.focus() ?? node?.focus();
36	
37	    const onKey = (e: KeyboardEvent) => {
38	      if (e.key === "Escape") { e.stopPropagation(); onClose(); return; }
39	      if (e.key !== "Tab") return;
40	      const f = focusables();
41	      if (f.length === 0) return;
42	      const first = f[0], last = f[f.length - 1];
43	      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
44	      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
45	    };
46	
47	    document.addEventListener("keydown", onKey, true);
48	    const prevOverflow = document.body.style.overflow;
49	    document.body.style.overflow = "hidden";
50	    return () => {
51	      document.removeEventListener("keydown", onKey, true);
52	      document.body.style.overflow = prevOverflow;
53	      restoreTo.current?.focus();
54	    };
55	  }, [open, onClose]);
56	
57	  return ref;
58	}
59	
60	/* --------------------------------------------------------------- MODAL */
61	export function Modal({
62	  open, onClose, title, description, children, footer, size = "md",
63	}: {
64	  open: boolean; onClose: () => void; title: string; description?: string;
65	  children?: ReactNode; footer?: ReactNode; size?: "sm" | "md" | "lg";
66	}) {
67	  const ref = useFocusTrap(open, onClose);
68	  const titleId = useId();
69	  const descId = useId();
70	  if (!open) return null;
71	
72	  const width = { sm: "max-w-sm", md: "max-w-lg", lg: "max-w-2xl" }[size];
73	
74	  return (
75	    /* A phone gets a bottom sheet: it arrives from the thumb, not the middle
76	       of the screen, and it is reachable one-handed. Above sm it is a
77	       centred dialog as usual. */
78	    <div className="fixed inset-0 z-[var(--nx-z-overlay)] flex items-end justify-center sm:items-center sm:p-4">
79	      <div className="absolute inset-0 bg-scrim/80 animate-nx-fade" onClick={onClose} aria-hidden="true" />
80	      <div
81	        ref={ref}
82	        role="dialog"
83	        aria-modal="true"
84	        aria-labelledby={titleId}
85	        aria-describedby={description ? descId : undefined}
86	        tabIndex={-1}
87	        className={`animate-nx-rise relative max-h-[90dvh] w-full overflow-y-auto rounded-t-lg border border-hairline-strong bg-surface shadow-overlay sm:max-h-none sm:overflow-visible sm:rounded-lg ${width}`}
88	        style={{ paddingBottom: "env(safe-area-inset-bottom)" }}
89	      >
90	        {/* grab handle, phone only */}
91	        <div className="flex justify-center pt-2 sm:hidden" aria-hidden="true">
92	          <span className="h-1 w-9 rounded-pill bg-hairline-strong" />
93	        </div>
94	        <div className="flex items-start justify-between gap-4 border-b border-hairline px-5 py-4">
95	          <div className="min-w-0">
96	            <h2 id={titleId} className="text-h3 text-ink">{title}</h2>
97	            {description && <p id={descId} className="mt-1 text-body-sm text-ink-secondary">{description}</p>}
98	          </div>
99	          <IconButton name="close" label="Close" size="sm" onClick={onClose} />
100	        </div>
101	        {children && <div className="px-5 py-5">{children}</div>}
102	        {footer && <div className="flex flex-wrap justify-end gap-2 border-t border-hairline px-5 py-4">{footer}</div>}
103	      </div>
104	    </div>
105	  );
106	}
107	
108	/* -------------------------------------------------------------- DRAWER */
109	export function Drawer({
110	  open, onClose, title, side = "right", children, footer,
111	}: {
112	  open: boolean; onClose: () => void; title: string;
113	  side?: "right" | "left"; children?: ReactNode; footer?: ReactNode;
114	}) {
115	  const ref = useFocusTrap(open, onClose);
116	  const titleId = useId();
117	  if (!open) return null;
118	  return (
119	    <div className="fixed inset-0 z-[var(--nx-z-overlay)]">
120	      <div className="absolute inset-0 bg-scrim/80 animate-nx-fade" onClick={onClose} aria-hidden="true" />
121	      <div
122	        ref={ref}
123	        role="dialog"
124	        aria-modal="true"
125	        aria-labelledby={titleId}
126	        tabIndex={-1}
127	        className={`absolute inset-y-0 flex w-full max-w-md flex-col border-hairline-strong bg-surface shadow-overlay
128	          ${side === "right"
129	            ? "right-0 border-l animate-nx-slide-right"
130	            : "left-0 border-r animate-nx-slide-left"}`}
131	      >
132	        <div className="flex items-center justify-between gap-4 border-b border-hairline px-5 py-4">
133	          <h2 id={titleId} className="text-h3 text-ink">{title}</h2>
134	          <IconButton name="close" label="Close" size="sm" onClick={onClose} />
135	        </div>
136	        <div className="min-h-0 flex-1 overflow-y-auto px-5 py-5">{children}</div>
137	        {footer && <div className="flex justify-end gap-2 border-t border-hairline px-5 py-4">{footer}</div>}
138	      </div>
139	    </div>
140	  );
141	}
142	
143	/* ---------------------------------------------------- CONFIRM DIALOG */
144	/** Every destructive confirmation states what happens, what is lost and
145	    whether it can be undone. Irreversible actions require the resource name
146	    to be typed — clicking OK is not consent for a destroy. */
147	export function ConfirmDialog({
148	  open, onClose, onConfirm, title, whatHappens, whatIsLost, reversible,
149	  confirmLabel = "Confirm", typeToConfirm, tone = "danger",
150	}: {
151	  open: boolean; onClose: () => void; onConfirm: () => void;
152	  title: string; whatHappens: string; whatIsLost?: string; reversible: boolean;
153	  confirmLabel?: string; typeToConfirm?: string; tone?: "danger" | "signal";
154	}) {
155	  const [typed, setTyped] = useState("");
156	  useEffect(() => { if (!open) setTyped(""); }, [open]);
157	  const armed = !typeToConfirm || typed === typeToConfirm;
158	
159	  return (
160	    <Modal
161	      open={open}
162	      onClose={onClose}
163	      title={title}
164	      size="sm"
165	      footer={
166	        <>
167	          <Button variant="ghost" onClick={onClose}>Cancel</Button>
168	          <Button
169	            variant={tone === "danger" ? "danger" : "primary"}
170	            disabled={!armed}
171	            onClick={() => { onConfirm(); onClose(); }}
172	          >
173	            {confirmLabel}
174	          </Button>
175	        </>
176	      }
177	    >
178	      <div className="flex flex-col gap-4">
179	        <dl className="flex flex-col gap-3">
180	          <div>
181	            <dt className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">What happens</dt>
182	            <dd className="mt-1 text-body-sm text-ink-secondary">{whatHappens}</dd>
183	          </div>
184	          {whatIsLost && (
185	            <div>
186	              <dt className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">What is lost</dt>
187	              <dd className="mt-1 text-body-sm text-danger-text">{whatIsLost}</dd>
188	            </div>
189	          )}
190	          <div>
191	            <dt className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">Reversible</dt>
192	            <dd className={`mt-1 text-body-sm ${reversible ? "text-ink-secondary" : "text-danger-text"}`}>
193	              {reversible ? "Yes — this can be undone." : "No. This cannot be undone."}
194	            </dd>
195	          </div>
196	        </dl>
197	        {typeToConfirm && (
198	          <label className="flex flex-col gap-1.5">
199	            <span className="text-body-sm text-ink-secondary">
200	              Type <code className="font-mono text-code text-ink">{typeToConfirm}</code> to confirm.
201	            </span>
202	            <input
203	              value={typed}
204	              onChange={(e) => setTyped(e.target.value)}
205	              autoComplete="off"
206	              className="h-10 w-full rounded-md border border-hairline bg-plate px-3 font-mono text-code text-ink transition-colors duration-[var(--nx-dur-1)] hover:border-hairline-strong"
207	            />
208	          </label>
209	        )}
210	      </div>
211	    </Modal>
212	  );
213	}
214	
215	/* ------------------------------------------------------------ DROPDOWN */
216	export interface MenuItem {
217	  label: string; icon?: IconName; onSelect?: () => void;
218	  tone?: "default" | "danger"; separatorBefore?: boolean;
219	}
220	export function Dropdown({ trigger, items, align = "right" }: {
221	  trigger: ReactNode; items: MenuItem[]; align?: "left" | "right";
222	}) {
223	  const [open, setOpen] = useState(false);
224	  const wrap = useRef<HTMLDivElement>(null);
225	
226	  useEffect(() => {
227	    if (!open) return;
228	    const onDoc = (e: MouseEvent) => {
