"use client";

/* ============================================================================
   MODALS, DRAWERS, CONFIRMATIONS, DROPDOWNS, TOOLTIPS, TOASTS
   One implementation each, all with focus management. The old portal had 24
   independent overlays with zero focus traps, 60 browser confirmations and
   10 browser alerts, and no toast system at all.
   ========================================================================= */

import {
  createContext, useContext, useCallback, useEffect, useId, useRef, useState,
  type ReactNode,
} from "react";
import { Icon, type IconName } from "./Icon";
import { Button, IconButton } from "./controls";
import type { Tone } from "./primitives";

/* ------------------------------------------------------- focus plumbing */
function useFocusTrap(open: boolean, onClose: () => void) {
  const ref = useRef<HTMLDivElement>(null);
  const restoreTo = useRef<HTMLElement | null>(null);

  useEffect(() => {
    if (!open) return;
    restoreTo.current = document.activeElement as HTMLElement;

    const node = ref.current;
    const focusables = () =>
      Array.from(
        node?.querySelectorAll<HTMLElement>(
          'a[href],button:not([disabled]),textarea,input,select,[tabindex]:not([tabindex="-1"])'
        ) ?? []
      ).filter((el) => el.offsetParent !== null);

    focusables()[0]?.focus() ?? node?.focus();

    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") { e.stopPropagation(); onClose(); return; }
      if (e.key !== "Tab") return;
      const f = focusables();
      if (f.length === 0) return;
      const first = f[0], last = f[f.length - 1];
      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    };

    document.addEventListener("keydown", onKey, true);
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", onKey, true);
      document.body.style.overflow = prevOverflow;
      restoreTo.current?.focus();
    };
  }, [open, onClose]);

  return ref;
}

/* --------------------------------------------------------------- MODAL */
export function Modal({
  open, onClose, title, description, children, footer, size = "md",
}: {
  open: boolean; onClose: () => void; title: string; description?: string;
  children?: ReactNode; footer?: ReactNode; size?: "sm" | "md" | "lg";
}) {
  const ref = useFocusTrap(open, onClose);
  const titleId = useId();
  const descId = useId();
  if (!open) return null;

  const width = { sm: "max-w-sm", md: "max-w-lg", lg: "max-w-2xl" }[size];

  return (
    /* A phone gets a bottom sheet: it arrives from the thumb, not the middle
       of the screen, and it is reachable one-handed. Above sm it is a
       centred dialog as usual. */
    <div className="fixed inset-0 z-[var(--nx-z-overlay)] flex items-end justify-center sm:items-center sm:p-4">
      <div className="absolute inset-0 bg-scrim/80 animate-nx-fade" onClick={onClose} aria-hidden="true" />
      <div
        ref={ref}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        aria-describedby={description ? descId : undefined}
        tabIndex={-1}
        className={`animate-nx-rise relative max-h-[90dvh] w-full overflow-y-auto rounded-t-lg border border-hairline-strong bg-surface shadow-overlay sm:max-h-none sm:overflow-visible sm:rounded-lg ${width}`}
        style={{ paddingBottom: "env(safe-area-inset-bottom)" }}
      >
        {/* grab handle, phone only */}
        <div className="flex justify-center pt-2 sm:hidden" aria-hidden="true">
          <span className="h-1 w-9 rounded-pill bg-hairline-strong" />
        </div>
        <div className="flex items-start justify-between gap-4 border-b border-hairline px-5 py-4">
          <div className="min-w-0">
            <h2 id={titleId} className="text-h3 text-ink">{title}</h2>
            {description && <p id={descId} className="mt-1 text-body-sm text-ink-secondary">{description}</p>}
          </div>
          <IconButton name="close" label="Close" size="sm" onClick={onClose} />
        </div>
        {children && <div className="px-5 py-5">{children}</div>}
        {footer && <div className="flex flex-wrap justify-end gap-2 border-t border-hairline px-5 py-4">{footer}</div>}
      </div>
    </div>
  );
}

/* -------------------------------------------------------------- DRAWER */
export function Drawer({
  open, onClose, title, side = "right", children, footer,
}: {
  open: boolean; onClose: () => void; title: string;
  side?: "right" | "left"; children?: ReactNode; footer?: ReactNode;
}) {
  const ref = useFocusTrap(open, onClose);
  const titleId = useId();
  if (!open) return null;
  return (
    <div className="fixed inset-0 z-[var(--nx-z-overlay)]">
      <div className="absolute inset-0 bg-scrim/80 animate-nx-fade" onClick={onClose} aria-hidden="true" />
      <div
        ref={ref}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        tabIndex={-1}
        className={`absolute inset-y-0 flex w-full max-w-md flex-col border-hairline-strong bg-surface shadow-overlay
          ${side === "right"
            ? "right-0 border-l animate-nx-slide-right"
            : "left-0 border-r animate-nx-slide-left"}`}
      >
        <div className="flex items-center justify-between gap-4 border-b border-hairline px-5 py-4">
          <h2 id={titleId} className="text-h3 text-ink">{title}</h2>
          <IconButton name="close" label="Close" size="sm" onClick={onClose} />
        </div>
        <div className="min-h-0 flex-1 overflow-y-auto px-5 py-5">{children}</div>
        {footer && <div className="flex justify-end gap-2 border-t border-hairline px-5 py-4">{footer}</div>}
      </div>
    </div>
  );
}

/* ---------------------------------------------------- CONFIRM DIALOG */
/** Every destructive confirmation states what happens, what is lost and
    whether it can be undone. Irreversible actions require the resource name
    to be typed — clicking OK is not consent for a destroy. */
export function ConfirmDialog({
  open, onClose, onConfirm, title, whatHappens, whatIsLost, reversible,
  confirmLabel = "Confirm", typeToConfirm, tone = "danger",
}: {
  open: boolean; onClose: () => void; onConfirm: () => void;
  title: string; whatHappens: string; whatIsLost?: string; reversible: boolean;
  confirmLabel?: string; typeToConfirm?: string; tone?: "danger" | "signal";
}) {
  const [typed, setTyped] = useState("");
  useEffect(() => { if (!open) setTyped(""); }, [open]);
  const armed = !typeToConfirm || typed === typeToConfirm;

  return (
    <Modal
      open={open}
      onClose={onClose}
      title={title}
      size="sm"
      footer={
        <>
          <Button variant="ghost" onClick={onClose}>Cancel</Button>
          <Button
            variant={tone === "danger" ? "danger" : "primary"}
            disabled={!armed}
            onClick={() => { onConfirm(); onClose(); }}
          >
            {confirmLabel}
          </Button>
        </>
      }
    >
      <div className="flex flex-col gap-4">
        <dl className="flex flex-col gap-3">
          <div>
            <dt className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">What happens</dt>
            <dd className="mt-1 text-body-sm text-ink-secondary">{whatHappens}</dd>
          </div>
          {whatIsLost && (
            <div>
              <dt className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">What is lost</dt>
              <dd className="mt-1 text-body-sm text-danger-text">{whatIsLost}</dd>
            </div>
          )}
          <div>
            <dt className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">Reversible</dt>
            <dd className={`mt-1 text-body-sm ${reversible ? "text-ink-secondary" : "text-danger-text"}`}>
              {reversible ? "Yes — this can be undone." : "No. This cannot be undone."}
            </dd>
          </div>
        </dl>
        {typeToConfirm && (
          <label className="flex flex-col gap-1.5">
            <span className="text-body-sm text-ink-secondary">
              Type <code className="font-mono text-code text-ink">{typeToConfirm}</code> to confirm.
            </span>
            <input
              value={typed}
              onChange={(e) => setTyped(e.target.value)}
              autoComplete="off"
              className="h-10 w-full rounded-md border border-hairline bg-plate px-3 font-mono text-code text-ink transition-colors duration-[var(--nx-dur-1)] hover:border-hairline-strong"
            />
          </label>
        )}
      </div>
    </Modal>
  );
}

/* ------------------------------------------------------------ DROPDOWN */
export interface MenuItem {
  label: string; icon?: IconName; onSelect?: () => void;
  tone?: "default" | "danger"; separatorBefore?: boolean;
}
export function Dropdown({ trigger, items, align = "right" }: {
  trigger: ReactNode; items: MenuItem[]; align?: "left" | "right";
}) {
  const [open, setOpen] = useState(false);
  const wrap = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => {
      if (wrap.current && !wrap.current.contains(e.target as Node)) setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") setOpen(false); };
    document.addEventListener("mousedown", onDoc);
    document.addEventListener("keydown", onKey);
    return () => { document.removeEventListener("mousedown", onDoc); document.removeEventListener("keydown", onKey); };
  }, [open]);

  return (
    <div ref={wrap} className="relative">
      <span onClick={() => setOpen((v) => !v)}>{trigger}</span>
      {open && (
        <div
          role="menu"
          className={`absolute top-[calc(100%+4px)] z-[var(--nx-z-overlay)] min-w-52 animate-nx-rise rounded-md border border-hairline-strong bg-surface py-1 shadow-overlay ${
            align === "right" ? "right-0" : "left-0"
          }`}
        >
          {items.map((it, i) => (
            <div key={it.label}>
              {it.separatorBefore && i > 0 && <div className="my-1 h-px bg-hairline" />}
              <button
                role="menuitem"
                type="button"
                onClick={() => { it.onSelect?.(); setOpen(false); }}
                className={`flex w-full items-center gap-2.5 px-3 py-2 text-left text-body-sm transition-colors duration-[var(--nx-dur-1)] hover:bg-interactive ${
                  it.tone === "danger" ? "text-danger-text" : "text-ink-secondary hover:text-ink"
                }`}
              >
                {it.icon && <Icon name={it.icon} size="md" />}
                {it.label}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------- TOOLTIP */
export function Tooltip({ label, children }: { label: string; children: ReactNode }) {
  const [open, setOpen] = useState(false);
  const id = useId();
  return (
    <span className="relative inline-flex">
      <span
        aria-describedby={open ? id : undefined}
        onMouseEnter={() => setOpen(true)}
        onMouseLeave={() => setOpen(false)}
        onFocus={() => setOpen(true)}
        onBlur={() => setOpen(false)}
        className="inline-flex"
      >
        {children}
      </span>
      {open && (
        <span
          id={id}
          role="tooltip"
          className="pointer-events-none absolute bottom-[calc(100%+6px)] left-1/2 z-[var(--nx-z-tooltip)] w-max max-w-56 -translate-x-1/2 animate-nx-fade rounded-md border border-hairline-strong bg-plate px-2.5 py-1.5 text-caption text-ink shadow-overlay"
        >
          {label}
        </span>
      )}
    </span>
  );
}

/* --------------------------------------------------------------- ALERT */
const ALERT_STYLE: Record<Tone, { border: string; icon: IconName; text: string }> = {
  neutral: { border: "border-hairline-strong",     icon: "info",    text: "text-ink-secondary" },
  signal:  { border: "border-signal-edge/45",      icon: "info",    text: "text-signal-text" },
  success: { border: "border-success-text/40",     icon: "check",   text: "text-success-text" },
  warning: { border: "border-warning-text/40",     icon: "warning", text: "text-warning-text" },
  danger:  { border: "border-danger-text/40",      icon: "alert",   text: "text-danger-text" },
  ai:      { border: "border-ai-text/40",          icon: "ai",      text: "text-ai-text" },
};

export function Alert({
  tone = "neutral", title, children, action,
}: { tone?: Tone; title: string; children?: ReactNode; action?: ReactNode }) {
  const s = ALERT_STYLE[tone];
  return (
    <div
      role={tone === "danger" ? "alert" : "status"}
      className={`flex gap-3 rounded-md border-l-2 border-y border-r border-y-hairline border-r-hairline bg-surface px-4 py-3 ${s.border}`}
    >
      <Icon name={s.icon} size="md" className={`mt-0.5 ${s.text}`} />
      <div className="min-w-0 flex-1">
        <p className={`font-display text-body-sm font-semibold ${s.text}`}>{title}</p>
        {children && <div className="mt-1 text-body-sm text-ink-secondary">{children}</div>}
      </div>
      {action && <div className="shrink-0 self-center">{action}</div>}
    </div>
  );
}

/* --------------------------------------------------------------- TOAST */
export interface ToastMsg { id: number; tone: Tone; title: string; body?: string }
const ToastCtx = createContext<{ push: (t: Omit<ToastMsg, "id">) => void }>({ push: () => {} });
export const useToast = () => useContext(ToastCtx);

export function ToastProvider({ children }: { children: ReactNode }) {
  const [items, setItems] = useState<ToastMsg[]>([]);
  const push = useCallback((t: Omit<ToastMsg, "id">) => {
    const id = Date.now() + Math.random();
    setItems((xs) => [...xs, { ...t, id }]);
    window.setTimeout(() => setItems((xs) => xs.filter((x) => x.id !== id)), 4500);
  }, []);
  return (
    <ToastCtx.Provider value={{ push }}>
      {children}
      <div
        className="pointer-events-none fixed bottom-4 right-4 z-[var(--nx-z-toast)] flex w-full max-w-sm flex-col gap-2"
        aria-live="polite"
        aria-atomic="false"
      >
        {items.map((t) => {
          const s = ALERT_STYLE[t.tone];
          return (
            <div
              key={t.id}
              className={`pointer-events-auto flex animate-nx-rise gap-3 rounded-md border border-hairline-strong border-l-2 bg-surface px-4 py-3 shadow-overlay ${s.border}`}
            >
              <Icon name={s.icon} size="md" className={`mt-0.5 ${s.text}`} />
              <div className="min-w-0 flex-1">
                <p className={`font-display text-body-sm font-semibold ${s.text}`}>{t.title}</p>
                {t.body && <p className="mt-0.5 text-caption text-ink-secondary">{t.body}</p>}
              </div>
              <button
                type="button"
                aria-label="Dismiss"
                onClick={() => setItems((xs) => xs.filter((x) => x.id !== t.id))}
                className="shrink-0 self-start rounded-sm p-0.5 text-ink-muted transition-colors duration-[var(--nx-dur-1)] hover:text-ink"
              >
                <Icon name="close" size="sm" />
              </button>
            </div>
          );
        })}
      </div>
    </ToastCtx.Provider>
  );
}

