1	"use client";
2	
3	/* ============================================================================
4	   TABLES, METRICS, METERS, CHARTS
5	   Chart colour comes from tokens, never from a hardcoded hex — the old
6	   portal's charts were unthemeable because the stroke was baked in.
7	   ========================================================================= */
8	
9	import type { ReactNode } from "react";
10	import { Icon } from "./Icon";
11	
12	/* --------------------------------------------------------------- TABLE */
13	export interface Column<Row> {
14	  key: string;
15	  header: string;
16	  align?: "left" | "right";
17	  /** Marks the column as technical, so its cells get the mono treatment. */
18	  mono?: boolean;
19	  width?: string;
20	  /** On a phone this column becomes the card's title line. */
21	  primary?: boolean;
22	  /** Hidden on a phone card — noise the small layout does not need. */
23	  hideOnCard?: boolean;
24	  render: (row: Row) => ReactNode;
25	}
26	
27	/** One table skin. Wide content scrolls inside its own container so the page
28	    body never scrolls sideways; below `md` the caller should render cards
29	    instead — see ResourceRow. */
30	export function Table<Row extends { id: string }>({
31	  columns, rows, caption, empty,
32	}: { columns: Column<Row>[]; rows: Row[]; caption?: string; empty?: ReactNode }) {
33	  if (rows.length === 0 && empty) return <>{empty}</>;
34	
35	  const primary = columns.find((c) => c.primary) ?? columns[0];
36	  const rest = columns.filter((c) => c !== primary && !c.hideOnCard);
37	
38	  return (
39	    <>
40	    {/* Below md a primary table becomes stacked object cards. It never
41	        scrolls sideways: a phone user should not have to drag a table. */}
42	    <div className="flex flex-col gap-2 md:hidden">
43	      {rows.map((r) => (
44	        <div key={r.id} className="nx-object px-4 py-3.5">
