135	export function ResourceMeter({
136	  label, used, total, unit, format,
137	}: { label: string; used: number; total: number; unit?: string; format?: (n: number) => string }) {
138	  const pct = total > 0 ? Math.min(100, (used / total) * 100) : 0;
139	  const tone = pct >= 90 ? "danger" : pct >= 75 ? "warning" : "signal";
140	  const bar = { signal: "bg-signal", warning: "bg-warning-text", danger: "bg-danger-text" }[tone];
