161	type Ramp = "data" | "data-2" | "data-3" | "data-4" | "data-5";
162	const RAMP: Record<Ramp, string> = {
163	  "data":   "var(--color-data)",
164	  "data-2": "var(--color-data-2)",
165	  "data-3": "var(--color-data-3)",
166	  "data-4": "var(--color-data-4)",
