170	export function Sparkline({
171	  points, tone = "data", width = 120, height = 32,
172	}: { points: number[]; tone?: Ramp; width?: number; height?: number }) {
173	  if (points.length < 2) return null;
174	  const min = Math.min(...points), max = Math.max(...points);
175	  const span = max - min || 1;
176	  const d = points
177	    .map((p, i) => {
178	      const x = (i / (points.length - 1)) * width;
179	      const y = height - ((p - min) / span) * (height - 4) - 2;
180	      return `${i === 0 ? "M" : "L"}${x.toFixed(1)},${y.toFixed(1)}`;
181	    })
182	    .join(" ");
183	  const lastX = width;
184	  const lastY = height - ((points[points.length - 1] - min) / span) * (height - 4) - 2;
185	  return (
186	    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} aria-hidden="true" className="overflow-visible">
187	      <path d={d} fill="none" stroke={RAMP[tone]} strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" />
188	      <circle cx={lastX} cy={lastY} r={2.5} fill={RAMP[tone]} />
