196	  points, labels, tone = "data", height = 160, unit = "", ariaLabel,
197	}: {
198	  points: number[]; labels?: string[]; tone?: Ramp;
199	  height?: number; unit?: string; ariaLabel: string;
200	}) {
201	  const W = 560, H = height, padL = 44, padB = 22, padT = 10, padR = 8;
202	  const iw = W - padL - padR, ih = H - padT - padB;
203	  const max = Math.max(...points, 1);
204	  const niceMax = Math.ceil(max / 5) * 5 || 5;
205	  const ticks = [0, niceMax / 2, niceMax];
206	
207	  const x = (i: number) => padL + (i / (points.length - 1)) * iw;
208	  const y = (v: number) => padT + ih - (v / niceMax) * ih;
209	
210	  const line = points.map((p, i) => `${i === 0 ? "M" : "L"}${x(i).toFixed(1)},${y(p).toFixed(1)}`).join(" ");
211	  const area = `${line} L${x(points.length - 1).toFixed(1)},${(padT + ih).toFixed(1)} L${padL},${(padT + ih).toFixed(1)} Z`;
212	  const gid = `nx-grad-${tone}`;
213	
214	  return (
215	    <svg viewBox={`0 0 ${W} ${H}`} className="w-full" role="img" aria-label={ariaLabel}>
216	      <defs>
217	        <linearGradient id={gid} x1="0" y1="0" x2="0" y2="1">
218	          <stop offset="0%" stopColor={RAMP[tone]} stopOpacity="0.28" />
219	          <stop offset="100%" stopColor={RAMP[tone]} stopOpacity="0.02" />
220	        </linearGradient>
221	      </defs>
222	
223	      {ticks.map((t) => (
