225	          <line x1={padL} x2={W - padR} y1={y(t)} y2={y(t)} stroke="var(--color-hairline)" strokeWidth={1} />
226	          <text
227	            x={padL - 8} y={y(t)} textAnchor="end" dominantBaseline="middle"
228	            fill="var(--color-ink-muted)" fontSize="11" fontFamily="var(--font-mono)"
229	          >
230	            {t}{unit}
231	          </text>
232	        </g>
233	      ))}
234	
235	      <path d={area} fill={`url(#${gid})`} />
236	      <path d={line} fill="none" stroke={RAMP[tone]} strokeWidth={1.75} strokeLinecap="round" strokeLinejoin="round" />
237	      <circle cx={x(points.length - 1)} cy={y(points[points.length - 1])} r={3.5} fill={RAMP[tone]} />
238	
239	      {labels?.map((l, i) => {
240	        const step = Math.ceil(labels.length / 5);
241	        if (i % step !== 0 && i !== labels.length - 1) return null;
242	        return (
243	          <text
244	            key={l + i} x={x(i)} y={H - 6}
245	            textAnchor={i === labels.length - 1 ? "end" : i === 0 ? "start" : "middle"}
246	            fill="var(--color-ink-muted)" fontSize="11" fontFamily="var(--font-mono)"
247	          >
