"use client";

/* ============================================================================
   TABLES, METRICS, METERS, CHARTS
   Chart colour comes from tokens, never from a hardcoded hex — the old
   portal's charts were unthemeable because the stroke was baked in.
   ========================================================================= */

import type { ReactNode } from "react";
import { Icon } from "./Icon";

/* --------------------------------------------------------------- TABLE */
export interface Column<Row> {
  key: string;
  header: string;
  align?: "left" | "right";
  /** Marks the column as technical, so its cells get the mono treatment. */
  mono?: boolean;
  width?: string;
  /** On a phone this column becomes the card's title line. */
  primary?: boolean;
  /** Hidden on a phone card — noise the small layout does not need. */
  hideOnCard?: boolean;
  render: (row: Row) => ReactNode;
}

/** One table skin. Wide content scrolls inside its own container so the page
    body never scrolls sideways; below `md` the caller should render cards
    instead — see ResourceRow. */
export function Table<Row extends { id: string }>({
  columns, rows, caption, empty,
}: { columns: Column<Row>[]; rows: Row[]; caption?: string; empty?: ReactNode }) {
  if (rows.length === 0 && empty) return <>{empty}</>;

  const primary = columns.find((c) => c.primary) ?? columns[0];
  const rest = columns.filter((c) => c !== primary && !c.hideOnCard);

  return (
    <>
    {/* Below md a primary table becomes stacked object cards. It never
        scrolls sideways: a phone user should not have to drag a table. */}
    <div className="flex flex-col gap-2 md:hidden">
      {rows.map((r) => (
        <div key={r.id} className="nx-object px-4 py-3.5">
          <div className="pl-2">{primary.render(r)}</div>
          <dl className="mt-3 grid grid-cols-2 gap-x-4 gap-y-2 border-t border-hairline pl-2 pt-3">
            {rest.map((c) => (
              <div key={c.key} className="min-w-0">
                <dt className="font-display text-[0.6875rem] uppercase tracking-[0.1em] text-ink-muted">
                  {c.header || "\u00a0"}
                </dt>
                <dd className={`mt-0.5 truncate text-caption text-ink-secondary ${c.mono ? "font-mono" : ""}`}>
                  {c.render(r)}
                </dd>
              </div>
            ))}
          </dl>
        </div>
      ))}
    </div>

    <div className="hidden overflow-x-auto rounded-lg border border-hairline md:block">
      <table className="w-full border-collapse text-body-sm">
        {caption && <caption className="sr-only">{caption}</caption>}
        <thead>
          <tr className="border-b border-hairline bg-surface">
            {columns.map((c) => (
              <th
                key={c.key}
                scope="col"
                style={c.width ? { width: c.width } : undefined}
                className={`px-4 py-2.5 font-display text-label font-semibold uppercase tracking-[0.11em] text-ink-muted ${
                  c.align === "right" ? "text-right" : "text-left"
                }`}
              >
                {c.header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((r) => (
            <tr
              key={r.id}
              className="border-b border-hairline last:border-0 transition-colors duration-[var(--nx-dur-1)] hover:bg-surface"
            >
              {columns.map((c) => (
                <td
                  key={c.key}
                  className={`px-4 py-3 align-middle ${c.align === "right" ? "text-right" : "text-left"} ${
                    c.mono ? "font-mono text-code text-ink-secondary" : "text-ink-secondary"
                  }`}
                >
                  {c.render(r)}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
    </>
  );
}

/* --------------------------------------------------------- METRIC TILE */
export function MetricTile({
  label, value, unit, delta, hint, chart,
}: {
  label: string; value: string | number; unit?: string;
  delta?: { value: string; direction: "up" | "down"; good?: boolean };
  hint?: string; chart?: ReactNode;
}) {
  return (
    <div className="flex flex-col gap-2 px-4 py-3.5">
      <span className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">{label}</span>
      <div className="flex items-baseline gap-1.5">
        <span className="font-display text-metric tabular-nums text-ink">{value}</span>
        {unit && <span className="font-mono text-body-sm text-ink-muted">{unit}</span>}
      </div>
      {delta && (
        <span className={`inline-flex items-center gap-1 text-caption ${delta.good === false ? "text-danger-text" : "text-success-text"}`}>
          <Icon name={delta.direction === "up" ? "chevronRight" : "chevronRight"} size="sm"
            className={delta.direction === "up" ? "-rotate-90" : "rotate-90"} />
          {delta.value}
        </span>
      )}
      {chart}
      {hint && <span className="text-caption text-ink-muted">{hint}</span>}
    </div>
  );
}

/* ------------------------------------------------------ RESOURCE METER */
export function ResourceMeter({
  label, used, total, unit, format,
}: { label: string; used: number; total: number; unit?: string; format?: (n: number) => string }) {
  const pct = total > 0 ? Math.min(100, (used / total) * 100) : 0;
  const tone = pct >= 90 ? "danger" : pct >= 75 ? "warning" : "signal";
  const bar = { signal: "bg-signal", warning: "bg-warning-text", danger: "bg-danger-text" }[tone];
  const fmt = format ?? ((n: number) => String(n));
  return (
    <div>
      <div className="mb-1.5 flex items-baseline justify-between gap-3">
        <span className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">{label}</span>
        <span className="font-mono text-caption tabular-nums text-ink-secondary">
          {fmt(used)}<span className="text-ink-muted"> / {fmt(total)}{unit ? ` ${unit}` : ""}</span>
        </span>
      </div>
      <div
        className="h-1.5 w-full overflow-hidden rounded-pill bg-plate"
        role="meter" aria-valuenow={Math.round(pct)} aria-valuemin={0} aria-valuemax={100} aria-label={label}
      >
        <div className={`h-full rounded-pill ${bar} transition-[width] duration-[var(--nx-dur-3)] ease-[var(--nx-ease)]`} style={{ width: `${pct}%` }} />
      </div>
    </div>
  );
}

/* -------------------------------------------------------------- CHARTS */
type Ramp = "data" | "data-2" | "data-3" | "data-4" | "data-5";
const RAMP: Record<Ramp, string> = {
  "data":   "var(--color-data)",
  "data-2": "var(--color-data-2)",
  "data-3": "var(--color-data-3)",
  "data-4": "var(--color-data-4)",
  "data-5": "var(--color-data-5)",
};

export function Sparkline({
  points, tone = "data", width = 120, height = 32,
}: { points: number[]; tone?: Ramp; width?: number; height?: number }) {
  if (points.length < 2) return null;
  const min = Math.min(...points), max = Math.max(...points);
  const span = max - min || 1;
  const d = points
    .map((p, i) => {
      const x = (i / (points.length - 1)) * width;
      const y = height - ((p - min) / span) * (height - 4) - 2;
      return `${i === 0 ? "M" : "L"}${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(" ");
  const lastX = width;
  const lastY = height - ((points[points.length - 1] - min) / span) * (height - 4) - 2;
  return (
    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} aria-hidden="true" className="overflow-visible">
      <path d={d} fill="none" stroke={RAMP[tone]} strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" />
      <circle cx={lastX} cy={lastY} r={2.5} fill={RAMP[tone]} />
    </svg>
  );
}

/** Area chart with a real scale: every gridline is labelled with a value the
    chart actually reaches, and the endpoint is emphasised. */
export function AreaChart({
  points, labels, tone = "data", height = 160, unit = "", ariaLabel,
}: {
  points: number[]; labels?: string[]; tone?: Ramp;
  height?: number; unit?: string; ariaLabel: string;
}) {
  const W = 560, H = height, padL = 44, padB = 22, padT = 10, padR = 8;
  const iw = W - padL - padR, ih = H - padT - padB;
  const max = Math.max(...points, 1);
  const niceMax = Math.ceil(max / 5) * 5 || 5;
  const ticks = [0, niceMax / 2, niceMax];

  const x = (i: number) => padL + (i / (points.length - 1)) * iw;
  const y = (v: number) => padT + ih - (v / niceMax) * ih;

  const line = points.map((p, i) => `${i === 0 ? "M" : "L"}${x(i).toFixed(1)},${y(p).toFixed(1)}`).join(" ");
  const area = `${line} L${x(points.length - 1).toFixed(1)},${(padT + ih).toFixed(1)} L${padL},${(padT + ih).toFixed(1)} Z`;
  const gid = `nx-grad-${tone}`;

  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="w-full" role="img" aria-label={ariaLabel}>
      <defs>
        <linearGradient id={gid} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={RAMP[tone]} stopOpacity="0.28" />
          <stop offset="100%" stopColor={RAMP[tone]} stopOpacity="0.02" />
        </linearGradient>
      </defs>

      {ticks.map((t) => (
        <g key={t}>
          <line x1={padL} x2={W - padR} y1={y(t)} y2={y(t)} stroke="var(--color-hairline)" strokeWidth={1} />
          <text
            x={padL - 8} y={y(t)} textAnchor="end" dominantBaseline="middle"
            fill="var(--color-ink-muted)" fontSize="11" fontFamily="var(--font-mono)"
          >
            {t}{unit}
          </text>
        </g>
      ))}

      <path d={area} fill={`url(#${gid})`} />
      <path d={line} fill="none" stroke={RAMP[tone]} strokeWidth={1.75} strokeLinecap="round" strokeLinejoin="round" />
      <circle cx={x(points.length - 1)} cy={y(points[points.length - 1])} r={3.5} fill={RAMP[tone]} />

      {labels?.map((l, i) => {
        const step = Math.ceil(labels.length / 5);
        if (i % step !== 0 && i !== labels.length - 1) return null;
        return (
          <text
            key={l + i} x={x(i)} y={H - 6}
            textAnchor={i === labels.length - 1 ? "end" : i === 0 ? "start" : "middle"}
            fill="var(--color-ink-muted)" fontSize="11" fontFamily="var(--font-mono)"
          >
            {l}
          </text>
        );
      })}
    </svg>
  );
}

"use client";

/* ============================================================================
   ILLUSTRATIONS
   The asset audit found the product had zero illustrations and one generic
   glyph doing duty for every empty collection. These are the replacement,
   and they are drawn from the same vocabulary as the topology: the notched
   object outline, nodes, paths and the precision grid.

   Each one carries the meaning of its state in its geometry, so it is
   information rather than filler:
     empty    — a notched slot with nothing seated in it
     error    — a path that breaks partway
     success  — paths converging on a live node
     building — nodes assembling into an object
   ========================================================================= */

import { useId } from "react";

type Props = { className?: string; size?: number };

const NOTCH = "M14,1 L119,1 L119,79 L1,79 L1,14 Z";

function Frame({ children, size = 132, className = "" }: Props & { children: React.ReactNode }) {
  return (
    <svg
      viewBox="0 0 120 80"
      width={size}
      height={(size / 120) * 80}
      className={className}
      aria-hidden="true"
      fill="none"
    >
      {children}
    </svg>
  );
}

/** An empty slot: the object outline is there, nothing is seated in it. */
export function EmptySlot(p: Props) {
  const u = useId().replace(/:/g, "");
  return (
    <Frame {...p}>
      <defs>
        <linearGradient id={`${u}-g`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="var(--color-brand-a)" stopOpacity="0.5" />
          <stop offset="100%" stopColor="var(--color-brand-c)" stopOpacity="0.3" />
        </linearGradient>
      </defs>
      <path d={NOTCH} stroke={`url(#${u}-g)`} strokeWidth="1.25" strokeDasharray="5 4" />
      <g stroke="var(--color-hairline-strong)" strokeWidth="1">
        <line x1="22" y1="30" x2="98" y2="30" />
        <line x1="22" y1="44" x2="72" y2="44" />
        <line x1="22" y1="58" x2="56" y2="58" />
      </g>
      <circle cx="60" cy="14" r="2.5" fill="var(--color-brand-c)" fillOpacity="0.55" />
    </Frame>
  );
}

/** A path that breaks: the trace reaches a point and stops. */
export function BrokenPath(p: Props) {
  return (
    <Frame {...p}>
      <path d="M6,58 C30,58 34,24 58,24" stroke="var(--color-danger-text)" strokeWidth="1.5"
        strokeOpacity="0.9" strokeLinecap="round" />
      <path d="M74,24 C96,24 100,52 114,52" stroke="var(--color-hairline-strong)" strokeWidth="1.5"
        strokeDasharray="4 5" strokeLinecap="round" />
      <g stroke="var(--color-danger-text)" strokeWidth="1.5" strokeLinecap="round">
        <line x1="62" y1="18" x2="70" y2="30" />
        <line x1="70" y1="18" x2="62" y2="30" />
      </g>
      <circle cx="6" cy="58" r="2.5" fill="var(--color-data-2)" />
