}

/** Paths converging on a node that is now live. */
export function ConvergedNode(p: Props) {
  const u = useId().replace(/:/g, "");
  return (
    <Frame {...p}>
      <defs>
        <radialGradient id={`${u}-h`}>
          <stop offset="0%" stopColor="var(--color-success-text)" stopOpacity="0.42" />
          <stop offset="100%" stopColor="var(--color-success-text)" stopOpacity="0" />
        </radialGradient>
      </defs>
      <g stroke="var(--color-success-text)" strokeOpacity="0.5" strokeWidth="1.25" strokeLinecap="round">
        <path d="M8,18 C34,18 40,40 60,40" />
        <path d="M8,62 C34,62 40,40 60,40" />
        <path d="M112,26 C90,26 82,40 60,40" />
      </g>
      <circle cx="60" cy="40" r="20" fill={`url(#${u}-h)`} />
      <circle cx="60" cy="40" r="7" fill="var(--color-success-text)" />
      <path d="M56.5,40 l2.5,2.5 l5,-5.5" stroke="var(--color-base)" strokeWidth="1.6"
        strokeLinecap="round" strokeLinejoin="round" />
      {[[8, 18], [8, 62], [112, 26]].map(([x, y]) => (
        <circle key={`${x}-${y}`} cx={x} cy={y} r="2.5" fill="var(--color-data-2)" />
      ))}
    </Frame>
  );
}

/** Nodes assembling into an object — the provisioning illustration. */
export function Assembling(p: Props) {
  const u = useId().replace(/:/g, "");
  return (
    <Frame {...p}>
      <defs>
        <linearGradient id={`${u}-g`} x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%" stopColor="var(--color-brand-a)" />
          <stop offset="55%" stopColor="var(--color-brand-b)" />
          <stop offset="100%" stopColor="var(--color-brand-c)" />
        </linearGradient>
      </defs>
      <path d={NOTCH} stroke="var(--color-hairline-strong)" strokeWidth="1" />
      <path d="M14,1 L119,1" stroke={`url(#${u}-g)`} strokeWidth="1.5" />
      <g>
        <rect x="20" y="26" width="34" height="8" rx="2" fill="var(--color-brand-b)" fillOpacity="0.55" />
        <rect x="58" y="26" width="42" height="8" rx="2" fill="var(--color-hairline-strong)" />
        <rect x="20" y="42" width="56" height="8" rx="2" fill="var(--color-brand-c)" fillOpacity="0.4" />
        <rect x="80" y="42" width="20" height="8" rx="2" fill="var(--color-hairline-strong)" />
        <rect x="20" y="58" width="24" height="8" rx="2" fill="var(--color-hairline-strong)" />
      </g>
      <g className="animate-nx-node">
        <circle cx="104" cy="66" r="3" fill="var(--color-neon-cyan)" />
      </g>
    </Frame>
  );
}

/** A search that found nothing — a probe out into an empty field. */
export function EmptySearch(p: Props) {
  return (
    <Frame {...p}>
      <g stroke="var(--color-hairline-strong)" strokeWidth="1">
        {[20, 44, 68, 92].map((x) => <line key={x} x1={x} y1="10" x2={x} y2="70" strokeDasharray="2 6" />)}
      </g>
      <circle cx="52" cy="36" r="15" stroke="var(--color-brand-b)" strokeWidth="1.5" strokeOpacity="0.8" />
      <line x1="63" y1="47" x2="76" y2="60" stroke="var(--color-brand-c)" strokeWidth="1.75" strokeLinecap="round" />
      <circle cx="52" cy="36" r="2.5" fill="var(--color-ink-disabled)" />
    </Frame>
  );
}

