node -e '
function lin(c){c/=255;return c<=0.03928?c/12.92:Math.pow((c+0.055)/1.055,2.4)}
function lum(r,g,b){return 0.2126*lin(r)+0.7152*lin(g)+0.0722*lin(b)}
function cr(a,b){const[l1,l2]=[lum(...a),lum(...b)].sort((x,y)=>y-x);return ((l1+0.05)/(l2+0.05)).toFixed(2)}
const W=[255,255,255];
const hex=h=>{h=h.replace("#","");return [0,2,4].map(i=>parseInt(h.slice(i,i+2),16))}
const mix=(a,b,pa)=>a.map((v,i)=>Math.round(v*pa+b[i]*(1-pa)));
const A=hex("3b6be8"),B=hex("7b3fef"),C=hex("e5197e"),CY=hex("34e6ff"),BASE=hex("070b14");
console.log("white on brand-a:",cr(W,A));
console.log("white on brand-b:",cr(W,B));
console.log("white on brand-c:",cr(W,C));
console.log("white on neon-cyan:",cr(W,CY));
for(const p of [0.85,0.80,0.78,0.72]){const m=mix(C,BASE,p);console.log(`white on mix(c ${p*100}%, base): rgb(${m}) =`,cr(W,m));}
for(const p of [0.30,0.25,0.20]){const m=mix(CY,B,p);console.log(`white on mix(cyan ${p*100}%, brand-b): rgb(${m}) =`,cr(W,m));}
// signal button check
console.log("white on signal #1e63d6:",cr(W,hex("1e63d6")));
'

