// Screenshot every showcase entry at desktop/tablet/mobile.
// Usage: node shoot.mjs <outdir> [pageFilter...]
import { chromium } from "/opt/nxeon/node_modules/playwright-core/index.mjs";
import fs from "node:fs";

const OUT = process.argv[2] || "shots";
const only = process.argv.slice(3);
fs.mkdirSync(OUT, { recursive: true });

const PAGES = [
  "overview", "colour", "type", "surfaces", "icons", "motion",
  "buttons", "forms", "navigation", "data", "overlays", "states",
  "regions", "games", "loaders", "topology", "inventory", "detail",
  "checkout", "ladder", "setup",
];
const WIDTHS = { desktop: 1440, tablet: 768, mobile: 390 };

const browser = await chromium.launch({
  executablePath: "/root/.cache/ms-playwright/chromium-1234/chrome-linux/chrome",
  args: ["--no-sandbox"],
});

const pages = only.length ? PAGES.filter((p) => only.includes(p)) : PAGES;
const report = [];
for (const [wname, width] of Object.entries(WIDTHS)) {
  const ctx = await browser.newContext({ viewport: { width, height: 940 }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  await page.goto("http://127.0.0.1:3010/ds/design", { waitUntil: "networkidle" });
  for (const id of pages) {
    // navigate via the client-side switch: click the sidebar/bottom entry by evaluating state
    await page.evaluate((id) => {
      // find the nav button whose click sets this id — buttons carry the label text;
      // instead drive via a synthetic event: click matching rail button if visible
      const btns = [...document.querySelectorAll("button")];
      const map = {
        overview: "Overview", colour: "Colour", type: "Typography", surfaces: "Surfaces",
        icons: "Iconography", motion: "Motion", buttons: "Buttons", forms: "Forms",
        navigation: "Navigation", data: "Data display", overlays: "Overlays", states: "States",
        regions: "Region selector", games: "Game servers", loaders: "Deploy loaders",
        topology: "Topology", inventory: "Inventory", detail: "Resource detail",
        checkout: "Two-stage checkout", ladder: "Deployment ladder", setup: "Post-payment setup",
      };
      const label = map[id];
      const b = btns.find((x) => x.textContent.trim() === label);
      if (b) b.click();
    }, id);
    await page.waitForTimeout(700);
    // detect horizontal overflow
    const overflow = await page.evaluate(() => {
      const d = document.documentElement;
      const over = d.scrollWidth - d.clientWidth;
      const bad = [];
      if (over > 1) {
        for (const el of document.querySelectorAll("body *")) {
          const r = el.getBoundingClientRect();
          if (r.right - d.clientWidth > 2 && r.width > 30)
            bad.push(`${el.tagName}.${String(el.className).slice(0, 60)} right=${Math.round(r.right)}`);
          if (bad.length > 5) break;
        }
      }
      return { over, bad };
    });
    if (overflow.over > 1) report.push(`${wname}/${id}: OVERFLOW ${overflow.over}px :: ${overflow.bad.join(" | ")}`);
    await page.screenshot({ path: `${OUT}/${wname}-${id}.png`, fullPage: true });
  }
  await ctx.close();
}
await browser.close();
fs.writeFileSync(`${OUT}/overflow.txt`, report.join("\n") || "no horizontal overflow detected");
console.log(report.join("\n") || "no horizontal overflow detected");
console.log("done ->", OUT);

