        for (const el of document.querySelectorAll("body *")) {
          const r = el.getBoundingClientRect();
          if (r.right - d.clientWidth > 2 && r.width > 30)
            bad.push(`${el.tagName}.${String(el.className).slice(0, 60)} right=${Math.round(r.right)}`);
          if (bad.length > 5) break;
        }
      }
      return { over, bad };
    });
    if (overflow.over > 1) report.push(`${wname}/${id}: OVERFLOW ${overflow.over}px :: ${overflow.bad.join(" | ")}`);
    await page.screenshot({ path: `${OUT}/${wname}-${id}.png`, fullPage: true });
  }
  await ctx.close();
}
await browser.close();
fs.writeFileSync(`${OUT}/overflow.txt`, report.join("\n") || "no horizontal overflow detected");
console.log(report.join("\n") || "no horizontal overflow detected");
console.log("done ->", OUT);

