"use client";

/* ============================================================================
   TABS, SEGMENTED CONTROLS, STEPPERS, PROGRESS, WIZARD
   One tab mechanism for the product. The old portal had eight tab-bar styles
   plus eight one-off segmented rows, and its two most-used implementations
   rewrote the URL without adding history, so Back left the page.
   ========================================================================= */

import { useId, useRef, type ReactNode, type KeyboardEvent } from "react";
import { Icon, type IconName } from "./Icon";

/* ---------------------------------------------------------------- TABS */
export interface TabItem { id: string; label: string; icon?: IconName; badge?: string | number; disabled?: boolean }

/** Arrow keys move, Home and End jump, Enter and Space are implicit on a
    button. Roving tabindex, so the tab list is one stop in the page order. */
export function Tabs({
  items, active, onChange, ariaLabel = "Sections",
}: { items: TabItem[]; active: string; onChange: (id: string) => void; ariaLabel?: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const base = useId();

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const enabled = items.filter((i) => !i.disabled);
    const idx = enabled.findIndex((i) => i.id === active);
    let next = -1;
    if (e.key === "ArrowRight") next = (idx + 1) % enabled.length;
    else if (e.key === "ArrowLeft") next = (idx - 1 + enabled.length) % enabled.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = enabled.length - 1;
    if (next >= 0) {
      e.preventDefault();
      onChange(enabled[next].id);
      const el = ref.current?.querySelector<HTMLButtonElement>(`#${CSS.escape(`${base}-${enabled[next].id}`)}`);
      el?.focus();
    }
  };

  return (
    <div
      ref={ref}
      role="tablist"
      aria-label={ariaLabel}
      onKeyDown={onKeyDown}
      className="flex gap-0.5 overflow-x-auto border-b border-hairline"
    >
      {items.map((t) => {
        const on = t.id === active;
        return (
          <button
            key={t.id}
            id={`${base}-${t.id}`}
            role="tab"
            aria-selected={on}
            aria-controls={`${base}-panel-${t.id}`}
            tabIndex={on ? 0 : -1}
            disabled={t.disabled}
            onClick={() => onChange(t.id)}
            className={`relative -mb-px inline-flex shrink-0 items-center gap-2 whitespace-nowrap border-b-2 px-3.5 py-2.5 font-display text-body-sm font-semibold
              transition-colors duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
              disabled:cursor-not-allowed disabled:opacity-40
              ${on
                ? "border-signal-edge text-ink"
                : "border-transparent text-ink-muted hover:border-hairline-strong hover:text-ink-secondary"}`}
          >
            {t.icon && <Icon name={t.icon} size="md" />}
            {t.label}
            {t.badge !== undefined && (
              <span className="rounded-sm bg-interactive px-1.5 py-0.5 font-mono text-[0.6875rem] text-ink-secondary">
                {t.badge}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}

export function TabPanel({ id, active, children }: { id: string; active: string; children: ReactNode }) {
  if (id !== active) return null;
  return (
    <div role="tabpanel" className="animate-nx-fade pt-5">
      {children}
    </div>
  );
}

/* --------------------------------------------------- SEGMENTED CONTROL */
/** For switching a view of the same data — a time range, a density. Visually
    distinct from tabs on purpose: tabs change what you are looking at, a
    segment changes how. */
export function SegmentedControl<T extends string>({
  options, value, onChange, size = "md", ariaLabel,
}: {
  options: { value: T; label: string }[]; value: T; onChange: (v: T) => void;
  size?: "sm" | "md"; ariaLabel: string;
}) {
  return (
    <div
      role="group"
      aria-label={ariaLabel}
      className="inline-flex rounded-md border border-hairline bg-plate p-0.5"
    >
      {options.map((o) => {
        const on = o.value === value;
        return (
          <button
            key={o.value}
            type="button"
            aria-pressed={on}
            onClick={() => onChange(o.value)}
            className={`rounded-sm font-display font-semibold transition-colors duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
              ${size === "sm" ? "px-2 py-1 text-[0.75rem]" : "px-3 py-1.5 text-[0.8125rem]"}
              ${on ? "bg-interactive text-ink" : "text-ink-muted hover:text-ink-secondary"}`}
          >
            {o.label}
          </button>
        );
      })}
    </div>
  );
}

/* ------------------------------------------------------------- STEPPER */
export interface Step { id: string; label: string }

export function Stepper({ steps, current }: { steps: Step[]; current: number }) {
  return (
    <ol className="flex flex-wrap items-center gap-x-2 gap-y-2">
      {steps.map((s, i) => {
        const done = i < current;
        const now = i === current;
        return (
