const [collapsed, setCollapsed] = useState(false);
const [drawer, setDrawer] = useState(false);
const railRef = useRef<HTMLElement>(null);

useEffect(() => {
  const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") setDrawer(false); };
  document.addEventListener("keydown", onKey);
  return () => document.removeEventListener("keydown", onKey);
}, []);

/* The mobile drawer is a modal surface, so it behaves like one: focus
   moves in on open, Tab cycles inside it, and focus returns on close. */
useEffect(() => {
  if (!drawer) return;
  const rail = railRef.current;
  if (!rail) return;
  const restoreTo = document.activeElement as HTMLElement | null;
  const focusables = () =>
    Array.from(rail.querySelectorAll<HTMLElement>("button:not([disabled]),a[href]"))
      .filter((el) => el.offsetParent !== null);
  focusables()[0]?.focus();
  const onTab = (e: KeyboardEvent) => {
    if (e.key !== "Tab") return;
    const f = focusables();
    if (f.length === 0) return;
    const first = f[0], last = f[f.length - 1];
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
  };
  document.addEventListener("keydown", onTab, true);
  return () => {
    document.removeEventListener("keydown", onTab, true);
    restoreTo?.focus();
  };
}, [drawer]);

