  drawRef.current = draw;

  /* ---- run policy -------------------------------------------------------
     The loop costs real CPU for ~20k projected points, so it only runs
     while the canvas can actually be seen: on-screen, on a visible tab,
     and only for people who have not asked for reduced motion. Reduced
     motion gets a still frame; a paused globe repaints on select/resize. */
  let running = false, inView = false;

  const loop = () => { draw(); raf = requestAnimationFrame(loop); };
  const sync = () => {
    const should = inView && document.visibilityState === "visible" && !reduce;
    if (should && !running) { running = true; raf = requestAnimationFrame(loop); }
    else if (!should && running) { running = false; cancelAnimationFrame(raf); }
  };
  const io = new IntersectionObserver((entries) => {
    inView = entries[0]?.isIntersecting ?? false;
    sync();
  });
  io.observe(canvas);
  document.addEventListener("visibilitychange", sync);

  resize();
  const ro = new ResizeObserver(resize);
  ro.observe(wrap);
  draw(); // always paint at least one frame, spinning or not

  return () => {
    cancelAnimationFrame(raf);
    io.disconnect();
    ro.disconnect();
    document.removeEventListener("visibilitychange", sync);
    drawRef.current = null;
  };
}, [regions, height]);

