import { chromium } from "/opt/nxeon/node_modules/playwright-core/index.mjs";
const browser = await chromium.launch({
  executablePath: "/root/.cache/ms-playwright/chromium-1234/chrome-linux64/chrome",
  args: ["--no-sandbox"],
});

const nav = async (page, label) => {
  await page.evaluate((label) => {
    const b = [...document.querySelectorAll("button")].find((x) => x.textContent.trim() === label);
    b?.click();
  }, label);
  await page.waitForTimeout(600);
};

// ---- 1. rAF rate on the regions page: visible vs scrolled off-screen ----
{
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  await page.addInitScript(() => {
    window.__rafCount = 0;
    const orig = window.requestAnimationFrame.bind(window);
    window.requestAnimationFrame = (cb) => orig((t) => { window.__rafCount++; cb(t); });
  });
  await page.goto("http://127.0.0.1:3010/ds/design", { waitUntil: "networkidle" });
  await nav(page, "Region selector");
  const rate = async () => {
    const a = await page.evaluate(() => window.__rafCount);
    await page.waitForTimeout(1500);
    const b = await page.evaluate(() => window.__rafCount);
    return Math.round((b - a) / 1.5);
  };
  const visible = await rate();
  await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
  await page.waitForTimeout(400);
  const scrolled = await rate();
  console.log(`globe rAF/s while visible: ${visible}, while scrolled off-screen: ${scrolled}`);
  await ctx.close();
}

// ---- 2. reduced motion: loaders show static completed frames; globe still --
{
  const ctx = await browser.newContext({
    viewport: { width: 1440, height: 900 },
    reducedMotion: "reduce",
  });
  const page = await ctx.newPage();
  await page.addInitScript(() => {
    window.__rafCount = 0;
    const orig = window.requestAnimationFrame.bind(window);
    window.requestAnimationFrame = (cb) => orig((t) => { window.__rafCount++; cb(t); });
  });
  await page.goto("http://127.0.0.1:3010/ds/design", { waitUntil: "networkidle" });
  await nav(page, "Deploy loaders");
  await page.screenshot({ path: "reduced-loaders.png" });
  await nav(page, "Region selector");
  await page.waitForTimeout(800);
  const a = await page.evaluate(() => window.__rafCount);
  await page.waitForTimeout(1500);
  const b = await page.evaluate(() => window.__rafCount);
  console.log(`reduced-motion globe rAF/s: ${Math.round((b - a) / 1.5)} (should be ~0)`);
  await page.screenshot({ path: "reduced-regions.png" });
  await ctx.close();
}

// ---- 3. focus ring on clipped nx-object buttons (checkout plan cards) ----
{
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  await page.goto("http://127.0.0.1:3010/ds/design", { waitUntil: "networkidle" });
  await nav(page, "Two-stage checkout");
  // focus the Starter plan card via keyboard
  await page.evaluate(() => {
    const el = [...document.querySelectorAll("button.nx-object")].find((b) => b.textContent.includes("Starter"));
    el?.focus();
  });
  await page.keyboard.press("Tab"); // move once, then back — ensure focus-visible
  await page.evaluate(() => {
    const el = [...document.querySelectorAll("button.nx-object")].find((b) => b.textContent.includes("Starter"));
    el?.focus({ focusVisible: true });
  });
  await page.waitForTimeout(300);
  const card = await page.evaluateHandle(() =>
    [...document.querySelectorAll("button.nx-object")].find((b) => b.textContent.includes("Starter"))
  );
  await card.asElement().screenshot({ path: "focus-card.png" });
  // and the mobile drawer trap
  await ctx.close();
}

// ---- 4. mobile More-drawer focus trap ----
{
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 } });
  const page = await ctx.newPage();
  await page.goto("http://127.0.0.1:3010/ds/design", { waitUntil: "networkidle" });
  await page.click('button[aria-label="More"]');
  await page.waitForTimeout(500);
  const first = await page.evaluate(() => document.activeElement?.getAttribute("aria-label") || document.activeElement?.textContent?.trim());
  // Tab far more times than there are focusables — focus must stay inside the rail
  for (let i = 0; i < 40; i++) await page.keyboard.press("Tab");
  const inside = await page.evaluate(() => document.getElementById("nx-rail")?.contains(document.activeElement));
  await page.keyboard.press("Escape");
  await page.waitForTimeout(400);
  const restored = await page.evaluate(() => document.activeElement?.getAttribute("aria-label"));
  console.log(`drawer: initial focus="${first}", after 40 Tabs inside rail=${inside}, focus after Escape="${restored}"`);
  await ctx.close();
}

await browser.close();
console.log("verify done");

